:"រួមគ្នាកាន់តែរឹងមាំ។ យើងរីកចម្រើនជាមួយអតិថិជន ដៃគូ និងអ្នកផ្គត់ផ្គង់ តាមរយៈទំនាក់ទំនងរយៈពេលវែង ដែលផ្អែកលើទំនុកចិត្ត ការគោរព និងភាពជោគជ័យរួមគ្នា។"}]},"projects":{"titleLines":["គម្រោង","ជ្រើសរើស"],"ctaLabel":"មើលគម្រោងទាំងអស់"},"coverage":{"titleLines":["គ្រប់ទីកន្លែងដែលអ្នកសាងសង់,","យើងនៅទីនោះជាមួយអ្នក។"],"imageAlt":"វិស្វករ និងក្រុមការងាររបស់ BCE នៅលើកម្រាលបេតុងក្នុងប្រទេសកម្ពុជា","intro":"យើងទៅដល់គ្រប់ទីកន្លែងដែលអ្នកសាងសង់។ ជាមួយសមត្ថភាពគ្រឿងចក្រខ្លាំង ក្រុមការងារមានបទពិសោធន៍ និងការសម្របសម្រួលដែលអាចទុកចិត្តបាន យើងគាំទ្រគម្រោងនៅទូទាំង ១៣ ខេត្ត និងរាជធានីភ្នំពេញ។","hint":"ចុចលើខេត្តមួយ ដើម្បីមើលព័ត៌មានលម្អិត","story":[{"label":"តំបន់ប្រតិបត្តិការ","lead":"ទីតាំងដែលយើងគ្របដណ្តប់ទូទាំងកម្ពុជា"},{"label":"ឆ្នាំនៃបទពិសោធន៍","lead":"កសាងពីបាត់ដំបងតាំងពីឆ្នាំ ១៩៩៥"},{"label":"គម្រោងបានបញ្ចប់","lead":"គម្រោងបានបញ្ចប់ក្នុងឆ្នាំ ២០២៥ នៅទូទាំងប្រទេសកម្ពុជា"},{"label":"កងយានយន្ត និងគ្រឿងចក្រ","lead":"គ្រឿងចក្ររបស់យើងផ្ទាល់"}],"fleetNote":"បូករួមទាំងម៉ាស៊ីនបោះសសរស្ដម្ភផ្ទាល់ខ្លួន។","credit":"ព្រំដែន © អ្នករួមចំណែក OpenStreetMap · គម្រោងដែលបានបញ្ចប់ទូទាំងកម្ពុជា"},"why":{"eyebrow":"ហេតុអ្វីជ្រើសរើស BCE","beliefs":[{"word":"គុណភាព","tag":"ត្រួតពិនិត្យគ្រប់ដំណាក់កាល"},{"word":"សមត្ថភាព","tag":"រោងចក្រ និងគ្រឿងចក្រផ្ទាល់ខ្លួន"},{"word":"ទំនុកចិត្ត","tag":"ដៃគូរយៈពេលវែង"}]},"quote":{"image":"/Image/bce/hero_batching_plant.webp","title":"កំពុងរៀបចំគម្រោង? ស្នើសុំសម្រង់តម្លៃ","text":"ប្រាប់យើងអំពីទីតាំង វិសាលភាពការងារ និងកាលវិភាគរបស់អ្នក សម្រាប់បេតុងលាយស្រេច ការបោះសសរស្ដម្ភ សំណង់ ការងារចាក់កម្រាល ឬការជួលគ្រឿងចក្រ។ វិស្វកររបស់យើងនឹងផ្ញើសម្រង់តម្លៃច្បាស់លាស់ពីរោងចក្រ និងគ្រឿងចក្រផ្ទាល់ខ្លួនរបស់យើង។","ctaLabel":"ស្នើសុំសម្រង់តម្លៃ"},"footer":{"columns":[{"title":"ក្រុមហ៊ុន","links":[{"label":"ទំព័រដើម"},{"label":"អំពី BCE"},{"label":"គម្រោង"},{"label":"ប្លុក & ចំណេះដឹងបច្ចេកទេស"},{"label":"តំបន់សេវាកម្ម"},{"label":"ឯកសារ & ទាញយក"}]},{"title":"អាជីវកម្មរបស់យើង","links":[{"label":"បេតុងលាយស្រេច"},{"label":"ការបោះសសរស្ដម្ភ"},{"label":"សំណង់ស៊ីវិល"},{"label":"ការងារចាក់កម្រាលបេតុង"},{"labe