VALUES ('partners:home', 'partners', 'home', 'published', 0, '{"title":"Clients & partners","slug":"home","kicker":"Clients & partners","titleLines":["Strong relationships.","Shared success."],"intro":"BCE has built long-term working relationships across Cambodia’s public and private sectors. Our network includes government and public institutions, contractors, development and strategic partners, corporate clients, and key suppliers who contribute to the successful delivery of our projects and services.","registerNote":"The full register, as published in BCE’s Corporate Profile 2026.","footnote":"Organisations and individuals listed as published in the BCE Corporate Profile 2026. Names and marks belong to their respective owners.","groups":[{"id":"government","label":"Government & public sector","shortLabel":"Government & public sector","note":"Public institutions · Authorities · Government projects","items":[{"name":"Ministry of Water Resources and Meteorology","logo":"/assets/partners/mowram.png","featured":true},{"name":"Ministry of Land Management, Urban Planning and Construction","logo":"/assets/partners/mlmupc.png","featured":true},{"name":"Ministry of Commerce","logo":"/assets/partners/moc.png","featured":true},{"name":"Ministry of Mines and Energy"},{"name":"Ministry of Public Works and Transport","logo":"/assets/partners/mpwt.png","featured":true},{"name":"Ministry of Labour and Vocational Training"},{"name":"Ministry of Industry, Science, Technology & Innovation"},{"name":"Ministry of Rural Development","logo":"/assets/partners/mrd.png","featured":true},{"name":"Ministry of Economy and Finance"},{"name":"Ministry of Interior"},{"name":"General Department of Tax"},{"name":"National Social Security Fund (NSSF)"},{"name":"Building and Public Works Laboratory"},{"name":"Ministry of National Defence"},{"name":"Provincial Halls in Provinces Where BCE Operates","featured":true},{"name":"Provincial Administrations in BCE’s Operational Areas"}]},{"id":"clients","la