"},{"name":"Almond Company"},{"name":"Veng Srun"},{"name":"Ye Yaqing"},{"name":"Cambodia Cement Chakrey Ting Factory Co., Ltd."},{"name":"Hong Huot Ly Co., Ltd.","featured":true},{"name":"Battambang Conch Cement Co. Ltd.","logo":"/assets/partners/conch.jpg","featured":true},{"name":"SCG Distribution and Retail Co., Ltd.","logo":"/assets/partners/scg.png","featured":true},{"name":"Rong Sheng Jilong Chemicals Co., Ltd."},{"name":"Sika Cambodia","logo":"/assets/partners/sika.png","featured":true},{"name":"Leng Seng Na"},{"name":"Mitapheap"}]}]}', '{"kicker":"អតិថិជន និងដៃគូ","titleLines":["ទំនាក់ទំនងរឹងមាំ។","ជោគជ័យរួមគ្នា។"],"intro":"BCE បានកសាងទំនាក់ទំនងការងាររយៈពេលវែងជាមួយវិស័យសាធារណៈ និងឯកជនទូទាំងប្រទេសកម្ពុជា។ បណ្តាញរបស់យើងរួមមាន ស្ថាប័នរដ្ឋាភិបាល និងសាធារណៈ ក្រុមហ៊ុនម៉ៅការ ដៃគូអភិវឌ្ឍន៍ និងយុទ្ធសាស្ត្រ អតិថិជនសាជីវកម្ម និងអ្នកផ្គត់ផ្គង់សំខាន់ៗ ដែលរួមចំណែកដល់ការអនុវត្តគម្រោង និងសេវាកម្មរបស់យើងដោយជោគជ័យ។","registerNote":"បញ្ជីពេញលេញ ដូចដែលបានចេញផ្សាយក្នុងប្រវត្តិរូបក្រុមហ៊ុន BCE ២០២៦។","footnote":"អង្គភាព និងបុគ្គលដែលបានចុះក្នុងប្រវត្តិរូបក្រុមហ៊ុន BCE ២០២៦។ ឈ្មោះ និងសញ្ញាសម្គាល់ជាកម្មសិទ្ធិរបស់ម្ចាស់រៀងៗខ្លួន។","groups":[{"label":"រដ្ឋាភិបាល និងវិស័យសាធារណៈ","shortLabel":"រដ្ឋាភិបាល","note":"ស្ថាប័នសាធារណៈ · អាជ្ញាធរ · គម្រោងរដ្ឋាភិបាល","items":[{"name":"ក្រសួងធនធានទឹក និងឧតុនិយម"},{"name":"ក្រសួងរៀបចំដែនដី នគរូបនីយកម្ម និងសំណង់"},{"name":"ក្រសួងពាណិជ្ជកម្ម"},{"name":"ក្រសួងរ៉ែ និងថាមពល"},{"name":"ក្រសួងសាធារណការ និងដឹកជញ្ជូន"},{"name":"ក្រសួងការងារ និងបណ្តុះបណ្តាលវិជ្ជាជីវៈ"},{"name":"ក្រសួងឧស្សាហកម្ម វិទ្យាសាស្ត្រ បច្ចេកវិទ្យា និងនវានុវត្តន៍"},{"name":"ក្រសួងអភិវឌ្ឍន៍ជនបទ"},{"name":"ក្រសួងសេដ្ឋកិច្ច និងហិរញ្ញវត្ថុ"},{"name":"ក្រសួងមហាផ្ទៃ"},{"name":"អគ្គនាយកដ្ឋានពន្ធដារ"},{"name":"មូលនិធិសន្តិសុខសង្គមជាតិ (NSSF)"},{"name":"មន្ទីរពិសោធន៍សំណង់ និងការងារសាធារណៈ"},{"name":"ក្រសួងការពារជាតិ"},{"name":"សាលាខេត្ត នៅតាមខេត្តដែល BCE ដំណើរការ"},{"name":"រដ្ឋបាលខេត្ត នៅតាមតំបន់ប្រតិបត្តិការរបស់ BCE"}]},{"label":"ក្រុមហ៊ុនម៉ៅការ ដៃគូ និងអតិថិជនសាជីវកម្ម","shortLabel":"អតិថិជន","note":"ក្រុមហ៊ុនម៉ៅការ · ដៃគូអភិវឌ្ឍន៍ និងយុទ្ធសាស្ត្រ · អតិថិជនសាជីវកម្ម"},{"label":"អ្នកផ្គត់ផ្គង់សំខាន់","shortLabel":"អ្នកផ្គត់ផ្គង់","note":"វត្ថុធាតុដើម · ឧបករណ៍ · ការគាំទ្រប្រតិបត្តិការ"}],"slug":"home"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
