INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('quality:home', 'quality', 'home', 'published', 0, '{"cover":{"label":"Quality, capability & HSE","title":"Tested at every stage, built safely","image":"/Image/bce/photos/road-crew.webp","imageAlt":"BCE site crew in protective equipment placing and finishing concrete"},"intro":{"label":"Our approach","text":"Behind every BCE project is the capability to test, design and deliver concrete in-house: a quality process on every pour, our own laboratory, approved mix designs, certified materials, a fleet we own and maintain, and the engineers who bring it together."},"laboratory":{"title":"Laboratory & quality assurance","copy":"Strict quality control at every stage, with slump, strength and material testing at the plant and on site. Our own laboratory checks the materials that go into our concrete, the concrete as it leaves the plant and the strength it reaches once cured.","listLabel":"Our quality process","steps":[{"title":"Material check","text":"Every material checked before production."},{"title":"Batching","text":"Weighed and mixed to the approved design."},{"title":"Slump test","text":"Tested on delivery, before placing."},{"title":"Strength test","text":"Samples cured and tested in our lab."},{"title":"Verification","text":"Results checked and recorded."}],"tests":[{"label":"Slump testing","value":"Every delivery"},{"label":"Compressive strength","value":"7- and 28-day cubes"},{"label":"Aggregate grading","value":"Sieve analysis"},{"label":"Silt and moisture content","value":"Fine and coarse aggregate"},{"label":"Trial mixes","value":"For every new design"}],"image":"/Image/bce/cert_mix_design.webp","imageAlt":"Concrete test specimens side by side"},"materials":{"title":"Raw material certificates","copy":"Every material is certified at source and checked again before production, with certificates on file for each batch.","listLabel":"Certified materials","items":[{"name":"Cement","certificate":"Mill test certificate"},{"name":"Sand","certificate":"Grading and silt tests"},{"name":"Coarse aggregate","certificate":"Grading and crushing value"},{"name":"Admixtures","certificate":"Compliance certificate"},{"name":"Water","certificate":"Water quality tests"},{"name":"Steel","certificate":"Mill certificates"}],"image":"/Image/bce/project_page_14.webp","imageAlt":"Concrete specimens and raw materials"},"calibration":{"title":"Calibration certificates","copy":"The scales, meters and testing machines behind every result are calibrated on schedule, with certificates on file.","listLabel":"Calibrated equipment","items":[{"equipment":"Batching plant weigh scales","scope":"Cement, aggregate, water and admixture scales"},{"equipment":"Compression testing machine","scope":"Load calibration for cube and cylinder testing"},{"equipment":"Admixture dispensers","scope":"Dosing accuracy"},{"equipment":"Water meters","scope":"Flow accuracy at the batching plants"},{"equipment":"Laboratory equipment","scope":"Balances, slump cones and cube moulds"}]},"hse":{"label":"HSE commitment","heading":"HSE commitment: protecting people, working safely, respecting the environment","items":[{"lines":["Protecting","people"],"text":"We protect our people, our partners and the communities around every project we undertake.","image":"/Image/bce/hse_safety.webp","imageAlt":"BCE safety standards and protective equipment on site"},{"lines":["Working","safely"],"text":"Safe operations and a well-maintained fleet, run by a skilled and experienced team.","image":"/Image/bce/core_services.webp","imageAlt":"A site worker in an orange hard hat supervising pour"},{"lines":["Respecting","the environment"],"text":"We build today while protecting resources for future generations, through environmental responsibility and resource efficiency.","image":"/Image/bce/project_page_16.webp","imageAlt":"Environmental protection and clean site practices"},{"lines":["Delivering","quality"],"text":"Built to last. From certified batching to precision placement, laboratory quality control ensures every structure remains strong, durable and enduring.","image":"/Image/bce/cert_mix_design.webp","imageAlt":"A calibrated pressure gauge and quality testing"},{"lines":["Building","trust"],"text":"Stronger together. We grow alongside our clients, partners and suppliers through long-term relationships built on trust, respect and mutual success.","image":"/Image/bce/project_page_17.webp","imageAlt":"Construction engineering team collaborating on site"}]},"hsePractice":{"label":"HSE in practice","title":"Standards, PPE and inspections","copy":"Safety and quality here are routines, not posters: what we test to, what every crew wears, what we check each shift.","standards":[{"method":"ASTM C143","use":"Slump on every delivery"},{"method":"ASTM C31 / C39","use":"Specimens made, cured, crushed"},{"method":"BS EN 206","use":"Specification and conformity"},{"method":"ISO 9001","use":"Procedures and records"}],"ppe":["Hard hat and high-vis, every site","Boots, eye protection and gloves","Harness for work at height","Dust and hearing protection","Life jackets over water"],"inspections":["Pre-start checks, recorded daily","Lifting gear and rigging, tagged","Pump lines and outriggers, every setup","Toolbox talks before each pour","Incidents and near misses, closed out"]},"engineering":{"kicker":"People behind every project","title":"Engineering capability","image":"/Image/bce/stats_fleet.webp","imageAlt":"An engineer inspecting reinforcement on site","copy":["Our engineers plan, design and supervise every project, from mix design and piling programmes to site supervision and handover records."],"rows":[{"label":"Engineers","value":"15"},{"label":"Team","value":"71"},{"label":"Building since","value":"1995"},{"label":"Coverage","value":"13 provinces + Phnom Penh"}]},"fleet":{"kicker":"Our own fleet","title":"Equipment & fleet","image":"/Image/bce/about-zoom-boom-pumps.webp","imageAlt":"BCE pump trucks and mixer trucks placing concrete on site","copy":["Our plants and fleet are owned, operated and maintained by our own team, so capacity is planned around your programme rather than a supplier''s."],"note":"Equipment is dispatched from Battambang and mobilised to projects across 13 provinces and Phnom Penh. Hire is quoted per project: machine, duration, site access and whether an operator is included.","figuresLabel":"What we own, in numbers.","figuresTitle":"Capacity you can plan around.","jobsLabel":"Fleet by job","jobsTitle":"One fleet, four ways to build.","jobsCopy":"The same owned fleet carries BCE''s concrete, piling, lifting and site-support work. Counts are above; here is what each group is for.","jobs":[{"title":"Concrete production & delivery","text":"Ready-mix from our own batching plants, tested before it leaves and delivered by our own mixer fleet.","icon":"plant","bullets":["Ready-mix from our own batching plants","Mixer trucks on a planned dispatch","Laboratory-tested on every pour","Delivery across 13 provinces + Phnom Penh"],"image":"/Image/bce/fleet/03-mixer.jpg","imageAlt":"BCE concrete mixer truck at the plant"},{"title":"Concrete placing","text":"Boom pumps and operators place concrete where mixers cannot reach, working to the pour sequence.","icon":"pump","bullets":["Boom pumps for high-reach pours","Placement where mixers cannot reach","Operators work to the pour sequence","Pump lines checked at every setup"],"image":"/Image/bce/fleet/02-pump.jpg","imageAlt":"BCE pump truck with its boom folded"},{"title":"Foundations","text":"Reinforced concrete piles installed and tested by our own rigs and crews, from platform to pile cap.","icon":"rig","bullets":["Reinforced concrete piles","Bridge, road and building foundations","Own rigs and installation crews","Pile records handed over"],"image":"/Image/bce/fleet/05-piling.jpg","imageAlt":"BCE piling rig working on a foundation site"},{"title":"Lifting & site support","text":"Crane trucks, tower cranes, lifts and wheel loaders keep the site moving, with operators and inspection records.","icon":"crane","bullets":["Crane trucks and tower cranes","Wheel loaders for material handling","Lifts for work at height","Operators and inspection records"],"image":"/Image/bce/fleet/06-crane-truck.jpg","imageAlt":"Crane truck lifting on a BCE site"}],"maintenanceLabel":"Maintenance & operators","maintenanceTitle":"Ready when it reaches site.","maintenance":[{"icon":"wrench","title":"Serviced in our workshop","text":"Trucks, pumps and rigs are maintained by our own team between projects, not sent to a third-party yard."},{"icon":"helmet","title":"Operators included","text":"Experienced drivers and operators come with the machine and work to your pour or piling sequence."},{"icon":"shield","title":"Checked before dispatch","text":"Pre-start checks, lifting gear and pump lines are inspected and recorded before the machine leaves."},{"icon":"pin","title":"Mobilised from Battambang","text":"Equipment is dispatched from our base to 13 provinces and Phnom Penh, with mobilisation quoted per project."}],"rows":[{"label":"Batching plants","value":"04  /  70 m³/hr each","note":"70 m³/hr each"},{"label":"Mixer trucks","value":"41","note":"13 provinces + Phnom Penh"},{"label":"Pump trucks","value":"08","note":"Placing and boom pumps"},{"label":"Wheel loaders","value":"07","note":"Loading and material handling"},{"label":"Piling rigs","value":"07","note":"Bore and hammer rigs"},{"label":"Crane trucks","value":"06","note":"Lifting on site"},{"label":"Tower cranes","value":"08","note":"High-rise construction"},{"label":"Lifts","value":"05","note":"Work at height"}],"ctaLabel":"Hire our equipment","ctaHref":"/quote?service=equipment-rental"},"documents":{"label":"Quality documents","title":"Mix designs & certification","text":"The mix designs behind every grade, and the licences, certificates and company profile that procurement and tender teams ask for.","items":[{"title":"Company profile","subtitle":"BCE Corporate Profile 2026","status":"","date":"2026","size":"8.4 MB","file":"/assets/BCE_Corporate_Profile_2026_web.pdf"},{"title":"Mix design documents","subtitle":"Supplied with every mix design","status":"On request","date":"","size":"","file":""},{"title":"Business licence & registration","subtitle":"Ministry of Commerce","status":"On request","date":"","size":"","file":""},{"title":"Construction licence","subtitle":"Ministry of Land Management, Urban Planning and Construction","status":"On request","date":"","size":"","file":""},{"title":"Tax registration (VAT) certificate","subtitle":"General Department of Taxation","status":"On request","date":"","size":"","file":""}],"gradesText":"From blinding and mass fill to bridges and heavy structures, every grade is designed, trial-mixed and tested in our own laboratory before it reaches site.","grades":[{"grade":"C15","strength":"15 MPa","use":"Blinding and mass fill"},{"grade":"C20","strength":"20 MPa","use":"Ground slabs and paths"},{"grade":"C25","strength":"25 MPa","use":"Floor slabs and footings"},{"grade":"C30","strength":"30 MPa","use":"Columns, beams and suspended slabs"},{"grade":"C35","strength":"35 MPa","use":"Foundations and piles"},{"grade":"C40","strength":"40 MPa","use":"Bridges and heavy structures"}],"note":"Characteristic cube strength at 28 days. Other grades and special mixes designed on request.","ctaLabel":"Request documents","ctaHref":"#contact"},"title":"Quality & HSE","slug":"home"}', '{"cover":{"label":"គុណភាព សមត្ថភាព និង HSE","title":"តេស្តគ្រប់ដំណាក់កាល សាងសង់ដោយសុវត្ថិភាព","imageAlt":"ក្រុមការងារការដ្ឋាន BCE ក្នុងឧបករណ៍ការពារខ្លួន កំពុងចាក់ និងបញ្ចប់បេតុង"},"intro":{"label":"វិធីសាស្ត្ររបស់យើង","text":"នៅពីក្រោយគម្រោងនីមួយៗរបស់ BCE គឺសមត្ថភាពក្នុងការតេស្ត រចនា និងផ្គត់ផ្គង់បេតុងដោយខ្លួនឯង៖ ដំណើរការត្រួតពិនិត្យគុណភាពលើរាល់ការចាក់បេតុង មន្ទីរពិសោធន៍ផ្ទាល់ខ្លួន រូបមន្តលាយបេតុងដែលបានអនុម័ត វត្ថុធាតុដើមដែលមានការបញ្ជាក់គុណភាព កងរថយន្តដែលយើងកាន់កាប់ និងថែទាំដោយខ្លួនឯង ព្រមទាំងវិស្វករដែលភ្ជាប់អ្វីៗទាំងអស់នេះចូលគ្នា។"},"laboratory":{"title":"មន្ទី