 និងការគាំទ្រការដ្ឋានរបស់ BCE។ ចំនួនមាននៅខាងលើ។ ខាងក្រោមនេះជាគោលបំណងរបស់ក្រុមនីមួយៗ។","jobs":[{"title":"ផលិតកម្ម និងការដឹកជញ្ជូនបេតុង","text":"បេតុងលាយស្រេចពីរោងចក្រលាយបេតុងផ្ទាល់ខ្លួន តេស្តរួចមុនពេលចេញ និងដឹកជញ្ជូនដោយកងរថយន្តលាយបេតុងរបស់យើង។","bullets":["បេតុងលាយស្រេចពីរោងចក្រលាយបេតុងផ្ទាល់ខ្លួន","រថយន្តលាយបេតុងតាមកាលវិភាគបញ្ជូនដែលបានគ្រោងទុក","តេស្តនៅមន្ទីរពិសោធន៍លើរាល់ការចាក់បេតុង","ការដឹកជញ្ជូនគ្រប់ 13 ខេត្ត + រាជធានីភ្នំពេញ"],"imageAlt":"រថយន្តលាយបេតុងរបស់ BCE នៅរោងចក្រ"},{"title":"ការចាក់បេតុង","text":"រថយន្តបូមបេតុង និងអ្នកបើកបរ ចាក់បេតុងទៅកន្លែងដែលរថយន្តលាយបេតុងមិនអាចឈានដល់ ដោយអនុវត្តតាមលំដាប់នៃការចាក់បេតុង។","bullets":["រថយន្តបូមបេតុងសម្រាប់ការចាក់នៅកម្ពស់ខ្ពស់","ការចាក់នៅកន្លែងដែលរថយន្តលាយបេតុងមិនអាចឈានដល់","អ្នកបើកបរអនុវត្តតាមលំដាប់នៃការចាក់បេតុង","បន្ទាត់បូមត្រូវបានត្រួតពិនិត្យរាល់ការដំឡើង"],"imageAlt":"រថយន្តបូមបេតុងរបស់ BCE ដោយបត់ដងបូមចូល"},{"title":"គ្រឹះ","text":"សសរស្ដម្ភបេតុងពង្រឹងកម្លាំង ត្រូវបានដំឡើង និងតេស្តដោយម៉ាស៊ីន និងក្រុមការងារផ្ទាល់ខ្លួន ចាប់ពីវេទិការហូតដល់ក្បាលសសរ។","bullets":["សសរស្ដម្ភបេតុងពង្រឹងកម្លាំង","គ្រឹះស្ពាន ផ្លូវ និងអគារ","ម៉ាស៊ីន និងក្រុមការងារដំឡើងផ្ទាល់ខ្លួន","កំណត់ត្រាសសរស្ដម្ភប្រគល់ជូន"],"imageAlt":"ម៉ាស៊ីនបោះសសរស្ដម្ភរបស់ BCE កំពុងធ្វើការនៅការដ្ឋានគ្រឹះ"},{"title":"ការលើក និងការគាំទ្រការដ្ឋាន","text":"រថយន្តស្ទូច ស្ទូចប៉ម ជណ្តើរយន្ត និងរថយន្តផ្ទុក ធ្វើឲ្យការដ្ឋានដំណើរការទៅមុខ ជាមួយអ្នកបើកបរ និងកំណត់ត្រាត្រួតពិនិត្យ។","bullets":["រថយន្តស្ទូច និងស្ទូចប៉ម","រថយន្តផ្ទុកសម្រាប់ការគ្រប់គ្រងវត្ថុធាតុ","ជណ្តើរយន្តសម្រាប់ការងារនៅកម្ពស់","អ្នកបើកបរ និងកំណត់ត្រាត្រួតពិនិត្យ"],"imageAlt":"រថយន្តស្ទូចកំពុងលើកនៅការដ្ឋាន BCE"}],"maintenanceLabel":"ការថែទាំ និងអ្នកបើកបរ","maintenanceTitle":"ត្រៀមរួចរាល់ ពេលដល់ការដ្ឋាន។","maintenance":[{"title":"ថែទាំនៅសិក្ខាសាលារបស់យើង","text":"រថយន្ត ម៉ាស៊ីនបូម និងម៉ាស៊ីនបោះសសរស្ដម្ភ ត្រូវបានថែទាំដោយក្រុមការងារផ្ទាល់ខ្លួនរវាងគម្រោងនីមួយៗ មិនមែនបញ្ជូនទៅអាងខាងក្រៅទេ។"},{"title":"រួមបញ្ចូលអ្នកបើកបរ","text":"អ្នកបើកបរដែលមានបទពិសោធន៍មកជាមួយម៉ាស៊ីន ហើយអនុវត្តតាមលំដាប់នៃការចាក់បេតុង ឬការបោះសសរស្ដម្ភរបស់អ្នក។"},{"title":"ត្រួតពិនិត្យមុនការបញ្ជូន","text":"ការត្រួតពិនិត្យមុនចាប់ផ្តើម ឧបករណ៍លើក និងបន្ទាត់បូម ត្រូវបានត្រួតពិនិត្យ និងកត់ត្រាមុនពេលម៉ាស៊ីនចេញ។"},{"title":"ដឹកជញ្ជូនចេញពីបាត់ដំបង","text":"គ្រឿងចក្រត្រូវបានបញ្ជូនចេញពីមូលដ្ឋានរបស់យើងទៅ 13 ខេត្ត និងរាជធានីភ្នំពេញ ដោយការដឹកជញ្ជូនត្រូវបានវាយតម្លៃតាមគម្រោង។"}],"rows":[{"label":"រោងចក្រលាយបេតុង","value":"04  /  70 m³/hr ក្នុងមួយរោងចក្រ","note":"70 m³/hr ក្នុងមួយរោងចក្រ"},{"label":"រថយន្តលាយបេតុង","value":"41","note":"13 ខេត្ត + រាជធានីភ្នំពេញ"},{"label":"រថយន្តបូមបេតុង","value":"08","note":"រថយន្តបូមសម្រាប់ចាក់ និងបូមដងវែង"},{"label":"រថយន្តផ្ទុក","value":"07","note":"ការផ្ទុក និងការគ្រប់គ្រងវត្ថុធាតុ"},{"label":"ម៉ាស៊ីនបោះសសរស្ដម្ភ","value":"07","note":"ម៉ាស៊ីនខួង និងម៉ាស៊ីនញញួរ"},{"label":"រថយន្តស្ទូច","value":"06","note":"ការលើកនៅការដ្ឋាន"},{"label":"ស្ទូចប៉ម","value":"08","note":"សំណង់អគារខ្ពស់"},{"label":"ជណ្តើរយន្ត","value":"05","note":"ការងារនៅកម្ពស់"}],"ctaLabel":"ជួលគ្រឿងចក្ររបស់យើង"},"documents":{"label":"ឯកសារគុណភាព","title":"រូបមន្តលាយបេតុង និងការបញ្ជាក់គុណភាព","text":"រូបមន្តលាយបេតុងនៅពីក្រោយរាល់កម្រិត ព្រមទាំងអាជ្ញាបណ្ណ វិញ្ញាបនបត្រ និងប្រវត្តិក្រុមហ៊ុន ដែលក្រុមលទ្ធកម្ម និងក្រុមដេញថ្លៃត្រូវការ។","items":[{"title":"ប្រវត្តិក្រុមហ៊ុន","subtitle":"ប្រវត្តិក្រុមហ៊ុន BCE 2026","status":""},{"title":"ឯកសាររូបមន្តលាយបេតុង","subtitle":"ផ្តល់ជូនជាមួយរូបមន្តលាយបេតុងនីមួយៗ","status":"តាមការស្នើសុំ"},{"title":"អាជ្ញាបណ្ណអាជីវកម្ម និងការចុះបញ្ជី","subtitle":"ក្រសួងពាណិជ្ជកម្ម","status":"តាមការស្នើសុំ"},{"title":"អាជ្ញាបណ្ណសំណង់","subtitle":"ក្រសួងរៀបចំដែនដី នគរូបនីយកម្ម និងសំណង់","status":"តាមការស្នើសុំ"},{"title":"វិញ្ញាបនបត្រចុះបញ្ជីពន្ធ (VAT)","subtitle":"អគ្គនាយកដ្ឋានពន្ធដារ","status":"តាមការស្នើសុំ"}],"gradesText":"ចាប់ពីបេតុងស្តើងលើដី និងការបំពេញដីបរិមាណច្រើន រហូតដល់ស្ពាន និងរចនាសម្ព័ន្ធធ្ងន់ រាល់កម្រិតត្រូវបានរចនា លាយសាកល្បង និងតេស្តនៅមន្ទីរពិសោធន៍ផ្ទាល់ខ្លួន មុនពេលដឹកជញ្ជូនទៅការដ្ឋាន។","grades":[{"use":"បេតុងស្តើងលើដី និងការបំពេញដីបរិមាណច្រើន"},{"use":"កម្រាលបេតុងលើដី និងផ្លូវដើរ"},{"use":"កម្រាលបេតុងជាន់ និងគ្រឹះជើងសសរ"},{"use":"សសរ ធ្នឹម និងកម្រាលបេតុងព្យួរ"},{"use":"គ្រឹះ និងសសរស្ដម្ភ"},{"use":"ស្ពាន និងរចនាសម្ព័ន្ធធ្ងន់"}],"note":"កម្លាំងសង្កត់លក្ខណៈរបស់គូបនៅអាយុ 28 ថ្ងៃ។ កម្រិតផ្សេងទៀត និងល្បាយពិសេស ត្រូវបានរចនាតាមការស្នើសុំ។","ctaLabel":"ស្នើសុំឯកសារ"}}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
