INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('about:home', 'about', 'home', 'published', 0, '{"cover":{"label":"Who we are","title":"About BCE","image":"/Image/bce/about-hero-banner.webp","imageAlt":"Aerial view of a BCE batching plant and aggregate yard"},"intro":{"text":"Battambang Construction and Engineering, Co., Ltd. (BCE) is a Battambang-based construction, concrete, piling and engineering company, supplying ready-mix concrete, reinforced concrete piling and civil construction to projects across Cambodia with its own plants, fleet and a team of 71.","primaryLabel":"Download Company Profile (PDF)","primaryHref":"/assets/BCE_Corporate_Profile_2026_web.pdf","secondaryLabel":"View all resources","secondaryHref":"/resources"},"message":{"quote":"For more than thirty years we have built on four pillars: quality, safety, reliability and partnership. They guide every pour, every pile and every project.","attribution":"Chairwoman, BCE., Ltd."},"story":{"title":"Our story","text":"Founded in Battambang in 1995, BCE has grown into an integrated operation, delivering concrete, piling, construction, slab works and equipment rental with its own plants and fleet.","milestones":[{"year":"1995","title":"Foundation","text":"BCE begins in Battambang as Hong Huot Ly Co., Ltd., supplying concrete and construction services to projects across the province.","image":"/Image/bce/about-hero-banner.webp","imageAlt":"Aerial view of the batching plant and aggregate yard BCE started from"},{"year":"2015","title":"Restructured for growth","text":"The company is restructured into its current organisation, bringing batching, piling and civil works under one management team.","image":"/Image/bce/about-zoom-batching.webp","imageAlt":"Batching plant and aggregate stockpiles"},{"year":"2018","title":"Modern plant and fleet","text":"Computerized batching and a larger mixer and pump fleet expand capacity beyond Battambang.","image":"/Image/bce/machinery_fleet.webp","imageAlt":"BCE mixer and pump trucks lined up at the plant"},{"year":"2020","title":"Incorporated as BCE","text":"The business is incorporated as Battambang Construction and Engineering Co., Ltd. (BCE).","image":"/Image/bce/about-business-banner.webp","imageAlt":"BCE engineers and crew on site in Battambang"},{"year":"2023","title":"Laboratory and quality system","text":"An in-house materials laboratory and formal mix-design records bring testing and quality control under one roof.","image":"/Image/bce/laboratory_qa.webp","imageAlt":"Concrete test specimens in the BCE laboratory"},{"year":"2024","title":"Partnerships and coverage","text":"Long-term supply and technical partnerships extend deliveries across 13 provinces and Phnom Penh.","image":"/Image/bce/core_services.webp","imageAlt":"Concrete discharge on a BCE project site"},{"year":"2025","title":"128 projects in one year","text":"128 projects completed and 1,564 clients served in a single year.","image":"/Image/bce/stats_fleet.webp","imageAlt":"BCE fleet and equipment on site"},{"year":"2026","title":"Today","text":"Four batching plants, 41 mixer trucks, 8 pump trucks, 7 piling rigs and a team of 71, still building from Battambang.","image":"/Image/bce/hero_batching_plant.webp","imageAlt":"BCE batching plant at dusk"}]},"leadership":{"label":"Leadership","title":"Meet the people behind every pour.","people":[{"name":"Ms. Loeung Chan","role":"Chairwoman","image":"/Image/bce/chairwoman.webp","imageAlt":"Ms. Loeung Chan, Chairwoman of BCE","bio":["Ms. Loeung Chan is Chairwoman of Battambang Construction and Engineering Co., Ltd. She has guided the company through its restructuring in 2015 and its incorporation as BCE in 2020, and still sets the standard the business is run to.","Her direction is simple and does not change with the size of the project: quality controlled at every stage, safety on every site, and long-term partnerships with the clients, suppliers and crews who build Cambodia with us.","Thirty years on, the company she chairs runs four batching plants, its own piling rigs and a fleet of 41 mixer trucks — and still answers the phone from Battambang."]},{"name":"Mr. Sokha Vann","role":"Managing Director","image":"","imageAlt":"","bio":["Mr. Sokha Vann runs BCE''s day-to-day business, coordinating the batching plants, piling crews and civil works teams so every project is delivered on schedule and to specification.","He works alongside the Chairwoman on company strategy, fleet investment and the long-term partnerships that keep BCE building across Cambodia."]},{"name":"Ms. Sreyleak Chhun","role":"Finance & Administration Director","image":"","imageAlt":"","bio":["Ms. Sreyleak Chhun leads finance, procurement and administration, keeping plant, fleet and project spending under one budget and one set of controls.","Her team looks after payroll, supplier accounts and the paperwork behind every tender, so the site teams can concentrate on the work."]},{"name":"Mr. Dara Pich","role":"Operations Director","image":"","imageAlt":"","bio":["Mr. Dara Pich oversees production and site operations, from aggregate intake and batching to the mixers, pumps and piling rigs on the road.","He sets the daily dispatch plan with the plant and keeps quality, safety and delivery on the same schedule."]}]},"vision":{"sectionLabel":"Vision & mission","label":"Our vision","statement":"To be Cambodia’s most trusted partner for concrete, piling and construction."},"mission":{"label":"Our mission","statement":"To deliver quality-controlled concrete, foundations and construction on time and on spec, with our own plants, fleet and people."},"values":{"sectionLabel":"Core values","items":[{"title":"Quality","text":"Built to last. From material selection and production to construction and delivery, laboratory quality control keeps every structure strong, durable and lasting.","image":"/Image/bce/value-quality.webp","imageAlt":"Concrete frame and formwork rising beside a tower crane"},{"title":"Safety","text":"Our top priority. We protect our people, our partners and the communities we serve, from the batching plant to the project site.","image":"/Image/bce/value-safety.webp","imageAlt":"Crew working at height on scaffolding in high-visibility vests"},{"title":"Reliability","text":"On time, every time. Our own batching plants, mixer trucks and pump trucks give us the capacity to keep projects on schedule and on spec.","image":"/Image/bce/value-reliability.webp","imageAlt":"Tower crane and formwork keeping the construction programme on schedule"},{"title":"Partnership","text":"Stronger together. We grow alongside our clients, partners and suppliers through long-term relationships built on trust, respect and mutual success.","image":"/Image/bce/value-partnership.webp","imageAlt":"Two steel fixers working together on reinforcement"}]},"strategy":{"label":"Future development strategy","title":"Building today. Leading tomorrow.","pillars":[{"title":"Growth & expansion","text":"Expand our footprint across Cambodia and pursue selected regional opportunities through new facilities, partnerships and strategic investments.","icon":"tower"},{"title":"Innovation & technology","text":"Invest in advanced technology, digital systems and data-driven operations to improve efficiency, product quality and customer experience.","icon":"blueprint"},{"title":"Quality & reliability","text":"Strengthen our quality management, laboratory capability and process control to deliver products and services that exceed industry standards.","icon":"shield"},{"title":"People & culture","text":"Develop our people, promote a strong safety culture and foster a performance-driven environment built on integrity and accountability.","icon":"helmet"},{"title":"Sustainability & responsibility","text":"Operate responsibly with care for the environment, support communities and contribute to Cambodia’s sustainable development.","icon":"rain"}]},"careers":{"label":"Careers","title":"Build your career.","copy":"Great crews build great projects. Join BCE and put thirty years of equipment, engineers and experience behind your career.","image":"/Image/bce/about-zoom-rebar-crew.webp","imageAlt":"BCE crews working safely across a reinforced slab","primaryLabel":"View all positions","primaryHref":"/careers","secondaryLabel":"Apply","secondaryHref":"mailto:bce.hr.1990@gmail.com?subject=Job%20Application%20-%20BCE"},"zoom":{"statements":["Engineering and construction, from Battambang across Cambodia since 1995","Concrete, piling, construction and fleet, all under one roof"]},"explore":{"label":"Explore more","tiles":[{"label":"What we do","title":"Our businesses","href":"/businesses","image":"/Image/bce/about-business-banner.webp","imageAlt":"BCE site team reviewing a reinforced concrete slab"},{"label":"Tested at every stage","title":"Quality & HSE","href":"/quality","image":"/Image/bce/about-hse-banner.webp","imageAlt":"Concrete cylinder under compression testing in the BCE laboratory"}]},"title":"About BCE","slug":"home"}', '{"cover":{"label":"យើងជានរណា","title":"អំពី BCE","imageAlt":"ទិដ្ឋភាពពីលើនៃរោងចក្រលាយបេតុង និងលានគរថ្ម និងខ្សាច់របស់ BCE"},"intro":{"text":"ក្រុមហ៊ុន បាត់ដំបង ខនស្ត្រាក់សិន អេន អេនជីនារីង ខូអិលធីឌី (BCE) ជាក្រុមហ៊ុនសំណង់ បេតុង ការបោះសសរស្ដម្ភ និងវិស្វកម្ម ដែលមានមូលដ្ឋាននៅខេត្តបាត់ដំបង ដោយផ្គត់ផ្គង់បេតុងលាយស្រេច ការបោះសសរស្ដម្ភបេតុងអារម៉េ និងសំណង់ស៊ីវិល ដល់គម្រោងនានាទូទាំងកម្ពុជា ជាមួយរោងចក្រ កងគ្រឿងចក្រ និងក្រុមការងារ ៧១ នាក់ផ្ទាល់ខ្លួន។","primaryLabel":"ទាញយកប្រវត្តិរូបក្រុមហ៊ុន (PDF)","secondaryLabel":"មើលឯកសារ និងធនធានទាំងអស់"},"message":{"quote":"អស់រយៈពេលជាង ៣០ ឆ្នាំមកនេះ យើងបានកសាងឡើងលើសសរស្តម្ភ ៤ យ៉ាង៖ គុណភាព សុវត្ថិភាព ភាពជឿជាក់ និងភាពជាដៃគូ។ គុណតម្លៃទាំងនេះជាការណែនាំរាល់ការចាក់បេតុង រាល់ការបោះសសរ និងគ្រប់គម្រោងទាំងអស់។","attribution":"ប្រធានក្រុមប្រឹក្សាភិបាល ក្រុមហ៊ុន BCE., Ltd."},"story":{"title":"ប្រវត្តិដំណើររបស់យើង","text":"បង្កើតឡើងនៅខេត្តបាត់ដំបងក្នុងឆ្នាំ ១៩៩៥ ក្រុមហ៊ុន BCE បានរីកចម្រើនទៅជាប្រតិបត្តិការរួមបញ្ចូលគ្នាយ៉ាងពេញលេញ ដោយផ្តល់នូវការផ្គត់ផ្គង់បេតុង ការបោះសសរស្ដម្ភ សំណង់ ការងារចាក់កម្រាលបេតុង និងការជួលរថយន្ត និងគ្រឿងចក្រ ជាមួយរោងចក្រ និងកងយានយន្តផ្ទាល់ខ្លួន។","milestones":[{"title":"ការបង្កើតក្រុមហ៊ុន","text":"BCE ចាប់ផ្ដើមនៅបាត់ដំបង ក្រោមឈ្មោះ Hong Huot Ly Co., Ltd. ដោយផ្គត់ផ្គង់បេតុង និងសេវាកម្មសំណង់ ដល់គម្រោងនានាទូទាំងខេត្ត។","imageAlt":"ទិដ្ឋភាពពីលើនៃរោងចក្រលាយបេតុង និងលានគរថ្ម និងខ្សាច់ ដែលជាចំណុចចាប់ផ្ដើមរបស់ BCE"},{"title":"រៀបចំរចនាសម្ព័ន្ធឡើងវិញដើម្បីកំណើន","text":"ក្រុមហ៊ុនត្រូវបានរៀបចំរចនាសម្ព័ន្ធឡើងវិញ ជាទម្រង់ស្ថាប័នបច្ចុប្បន្ន ដោយបញ្ចូលការងារលាយបេតុង ការបោះសសរស្ដម្ភ និងសំណង់ស៊ីវិល ក្រោមក្រុមគ្រប់គ្រងតែមួយ។","imageAlt":"រោងចក្រលាយបេតុង និងគំនរថ្ម និងខ្សាច់"},{"title":"រោងចក្រ និងកងគ្រឿងចក្រទំនើប","text":"ការលាយបេតុងដោយប្រព័ន្ធកុំព្យូទ័រ និងកងរថយន្តលាយបេតុង និងរថយន្តបូមបេតុងកាន់តែធំឡើង បានពង្រីកសមត្ថភាពហួសពីបាត់ដំបង។","imageAlt":"រថយន្តលាយបេតុង និងរថយន្តបូមបេតុងរបស់ BCE តម្រៀបជាជួរនៅរោងចក្រ"},{"title":"ចុះបញ្ជីជាក្រុមហ៊ុន BCE","text":"អាជីវកម្មត្រូវបានចុះបញ្ជីជាផ្លូវការ ក្រោមឈ្មោះ ក្រុមហ៊ុន បាត់ដំបង ខនស្ត្រាក់សិន អេន អេនជីនារីង ខូអិលធីឌី (BCE)។","imageAlt":"វិស្វករ និងក្រុមការងាររបស់ BCE នៅការដ្ឋានក្នុងខេត្តបាត់ដំបង"},{"title":"មន្ទីរពិសោធន៍ និងប្រព័ន្ធគុណភាព","text":"មន្ទីរពិសោធន៍វត្ថុធាតុសំណង់ផ្ទាល់ខ្លួន និងកំណត់ត្រារូបមន្តលាយបេតុងជាផ្លូវការ បាននាំការធ្វើតេស្ត និងការត្រួតពិនិត្យគុណភាព មកនៅកន្លែងតែមួយ។","imageAlt":"គំរូបេតុងសម្រាប់ធ្វើតេស្ត នៅក្នុងមន្ទីរពិសោធន៍របស់ BCE"},{"title":"ភាពជាដៃគូ និងតំបន់គ្របដណ្តប់","text":"ភាពជាដៃគូផ្គត់ផ្គង់រយៈពេលវែង និងភាពជាដៃគូបច្ចេកទេស បានពង្រីកការដឹកជញ្ជូនទៅដល់ ១៣ ខេត្ត និងរាជធានីភ្នំពេញ។","imageAlt":"ការចាក់បេតុងនៅការដ្ឋានគម្រោងរបស់ BCE"},{"title":"១២៨ គម្រោងក្នុងមួយឆ្នាំ","text":"បញ្ចប់គម្រោងបាន ១២៨ និងបម្រើអតិថិជនបាន ១,៥៦៤ នាក់ក្នុងមួយឆ្នាំតែមួយ។","imageAlt":"កងគ្រឿងចក្រ និងសម្ភារៈរបស់ BCE នៅការដ្ឋាន"},{"title":"ថ្ងៃនេះ","text":"រោងចក្រលាយបេតុង ៤ កន្លែង រថយន្តលាយបេតុង ៤១ គ្រឿង រថយន្តបូមបេតុង ៨ គ្រឿង ម៉ាស៊ីនបោះសសរស្ដម្ភ ៧ គ្រឿង និងក្រុមការងារ ៧១ នាក់ — នៅតែបន្តកសាងចេញពីបាត់ដំបង។","imageAlt":"រោងចក្រលាយបេតុងរបស់ BCE នៅពេលល្ងាច"}]},"leadership":{"label":"ថ្នាក់ដឹកនាំ","title":"ស្គាល់អ្នកដែលនៅពីក្រោយរាល់ការចាក់បេតុង។","people":[{"name":"លោកស្រី លឿង ចាន់","role":"ប្រធានក្រុមប្រឹក្សាភិបាល","imageAlt":"លោកស្រី លឿង ចាន់ ប្រធានក្រុមប្រឹក្សាភិបាលក្រុមហ៊ុន BCE","bio":["លោកស្រី លឿង ចាន់ គឺជាប្រធានក្រុមប្រឹក្សាភិបាលនៃក្រុមហ៊ុន បាត់ដំបង ខនស្ត្រាក់សិន អេន អេនជីនារីង ខូអិលធីឌី។ លោកស្រីបានដឹកនាំក្រុមហ៊ុនឆ្លងកាត់ការរៀបចំរចនាសម្ព័ន្ធឡើងវិញក្នុងឆ្នាំ ២០១៥ និងការចុះបញ្ជីជាក្រុមហ៊ុន BCE ក្នុងឆ្នាំ ២០២០ ហើយនៅតែកំណត់ស្តង់ដារដែលអាជីវកម្មនេះដំណើរការតាម។","ទិសដៅរបស់លោកស្រីគឺសាមញ្ញ ហើយមិនប្រែប្រួលតាមទំហំគម្រោង៖ គុណភាពត្រូវត្រួតពិនិត្យគ្រប់ដំណាក់កាល សុវត្ថិភាពនៅគ្រប់ការដ្ឋាន និងភាពជាដៃគូរយៈពេលវែង ជាមួយអតិថិជន អ្នកផ្គត់ផ្គង់ និងក្រុមការងារ ដែលកសាងកម្ពុជាជាមួយយើង។","រយៈពេល ៣០ ឆ្នាំក្រោយមក ក្រុមហ៊ុនដែលលោកស្រីដឹកនាំ មានរោងចក្រលាយបេតុង ៤ កន្លែង ម៉ាស៊ីនបោះសសរស្ដម្ភផ្ទាល់ខ្លួន និងកងរថយន្តលាយបេតុង ៤១ គ្រឿង — ហើយនៅតែទទួលទូរស័ព្ទពីបាត់ដំបង។"]},{"name":"លោក សុខា វ៉ាន់","role":"នាយកគ្រប់គ្រង","imageAlt":"","bio":["លោក សុខា វ៉ាន់ គ្រប់គ្រងប្រតិបត្តិការប្រចាំថ្ងៃរបស់ BCE ដោយសម្របសម្រួលរោងចក្រលាយបេតុង ក្រុមការងារបោះសសរស្ដម្ភ និងក្រុមការងារសំណង់ស៊ីវិល ដើម្បីធានាថាគ្រប់គម្រោងត្រូវបានប្រគល់ជូនទាន់ពេលវេលា និងត្រឹមត្រូវតាមលក្ខណៈបច្ចេកទេស។","លោកធ្វើការជាមួយប្រធានក្រុមប្រឹក្សាភិបាល លើយុទ្ធសាស្ត្រក្រុមហ៊ុន ការវិនិយោគលើកងគ្រឿងចក្រ និងភាពជាដៃគូរយៈពេលវែង ដែលធ្វើឱ្យ BCE បន្តកសាងទូទាំងកម្ពុជា។"]},{"name":"លោកស្រី ស្រីល័ក្ខ ឈុន","role":"នាយិកាហិរញ្ញវត្ថុ និងរដ្ឋបាល","imageAlt":"","bio":["លោកស្រី ស្រីល័ក្ខ ឈុន ដឹកនាំផ្នែកហិរញ្ញវត្ថុ ការទិញសម្ភារៈ និងរដ្ឋបាល ដោយរក្សាការចំណាយលើរោងចក្រ កងគ្រឿងចក្រ និងគម្រោង ឱ្យស្ថិតក្រោមថវិកាតែមួយ និងប្រព័ន្ធត្រួតពិនិត្យតែមួយ។","ក្រុមការងាររបស់លោកស្រីថែទាំបញ្ជីបៀវត្សរ៍ គណនីអ្នកផ្គត់ផ្គង់ និងឯកសារពាក់ព័ន្ធនឹងរាល់ការដេញថ្លៃ ដើម្បីឱ្យក្រុមការងារការដ្ឋានអាចផ្តោតលើការងារបានពេញលេញ។"]},{"name":"លោក ដារា ពេជ្រ","role":"នាយកប្រតិបត្តិការ","imageAlt":"","bio":["លោក ដារា ពេជ្រ ត្រួតពិនិត្យការផលិត និងប្រតិបត្តិការនៅការដ្ឋាន ចាប់ពីការទទួលថ្ម និងខ្សាច់ និងការលាយបេតុង រហូតដល់រថយន្តលាយបេតុង រថយន្តបូមបេតុង និងម៉ាស៊ីនបោះសសរស្ដម្ភ នៅលើផ្លូវ។","លោកកំណត់ផែនការបញ្ជូនប្រចាំថ្ងៃជាមួយរោងចក្រ និងរក្សាគុណភាព សុវត្ថិភាព និងការដឹកជញ្ជូន ឱ្យដំណើរការតាមកាលវិភាគតែមួយ។"]}]},"vision":{"sectionLabel":"ចក្ខុវិស័យ និងបេសកកម្ម","label":"ចក្ខុវិស័យរបស់យើង","statement":"ក្លាយជាដៃគូដែលគួរឱ្យទុកចិត្តបំផុតនៅកម្ពុជា សម្រាប់ការផ្គត់ផ្គង់បេតុង ការបោះសសរគ្រឹះ និងការងារសំណង់។"},"mission":{"label":"បេសកកម្មរបស់យើង","statement":"ផ្ដល់ជូននូវបេតុងដែលគ្រប់គ្រងគុណភាព គ្រឹះរឹងមាំ និងសំណង់ប្រកបដោយស្តង់ដារ ទាន់ពេលវេលា និងត្រូវតាមបច្ចេកទេស ដោយរោងចក្រ កងគ្រឿងចក្រ និងក្រុមការងារផ្ទាល់ខ្លួន។"},"values":{"sectionLabel":"គុណតម្លៃស្នូល","items":[{"title":"គុណភាព","text":"កសាងឡើងដើម្បីជាប់គង់វង្ស។ ចាប់ពីការជ្រើសរើសវត្ថុធាតុ និងការផលិត រហូតដល់ការសាងសង់ និងការដឹកជញ្ជូន ការត្រួតពិនិត្យគុណភាពនៅមន្ទីរពិសោធន៍ ធានាថាគ្រប់សំណង់មានភាពរឹងមាំ ធន់ និងគង់វង្ស។","imageAlt":"គ្រោងឆ្អឹងបេតុង និងទម្រង់ពូកកំពុងឡើងកម្ពស់ក្បែររថយន្តស្ទូចប៉ម"},{"title":"សុវត្ថិភាព","text":"ជាអាទិភាពចម្បងរបស់យើង។ យើងការពារបុគ្គលិក ដៃគូ និងសហគមន៍ដែលយើងបម្រើ ចាប់ពីរោងចក្រលាយបេតុង រហូតដល់ការដ្ឋានគម្រោង។","imageAlt":"ក្រុមការងារធ្វើការនៅខ្ពស់លើរនាស់ ដោយស្លៀកអាវឆ្លុះពន្លឺ"},{"title":"ភាពជឿជាក់","text":"ទាន់ពេលវេលាគ្រប់វេលា។ រោងចក្រលាយបេតុង រថយន្តលាយបេតុង និងរថយន្តបូមបេតុងផ្ទាល់ខ្លួនរបស់យើង ផ្ដល់សមត្ថភាពពេញលេញក្នុងការរក្សាគម្រោងឱ្យដំណើរការតាមកាលវិភាគ និងបច្ចេកទេស។","imageAlt":"រថយន្តស្ទូចប៉ម និងទម្រង់ពូក ដែលជួយឱ្យការសាងសង់ដំណើរការតាមកាលវិភាគ"},{"title":"ភាពជាដៃគូ","text":"រឹងមាំជាងមុន នៅពេលយើងរួមគ្នា។ យើងរីកចម្រើនរួមជាមួយអតិថិជន ដៃគូ និងអ្នកផ្គត់ផ្គង់ តាមរយៈទំនាក់ទំនងរយៈពេលវែង ដែលកសាងលើការទុកចិត្ត ការគោរព និងភាពជោគជ័យរួមគ្នា។","imageAlt":"ជាងដែកគោលពីរនាក់ធ្វើការជាមួយគ្នាលើដែកគោល"}]},"strategy":{"label":"យុទ្ធសាស្ត្រអភិវឌ្ឍន៍អនាគត","title":"កសាងថ្ងៃនេះ។ ឈានមុខថ្ងៃស្អែក។","pillars":[{"title":"កំណើន និងការពង្រីក","text":"ពង្រីកវត្តមានរបស់យើងទូទាំងកម្ពុជា និងស្វែងរកឱកាសក្នុងតំបន់ជាក់លាក់ តាមរយៈកន្លែងផលិតថ្មីៗ ភាពជាដៃគូ និងការវិនិយោគយុទ្ធសាស្ត្រ។"},{"title":"នវានុវត្តន៍ និងបច្ចេកវិទ្យា","text":"វិនិយោគលើបច្ចេកវិទ្យាទំនើប ប្រព័ន្ធឌីជីថល និងប្រតិបត្តិការដែលផ្អែកលើទិន្នន័យ ដើម្បីបង្កើនប្រសិទ្ធភាព គុណភាពផលិតផល និងបទពិសោធន៍របស់អតិថិជន។"},{"title":"គុណភាព និងភាពជឿជាក់","text":"ពង្រឹងការគ្រប់គ្រងគុណភាព សមត្ថភាពមន្ទីរពិសោធន៍ និងការត្រួតពិនិត្យដំណើរការ ដើម្បីផ្គត់ផ្គង់ផលិតផល និងសេវាកម្ម លើសពីស្តង់ដារឧស្សាហកម្ម។"},{"title":"មនុស្ស និងវប្បធម៌","text":"អភិវឌ្ឍន៍ធនធានមនុស្សរបស់យើង ជំរុញវប្បធម៌សុវត្ថិភាពដ៏រឹងមាំ និងបង្កើតបរិយាកាសការងារដែលជំរុញដោយលទ្ធផល ដោយផ្អែកលើភាពស្មោះត្រង់ និងការទទួលខុសត្រូវ។"},{"title":"ចីរភាព និងការទទួលខុសត្រូវ","text":"ប្រតិបត្តិការដោយការទទួលខុសត្រូវ និងការយកចិត្តទុកដាក់លើបរិស្ថាន គាំទ្រសហគមន៍ និងរួមចំណែកដល់ការអភិវឌ្ឍន៍ប្រកបដោយចីរភាពរបស់កម្ពុជា។"}]},"careers":{"label":"ឱកាសការងារ","title":"កសាងអាជីពរបស់អ្នក។","copy":"ក្រុមការងារដ៏ប៉ិនប្រសប់ កសាងគម្រោងដ៏អស្ចារ្យ។ ចូលរួមជាមួយ BCE ហើយដាក់គ្រឿងចក្រ វិស្វករ និងបទពិសោធន៍ ៣០ ឆ្នាំ នៅពីក្រោយអាជីពរបស់អ្នក។","imageAlt":"ក្រុមការងារ BCE ធ្វើការដោយសុវត្ថិភាពលើកម្រាលបេតុងដែលមានដែកគោល","primaryLabel":"មើលមុខតំណែងទាំងអស់","secondaryLabel":"ដាក់ពាក្យ"},"zoom":{"statements":["វិស្វកម្ម និងសំណង់ ពីបាត់ដំបង ទូទាំងកម្ពុជា តាំងពីឆ្នាំ ១៩៩៥","បេតុង ការបោះសសរស្ដម្ភ សំណង់ និងយានយន្ត ទាំងអស់នៅកន្លែងតែមួយ"]},"explore":{"label":"ស្វែងរកបន្ថែម","tiles":[{"label":"អ្វីដែលយើងធ្វើ","title":"អាជីវកម្មរបស់យើង","imageAlt":"ក្រុមការងារការដ្ឋានរបស់ BCE កំពុងពិនិត្យកម្រាលបេតុងដែលមានដែកគោល"},{"label":"ធ្វើតេស្តគ្រប់ដំណាក់កាល","title":"គុណភាព និងសុវត្ថិភាព (HSE)","imageAlt":"គំរូស៊ីឡាំងបេតុងកំពុងធ្វើតេស្តកម្លាំងសង្កត់ នៅក្នុងមន្ទីរពិសោធន៍របស់ BCE"}]}}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
