VALUES ('projects:kampong-thom-bridge-foundations', 'projects', 'kampong-thom-bridge-foundations', 'published', 0, '{"slug":"kampong-thom-bridge-foundations","sample":true,"name":"Bridge Foundation Piling","owner":"Provincial public works authority","location":"Stueng Saen, Kampong Thom","period":"Feb 2024 – Sep 2024","category":"Piling","summary":"Reinforced concrete piles for a two-span river bridge on a provincial road, installed and tested by our own rigs and crews.","scope":["Supply of reinforced concrete piles","Pile installation at abutments and pier","Pile cap concrete from our batching plant","Load testing and as-built records"],"gallery":[{"image":"/Image/bce/project_page_28.webp","caption":"Hydraulic piling rig positioned at the foundation site"},{"image":"/Image/bce/project_page_29.webp","caption":"Deep foundation reinforcement and boring"},{"image":"/Image/bce/project_page_30.webp","caption":"Reinforced pile installation across the foundation grid"},{"image":"/Image/bce/project_page_31.webp","caption":"Completed foundation pile caps"}],"highlights":[{"value":"64","label":"Piles installed","note":"Abutments and pier"},{"value":"18","unit":"m","label":"Pile length","note":"Average per pile"},{"value":"420","unit":"m³","label":"Concrete supplied","note":"Pile caps and deck"},{"value":"7","unit":"mo","label":"Project period","note":"Feb – Sep 2024"}],"equipment":[{"name":"Piling rigs","count":2},{"name":"Mixer trucks","count":4},{"name":"Mobile crane","count":1},{"name":"Pump truck","count":1}],"technical":[{"label":"Pile type","value":"Precast RC square pile, 350 × 350 mm"},{"label":"Concrete grade","value":"C35 piles, C30 pile caps"},{"label":"Testing","value":"Static load test; cube strength at 7 and 28 days"}],"outcome":"Foundations were handed over ahead of the rainy season, so deck works could begin without delay."}', '{"name":"ការបោះសសរស្ដម្ភគ្រឹះស្ពាន","owner":"មន្ទីរសាធារណការខេត្ត","location":"ស្ទឹងសែន កំពង់ធំ","period":"កុម្ភៈ ២០២៤ – កញ្ញា ២០២៤","summary":"សសរស្ដម្ភបេតុងអារម៉េសម្រាប់ស្ពានឆ្លងទន្លេពីរល្វែងលើផ្លូវខេត្ត ដែលយើងបានបោះ និងតេស្តដោយម៉ាស៊ីន និងក្រុមការងារផ្ទាល់ខ្លួន។","scope":["ការផ្គត់ផ្គង់សសរស្ដម្ភបេតុងអារម៉េ","ការបោះសសរស្ដម្ភនៅជើងស្ពាន និងសសរកណ្តាល","បេតុងក្បាលសសរស្ដម្ភពីរោងចក្ររបស់យើង","ការតេស្តបន្ទុក និងកំណត់ត្រាសំណង់ជាក់ស្ដែង"],"gallery":[{"caption":"ម៉ាស៊ីនបោះសសរស្ដម្ភធារាសាស្ត្រឈរប្រចាំនៅការដ្ឋានគ្រឹះ"},{"caption":"ការងារដែកគោល និងការខួងគ្រឹះជម្រៅ"},{"caption":"ការដំឡើងសសរស្ដម្ភបេតុងអារម៉េតាមបណ្តាញគ្រឹះ"},{"caption":"ក្បាលសសរស្ដម្ភគ្រឹះដែលបានបញ្ចប់រួចរាល់"}],"highlights":[{"value":"64","label":"សសរស្ដម្ភដែលបានបោះ","note":"ជើងស្ពាន និងសសរកណ្តាល"},{"value":"18","unit":"m","label":"ប្រវែងសសរស្ដម្ភ","note":"មធ្យមក្នុងមួយសសរ"},{"value":"420","unit":"m³","label":"បេតុងដែលបានផ្គត់ផ្គង់","note":"ក្បាលសសរ និងផ្ទៃស្ពាន"},{"value":"7","unit":"mo","label":"រយៈពេលគម្រោង","note":"កុម្ភៈ – កញ្ញា ២០២៤"}],"equipment":[{"name":"ម៉ាស៊ីនបោះសសរស្ដម្ភ"},{"name":"រថយន្តលាយបេតុង"},{"name":"ស្ទូចចល័ត"},{"name":"រថយន្តបូមបេតុង"}],"technical":[{"label":"ប្រភេទសសរស្ដម្ភ","value":"សសរស្ដម្ភបេតុងអារម៉េចាក់ស្រេចរាងការ៉េ 350 × 350 mm"},{"label":"កម្រិតបេតុង","value":"សសរស្ដម្ភ C35 ក្បាលសសរ C30"},{"label":"ការតេស្ត","value":"តេស្តបន្ទុកស្ថិត; កម្លាំងគំរូគូបនៅថ្ងៃទី ៧ និង ២៨"}],"outcome":"គ្រឹះត្រូវបានប្រគល់ជូនមុនរដូវវស្សា ដូច្នេះការងារផ្ទៃស្ពានអាចចាប់ផ្ដើមបានដោយគ្មានការពន្យារពេល។","slug":"kampong-thom-bridge-foundations"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
