INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('projects:poipet-logistics-warehouse', 'projects', 'poipet-logistics-warehouse', 'published', 1, '{"slug":"poipet-logistics-warehouse","sample":true,"name":"Logistics Warehouse Floor Slab","owner":"Private logistics developer","location":"Poipet, Banteay Meanchey","period":"Jun 2024 – Dec 2024","category":"Concrete Slab Works","summary":"A heavy-duty ground-bearing slab for a cross-border logistics warehouse, poured in planned bays and finished for racking and forklift traffic.","scope":["Sub-base preparation and compaction","Ready-mix supply from BTB plants","Slab placement in planned pour bays","Power-float finish and saw-cut joints"],"gallery":[{"image":"/Image/bce/project_page_14.webp","caption":"Structural frame rising over prepared foundation"},{"image":"/Image/bce/project_page_15.webp","caption":"Continuous ready-mix placement and leveling"},{"image":"/Image/bce/project_page_16.webp","caption":"Concrete finishing and power-float operations"},{"image":"/Image/bce/core_services.webp","caption":"Slab placement using heavy boom pumps"}],"highlights":[{"value":"12,400","unit":"m²","label":"Slab area","note":"Single warehouse floor"},{"value":"2,600","unit":"m³","label":"Concrete placed","note":"C30 ready-mix"},{"value":"22","label":"Pour bays","note":"Day pours"},{"value":"200","unit":"mm","label":"Slab thickness","note":"Mesh reinforced"}],"equipment":[{"name":"Pump trucks","count":2},{"name":"Mixer trucks","count":8},{"name":"Power trowels","count":4},{"name":"Vibratory roller","count":1}],"technical":[{"label":"Concrete","value":"C30, slump 100 ± 25 mm"},{"label":"Finish","value":"Power-floated with dry-shake hardener"},{"label":"Joints","value":"Saw-cut at 6 m centres, sealed"}],"outcome":"The floor was ready for racking installation two weeks ahead of the tenant''s fit-out."}', '{"name":"កម្រាលបេតុងឃ្លាំងភស្តុភារ","owner":"អ្នកអភិវឌ្ឍន៍ភស្តុភារឯកជន","location":"ប៉ោយប៉ែត បន្ទាយមានជ័យ","period":"មិថុនា ២០២៤ – ធ្នូ ២០២៤","summary":"កម្រាលបេតុងធន់នឹងបន្ទុកធ្ងន់ដាក់លើដីដោយផ្ទាល់ សម្រាប់ឃ្លាំងភស្តុភារឆ្លងព្រំដែន ចាក់ជាផ្ទាំងៗតាមការគ្រោងទុក និងបញ្ចប់ផ្ទៃឱ្យស័ក្តិសមសម្រាប់ការដំឡើងធ្នើរ និងការប្រើប្រាស់រថយន្តលើកទំនិញ។","scope":["ការរៀបចំ និងបង្ហាប់ស្រទាប់គ្រឹះ","ការផ្គត់ផ្គង់បេតុងលាយស្រេចពីរោងចក្រនៅបាត់ដំបង","ការចាក់កម្រាលតាមផ្ទាំងដែលបានគ្រោងទុក","ការរលោងផ្ទៃដោយម៉ាស៊ីន និងការកាត់សន្លាក់"],"gallery":[{"caption":"គ្រោងរចនាសម្ព័ន្ធកំពុងកើនឡើងលើគ្រឹះដែលបានរៀបចំ"},{"caption":"ការចាក់បេតុងលាយស្រេច និងការរាបស្មើជាបន្តបន្ទាប់"},{"caption":"ការងារបញ្ចប់ផ្ទៃ និងការរលោងដោយម៉ាស៊ីន"},{"caption":"ការចាក់កម្រាលដោយប្រើរថយន្តបូមបេតុងដៃវែង"}],"highlights":[{"value":"12,400","unit":"m²","label":"ផ្ទៃក្រឡាកម្រាល","note":"កម្រាលឃ្លាំងតែមួយ"},{"value":"2,600","unit":"m³","label":"បេតុងដែលបានចាក់","note":"បេតុងលាយស្រេច C30"},{"value":"22","label":"ផ្ទាំងចាក់","note":"ចាក់ពេលថ្ងៃ"},{"value":"200","unit":"mm","label":"កម្រាស់កម្រាល","note":"ពង្រឹងដោយសំណាញ់ដែក"}],"equipment":[{"name":"រថយន្តបូមបេតុង"},{"name":"រថយន្តលាយបេតុង"},{"name":"ម៉ាស៊ីនរលោងផ្ទៃ"},{"name":"ម៉ាស៊ីនបង្ហាប់ញ័រ"}],"technical":[{"label":"បេតុង","value":"C30 ស្រុត 100 ± 25 mm"},{"label":"ការបញ្ចប់ផ្ទៃ","value":"រលោងដោយម៉ាស៊ីន ជាមួយសារធាតុរឹងផ្ទៃប្រភេទស្ងួត"},{"label":"សន្លាក់","value":"កាត់ដោយរណាររៀងរាល់ 6 m និងបិទជិត"}],"outcome":"កម្រាលបានរួចរាល់សម្រាប់ការដំឡើងធ្នើរ លឿនជាងការតុបតែងខាងក្នុងរបស់អ្នកជួលពីរសប្ដាហ៍។","slug":"poipet-logistics-warehouse"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
