INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('projects:siem-reap-commercial-ready-mix', 'projects', 'siem-reap-commercial-ready-mix', 'published', 2, '{"slug":"siem-reap-commercial-ready-mix","sample":true,"name":"Commercial Complex Ready-Mix Supply","owner":"Private commercial developer","location":"Siem Reap City","period":"Jan 2023 – Mar 2024","category":"Ready-Mix Concrete","summary":"Continuous ready-mix supply for a four-storey commercial complex, scheduled around the contractor''s pour programme.","scope":["Mix designs for foundations, columns and slabs","Scheduled delivery from plant to site","Pumping for upper-floor slabs","Slump and cube testing on every pour"],"gallery":[{"image":"/Image/bce/hero_batching_plant.webp","caption":"Automated batching plant preparing ready-mix concrete"},{"image":"/Image/bce/project_page_17.webp","caption":"Mixer trucks staged and discharging on site"},{"image":"/Image/bce/project_page_18.webp","caption":"Upper floor structural slab concrete pouring"},{"image":"/Image/bce/laboratory_qa.webp","caption":"Slump test and compressive cube quality verification"}],"highlights":[{"value":"6,800","unit":"m³","label":"Concrete supplied","note":"Over 15 months"},{"value":"4","label":"Mix designs","note":"C25 to C35"},{"value":"1,100","label":"Truck deliveries","note":"Scheduled call-offs"},{"value":"100","unit":"%","label":"Pours tested","note":"Slump and cubes"}],"equipment":[{"name":"Mixer trucks","count":10},{"name":"Pump trucks","count":2}],"technical":[{"label":"Grades","value":"C25 slabs, C30 columns, C35 foundations"},{"label":"Quality control","value":"Slump at discharge; 6 cubes per 50 m³"}]}', '{"name":"ការផ្គត់ផ្គង់បេតុងលាយស្រេចសម្រាប់អគារពាណិជ្ជកម្ម","owner":"អ្នកអភិវឌ្ឍន៍ពាណិជ្ជកម្មឯកជន","location":"ក្រុងសៀមរាប","period":"មករា ២០២៣ – មីនា ២០២៤","summary":"ការផ្គត់ផ្គង់បេតុងលាយស្រេចជាបន្តបន្ទាប់សម្រាប់អគារពាណិជ្ជកម្មបួនជាន់ តាមកាលវិភាគចាក់បេតុងរបស់អ្នកម៉ៅការ។","scope":["រូបមន្តលាយបេតុងសម្រាប់គ្រឹះ សសរ និងកម្រាល","ការដឹកជញ្ជូនតាមកាលវិភាគពីរោងចក្រទៅការដ្ឋាន","ការបូមបេតុងសម្រាប់កម្រាលជាន់លើ","ការតេស្តកម្រិតស្រុត និងគំរូគូបលើរាល់ការចាក់បេតុង"],"gallery":[{"caption":"រោងចក្រលាយបេតុងស្វ័យប្រវត្តិកំពុងផលិតបេតុងលាយស្រេច"},{"caption":"រថយន្តលាយបេតុងឈរតម្រង់ជួរ និងកំពុងចាក់បេតុងនៅការដ្ឋាន"},{"caption":"ការចាក់បេតុងកម្រាលរចនាសម្ព័ន្ធជាន់លើ"},{"caption":"ការតេស្តកម្រិតស្រុត និងការផ្ទៀងផ្ទាត់គុណភាពគំរូគូបសង្កត់"}],"highlights":[{"value":"6,800","unit":"m³","label":"បេតុងដែលបានផ្គត់ផ្គង់","note":"ជាង ១៥ ខែ"},{"value":"4","label":"រូបមន្តលាយបេតុង","note":"C25 ដល់ C35"},{"value":"1,100","label":"ការដឹកជញ្ជូនដោយរថយន្ត","note":"ការហៅតាមកាលវិភាគ"},{"value":"100","unit":"%","label":"ការចាក់ដែលបានតេស្ត","note":"កម្រិតស្រុត និងគំរូគូប"}],"equipment":[{"name":"រថយន្តលាយបេតុង"},{"name":"រថយន្តបូមបេតុង"}],"technical":[{"label":"កម្រិតបេតុង","value":"កម្រាល C25 សសរ C30 គ្រឹះ C35"},{"label":"ការត្រួតពិនិត្យគុណភាព","value":"តេស្តកម្រិតស្រុតពេលចាក់; គំរូគូប ៦ ក្នុង 50 m³"}],"slug":"siem-reap-commercial-ready-mix"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
