INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('projects:battambang-provincial-road', 'projects', 'battambang-provincial-road', 'published', 3, '{"slug":"battambang-provincial-road","sample":true,"name":"Provincial Road Rehabilitation","owner":"Provincial administration","location":"Battambang Province","period":"Nov 2023 – May 2024","category":"Construction","summary":"Rehabilitation of a provincial road link, including sub-base works, drainage and a new asphalt wearing course.","scope":["Earthworks and sub-base","Culverts and roadside drainage","Asphalt paving and compaction","Road markings and handover"],"gallery":[{"image":"/Image/bce/project_page_20.webp","caption":"Heavy earthworks and road sub-base compaction"},{"image":"/Image/bce/project_page_21.webp","caption":"Concrete culvert installation and roadside drainage"},{"image":"/Image/bce/project_page_22.webp","caption":"Continuous asphalt and concrete paving operations"}],"highlights":[{"value":"8.5","unit":"km","label":"Road length","note":"Single carriageway"},{"value":"7","unit":"m","label":"Carriageway width","note":"Plus shoulders"},{"value":"14","label":"Culverts installed","note":"Box and pipe"}],"outcome":"The upgraded link shortened the journey to the district market and keeps traffic moving through the wet season."}', '{"name":"ការស្ដារផ្លូវខេត្តឡើងវិញ","owner":"រដ្ឋបាលខេត្ត","location":"ខេត្តបាត់ដំបង","period":"វិច្ឆិកា ២០២៣ – ឧសភា ២០២៤","summary":"ការស្ដារផ្លូវតភ្ជាប់ខេត្តឡើងវិញ រួមមានការងារស្រទាប់គ្រឹះ ប្រព័ន្ធលូបង្ហូរទឹក និងស្រទាប់កៅស៊ូថ្មី។","scope":["ការងារដី និងស្រទាប់គ្រឹះ","លូ និងប្រព័ន្ធបង្ហូរទឹកតាមផ្លូវ","ការក្រាលកៅស៊ូ និងការបង្ហាប់","ការគូសសញ្ញាផ្លូវ និងការប្រគល់ការងារ"],"gallery":[{"caption":"ការងារដីធុនធ្ងន់ និងការបង្ហាប់ស្រទាប់គ្រឹះផ្លូវ"},{"caption":"ការដំឡើងលូបេតុង និងប្រព័ន្ធបង្ហូរទឹកតាមផ្លូវ"},{"caption":"ប្រតិបត្តិការក្រាលកៅស៊ូ និងបេតុងជាបន្តបន្ទាប់"}],"highlights":[{"value":"8.5","unit":"km","label":"ប្រវែងផ្លូវ","note":"ផ្លូវមួយគន្លង"},{"value":"7","unit":"m","label":"ទទឹងផ្លូវ","note":"បូកចិញ្ចើមផ្លូវ"},{"value":"14","label":"លូដែលបានដំឡើង","note":"លូប្រអប់ និងលូមូល"}],"outcome":"ផ្លូវដែលបានកែលម្អបានកាត់បន្ថយរយៈពេលធ្វើដំណើរទៅផ្សារស្រុក និងរក្សាចរាចរណ៍ឱ្យដំណើរការពេញរដូវវស្សា។","slug":"battambang-provincial-road"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
