INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('projects:phnom-penh-tower-foundations', 'projects', 'phnom-penh-tower-foundations', 'published', 4, '{"slug":"phnom-penh-tower-foundations","sample":true,"name":"Mixed-Use Tower Foundations","owner":"Private developer","location":"Chamkar Mon, Phnom Penh","period":"Aug 2024 – Apr 2025","category":"Piling","summary":"Bored piles and a raft foundation for a mixed-use tower, with reinforcement, concrete and testing delivered by one team.","scope":["Bored cast-in-place piles","Reinforcement cages fabricated on site","Continuous raft foundation pour","Integrity and load testing"],"gallery":[{"image":"/Image/bce/project_page_23.webp","caption":"Heavy reinforcement steel fabrication for deep foundation"},{"image":"/Image/bce/project_page_24.webp","caption":"Structural column tying and engineering inspection"},{"image":"/Image/bce/project_page_25.webp","caption":"Continuous monolithic raft foundation concrete placement"},{"image":"/Image/bce/project_page_26.webp","caption":"Raft foundation cured and completed"}],"highlights":[{"value":"120","label":"Bored piles","note":"800 and 1,000 mm"},{"value":"32","unit":"m","label":"Pile depth","note":"Below cut-off"},{"value":"1,850","unit":"m³","label":"Raft pour","note":"Single continuous pour"},{"value":"9","unit":"mo","label":"Project period","note":"Aug 2024 – Apr 2025"}],"equipment":[{"name":"Piling rigs","count":3},{"name":"Crawler crane","count":1},{"name":"Mixer trucks","count":12},{"name":"Pump trucks","count":2}],"technical":[{"label":"Piles","value":"Bored cast-in-place, Ø 800 and 1,000 mm"},{"label":"Concrete grade","value":"C40 raft, C35 piles"},{"label":"Raft","value":"2.2 m thick, poured continuously over 26 hours"}],"outcome":"The raft was completed in a single pour with no cold joints, keeping the superstructure programme on track."}', '{"name":"គ្រឹះអគារពហុមុខងារ","owner":"អ្នកអភិវឌ្ឍន៍ឯកជន","location":"ចំការមន រាជធានីភ្នំពេញ","period":"សីហា ២០២៤ – មេសា ២០២៥","summary":"សសរស្ដម្ភខួង និងគ្រឹះកម្រាលសម្រាប់អគារពហុមុខងារ ដោយការងារដែក បេតុង និងការតេស្ត ត្រូវបានអនុវត្តដោយក្រុមតែមួយ។","scope":["សសរស្ដម្ភខួងចាក់នៅនឹងកន្លែង","ទ្រុងដែកដែលផលិតនៅការដ្ឋាន","ការចាក់គ្រឹះកម្រាលជាបន្តបន្ទាប់","ការតេស្តភាពរឹងមាំ និងបន្ទុក"],"gallery":[{"caption":"ការផលិតទ្រុងដែកធុនធ្ងន់សម្រាប់គ្រឹះជម្រៅ"},{"caption":"ការចងដែកសសររចនាសម្ព័ន្ធ និងការត្រួតពិនិត្យដោយវិស្វករ"},{"caption":"ការចាក់បេតុងគ្រឹះកម្រាលជាដុំតែមួយជាបន្តបន្ទាប់"},{"caption":"គ្រឹះកម្រាលបានថែរក្សាបេតុង និងបញ្ចប់រួចរាល់"}],"highlights":[{"value":"120","label":"សសរស្ដម្ភខួង","note":"800 និង 1,000 mm"},{"value":"32","unit":"m","label":"ជម្រៅសសរស្ដម្ភ","note":"ក្រោមកម្រិតកាត់"},{"value":"1,850","unit":"m³","label":"ការចាក់គ្រឹះកម្រាល","note":"ចាក់តែម្ដងជាបន្តបន្ទាប់"},{"value":"9","unit":"mo","label":"រយៈពេលគម្រោង","note":"សីហា ២០២៤ – មេសា ២០២៥"}],"equipment":[{"name":"ម៉ាស៊ីនបោះសសរស្ដម្ភ"},{"name":"ស្ទូចច្រវាក់"},{"name":"រថយន្តលាយបេតុង"},{"name":"រថយន្តបូមបេតុង"}],"technical":[{"label":"សសរស្ដម្ភ","value":"សសរខួងចាក់នៅនឹងកន្លែង Ø 800 និង 1,000 mm"},{"label":"កម្រិតបេតុង","value":"គ្រឹះកម្រាល C40 សសរស្ដម្ភ C35"},{"label":"គ្រឹះកម្រាល","value":"កម្រាស់ 2.2 m ចាក់ជាបន្តបន្ទាប់រយៈពេល ២៦ ម៉ោង"}],"outcome":"គ្រឹះកម្រាលបានបញ្ចប់ក្នុងការចាក់តែម្ដង ដោយគ្មានសន្លាក់ត្រជាក់ ធានាឱ្យការងាររចនាសម្ព័ន្ធផ្នែកខាងលើបន្តតាមកាលវិភាគ។","slug":"phnom-penh-tower-foundations"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('projects:sihanoukville-fleet-hire', 'projects', 'sihanoukville-fleet-hire', 'published', 5, '{"slug":"sihanoukville-fleet-hire","sample":true,"name":"Pump & Mixer Fleet Hire","owner":"Main contractor, hotel development","location":"Preah Sihanouk","period":"Mar 2025 – Oct 2025","category":"Truck & Equipment Rental","summary":"Concrete pump and mixer trucks hired with operators to a main contractor for structural pours on a coastal hotel.","scope":["Pump trucks with experienced operators","Mixer trucks on daily call-off","On-site maintenance and refuelling","Daily equipment reports"],"gallery":[{"image":"/Image/bce/machinery_fleet.webp","caption":"BCE fleet of 41 mixer trucks with GPS dispatch"},{"image":"/Image/bce/stats_fleet.webp","caption":"Extended boom pump trucks mobilized for high-reach pour"},{"image":"/Image/bce/hse_safety.webp","caption":"BCE certified HSE team and certified operators"}],"equipment":[{"name":"Pump trucks","count":3},{"name":"Mixer trucks","count":6}]}', '{"name":"ការជួលកងរថយន្តបូម និងរថយន្តលាយបេតុង","owner":"អ្នកម៉ៅការធំ គម្រោងអភិវឌ្ឍន៍សណ្ឋាគារ","location":"ព្រះសីហនុ","period":"មីនា ២០២៥ – តុលា ២០២៥","summary":"ការជួលរថយន្តបូមបេតុង និងរថយន្តលាយបេតុង រួមទាំងអ្នកបើកបរដែលមានបទពិសោធន៍ ជូនអ្នកម៉ៅការធំ សម្រាប់ការចាក់បេតុងរចនាសម្ព័ន្ធសណ្ឋាគារតាមឆ្នេរសមុទ្រ។","scope":["រថយន្តបូមបេតុងជាមួយអ្នកបើកបរមានបទពិសោធន៍","រថយន្តលាយបេតុងតាមការហៅប្រចាំថ្ងៃ","ការថែទាំ និងបំពេញប្រេងនៅការដ្ឋាន","របាយការណ៍គ្រឿងចក្រប្រចាំថ្ងៃ"],"gallery":[{"caption":"កងរថយន្តលាយបេតុង ៤១ គ្រឿងរបស់ BCE ជាមួយប្រព័ន្ធបញ្ជូនតាម GPS"},{"caption":"រថយន្តបូមបេតុងដៃវែងដាក់ពង្រាយសម្រាប់ការចាក់នៅទីខ្ពស់"},{"caption":"ក្រុមការងារ HSE និងអ្នកបើកបរដែលមានវិញ្ញាបនបត្ររបស់ BCE"}],"equipment":[{"name":"រថយន្តបូមបេតុង"},{"name":"រថយន្តលាយបេតុង"}],"slug":"sihanoukville-fleet-hire"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
