INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('posts:aci-211-high-strength-mix-designs', 'posts', 'aci-211-high-strength-mix-designs', 'published', 0, '{"slug":"aci-211-high-strength-mix-designs","sample":true,"title":"High-Strength Mix Design for Heavy Industrial Pours in Battambang","category":"Concrete Technology","kind":"Insight","year":"2026","date":"15 April 2026","readTime":"5 min read","image":"/Image/bce/laboratory_qa.webp","alt":"BCE laboratory technician testing a concrete sample","excerpt":"A deep dive into how BCE engineers formulate compressive strengths from C20 to C40, balancing water-cement ratios and mineral admixtures for high-load industrial floors.","content":{"intro":"Modern industrial facilities and heavy logistics warehouses demand concrete floors that resist extreme wheel point loads, chemical exposure, and thermal cracking. At Battambang Construction and Engineering (BCE), our mix formulation follows a documented proportioning method, customized for local sand, coarse aggregates, and ambient tropical curing conditions.","sections":[{"heading":"Precision Water-Cement Ratios & Superplasticizer Integration","body":["Achieving compressive strength exceeding 40 MPa without causing brittle shrinkage cracks requires meticulous control of the water-cementitious ratio (w/c ≤ 0.38). In our computerized batching plants, moisture probes continuously measure the surface water on coarse and fine aggregates in real-time, instantly adjusting the batched mixing water.","Polycarboxylate ether (PCE) superplasticizers are automatically dosed to maintain a fluid slump of 160–180 mm for pumping without sacrificing the dense crystalline microstructure necessary for high early strength."],"callout":"Moisture sensors in all 4 BCE batching plants calibrate aggregate moisture every 30 seconds to maintain exact design water-cement ratios."},{"heading":"Aggregate Gradation & Strength Verification","body":["We utilize crushed basalt aggregate graded strictly between 10mm and 20mm with less than 1% clay loam content. Combined with river sand having a fineness modulus of 2.6 to 2.8, the resulting concrete matrix achieves minimum void space and optimal particle packing.","Standard 150mm test cylinders cast from each dispatch batch are submerged in saturated lime water curing tanks and broken at 7 and 28 days using our digital compression testing machine to guarantee design compliance."]}],"takeaways":["The approved design is checked for workability and strength before it is used on site.","Computerized batching eliminates manual measurement variations across large continuous pours.","Full third-party and in-house laboratory test certificates accompany every commercial dispatch."]},"author":{"name":"Eng. Sokhom Seng","role":"Lead Materials & Batching Engineer, BCE"}}', '{"title":"រូបមន្តលាយបេតុងកម្លាំងខ្ពស់សម្រាប់ការចាក់បេតុងឧស្សាហកម្មធ្ងន់នៅបាត់ដំបង","kind":"Insight","alt":"អ្នកបច្ចេកទេសមន្ទីរពិសោធន៍ BCE កំពុងពិនិត្យគំរូបេតុង","excerpt":"ការវិភាគស៊ីជម្រៅអំពីរបៀបដែលវិស្វករ BCE បង្កើតរូបមន្តកម្លាំងសង្កត់ពី C20 ដល់ C40 ដោយធ្វើឱ្យមានតុល្យភាពរវាងសមាមាត្រទឹក-ស៊ីម៉ងត៍ និងសារធាតុបន្ថែមរ៉ែ សម្រាប់កម្រាលបេតុងឧស្សាហកម្មដែលផ្ទុកបន្ទុកខ្ពស់។","content":{"intro":"រោងចក្រឧស្សាហកម្មទំនើប និងឃ្លាំងដឹកជញ្ជូនធ្ងន់ តម្រូវឱ្យមានកម្រាលបេតុងដែលអាចទប់ទល់នឹងបន្ទុកចំណុចពីកង់យានយន្តយ៉ាងធ្ងន់ ការប៉ះពាល់សារធាតុគីមី និងស្នាមប្រេះដោយសារកម្តៅ។ នៅក្រុមហ៊ុន បាត់ដំបង ខនស្ត្រាក់សិន អេន អេនជីនារីង (BCE) ការបង្កើតរូបមន្តលាយបេតុងរបស់យើង អនុវត្តតាមវិធីសាស្ត្រកំណត់សមាមាត្រដែលមានឯកសារច្បាស់លាស់ ដោយកែសម្រួលឱ្យសមនឹងខ្សាច់ក្នុងតំបន់ ថ្មសំណង់ និងលក្ខខណ្ឌថែរក្សាបេតុងក្នុងអាកាសធាតុក្តៅស្តុកស្តម្ភ។","sections":[{"heading":"សមាមាត្រទឹក-ស៊ីម៉ងត៍យ៉ាងជាក់លាក់ និងការបញ្ចូលសារធាតុបន្ថែមបន្ទន់បេតុងកម្រិតខ្ពស់","body":["ការសម្រេចបានកម្លាំងសង្កត់លើសពី 40 MPa ដោយមិនបង្កឱ្យកើតស្នាមប្រេះផុយដោយសារការរួមតូច តម្រូវឱ្យមានការគ្រប់គ្រងយ៉ាងម៉ត់ចត់លើសមាមាត្រទឹក-សារធាតុចង (w/c ≤ 0.38)។ នៅក្នុងរោងចក្រលាយបេតុងដែលប្រើប្រាស់ប្រព័ន្ធកុំព្យូទ័ររបស់យើង ឧបករណ៍វាស់សំណើមវាស់ទឹកលើផ្ទៃថ្ម និងខ្សាច់ជាបន្តបន្ទាប់ក្នុងពេលជាក់ស្តែង ហើយកែតម្រូវបរិមាណទឹកសម្រាប់លាយភ្លាមៗ។","សារធាតុបន្ថែមបន្ទន់បេតុងប្រភេទ Polycarboxylate ether (PCE) ត្រូវបានបញ្ចូលដោយស្វ័យប្រវត្តិ ដើម្បីរក្សាកម្រិតស្រុតឱ្យរលូន 160–180 mm សម្រាប់ការបូម ដោយមិនបាត់បង់រចនាសម្ព័ន្ធគ្រីស្តាល់តូចល្អិតដិតណែន ដែលចាំបាច់សម្រាប់កម្លាំងដំបូងខ្ពស់។"],"callout":"ឧបករណ៍វាស់សំណើមនៅក្នុងរោងចក្រលាយបេតុងទាំង 4 របស់ BCE ធ្វើការក្រិតតម្រូវសំណើមថ្មរៀងរាល់ 30 វិនាទី ដើម្បីរក្សាសមាមាត្រទឹក-ស៊ីម៉ងត៍តាមការរចនាឱ្យបានច្បាស់លាស់។"},{"heading":"ការចាត់ថ្នាក់ទំហំថ្ម និងការផ្ទៀងផ្ទាត់កម្លាំង","body":["យើងប្រើប្រាស់ថ្មបាសាល់បំបែក ដែលមានទំហំចាត់ថ្នាក់យ៉ាងតឹងរ៉ឹងចន្លោះ 10mm ដល់ 20mm និងមានសារធាតុដីឥដ្ឋលាយខ្សាច់តិចជាង 1%។ នៅពេលផ្សំជាមួយខ្សាច់ទន្លេ ដែលមានម៉ូឌុលភាពល្អិតពី 2.6 ដល់ 2.8 ម៉ាទ្រីសបេតុងដែលទទួលបាន មានចន្លោះប្រហោងតិចបំផុត និងការរៀបចំភាគល្អិតបានល្អប្រសើរ។","គំរូស៊ីឡាំងសាកល្បងស្តង់ដារ 150mm ដែលចាក់ចេញពីរាល់ការបញ្ជូនម្តងៗ ត្រូវបានដាក់លិចក្នុងធុងថែរក្សាបេតុងដែលមានទឹកកំបោរឆ្អែត ហើយបំបែកនៅថ្ងៃទី 7 និងថ្ងៃទី 28 ដោយប្រើម៉ាស៊ីនសាកល្បងកម្លាំងសង្កត់ឌីជីថលរបស់យើង ដើម្បីធានាការអនុលោមតាមការរចនា។"]}],"takeaways":["រូបមន្តដែលបានអនុម័ត ត្រូវបានពិនិត្យលើភាពងាយស្រួលក្នុងការប្រើប្រាស់ និងកម្លាំង មុនពេលនាំយកទៅប្រើនៅការដ្ឋាន។","ការលាយបេតុងដោយប្រព័ន្ធកុំព្យូទ័រ លុបបំបាត់ភាពប្រែប្រួលនៃការវាស់វែងដោយដៃ ក្នុងការចាក់បេតុងធំៗជាបន្តបន្ទាប់។","វិញ្ញាបនបត្រលទ្ធផលពិសោធន៍ពេញលេញ ទាំងពីភាគីទីបី និងពីមន្ទីរពិសោធន៍ផ្ទៃក្នុង ភ្ជាប់មកជាមួយរាល់ការបញ្ជូនបេតុងពាណិជ្ជកម្ម។"]},"author":{"name":"វិស្វករ សុខុម សេង","role":"ប្រធានវិស្វករវត្ថុធាតុ និងការលាយបេតុង, BCE"},"slug":"aci-211-high-strength-mix-designs"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('posts:hydraulic-static-piling-soft-alluvial-soil', 'posts', 'hydraulic-static-piling-soft-alluvial-soil', 'published', 1, '{"slug":"hydraulic-static-piling-soft-alluvial-soil","sample":true,"title":"Precision Piling in Soft Alluvial Soil Formations","category":"Foundation Piling","kind":"Insight","year":"2026","date":"28 March 2026","readTime":"6 min read","image":"/Image/bce/about-zoom-piling-rig.webp","alt":"BCE piling rig working on a foundation site","excerpt":"How low-vibration piling methods reduce risk to adjacent structures in soft alluvial ground.","content":{"intro":"Foundations built along the Sangkae River basin encounter deep alluvial silt layers with low shear resistance. Traditional diesel hammer pile driving generates ground shockwaves that threaten adjacent historical shophouses and residential buildings. BCE’s piling rigs provide a controlled, low-vibration solution suited to sites where ground movement must be limited.","sections":[{"heading":"Vibration-Free Jacking Mechanics","body":["The hydraulic static pressing machine grips precast reinforced concrete square piles (from 250x250mm to 400x400mm) using high-pressure clamping jaws. Dual main hydraulic cylinders apply continuous downward thrust, smoothly pushing the pile into the subsoil without dynamic percussion.","Because the method develops pile capacity without heavy impact, it can be used where vibration and noise need to be controlled near existing structures."],"callout":"Static pressing reduces noise levels below 65 dB and eliminates ground vibrations, enabling 24/7 urban operations without municipal disruption."},{"heading":"Real-Time Digital Load-Settlement Gauging","body":["Every stroke of the hydraulic press is monitored via digital pressure transducers calibrated directly to ultimate pressing tonnage. Engineers log the exact terminal refusal load for every single pile, providing instant verification of foundation bearing capacity before casting the pile cap."]}],"takeaways":["Zero shockwaves protect neighboring foundations and underground utility lines.","Continuous digital load monitoring replaces uncertain hammer blow count estimates.","Enables faster installation of multi-section welded driven piles up to 28 meters depth."]},"author":{"name":"Eng. Chanthy Rath","role":"Chief Geotechnical & Piling Engineer, BCE"}}', '{"title":"ការបោះសសរស្ដម្ភយ៉ាងជាក់លាក់ក្នុងស្រទាប់ដីល្បាប់ទន់","kind":"Insight","alt":"ម៉ាស៊ីនបោះសសរស្ដម្ភរបស់ BCE កំពុងធ្វើការនៅការដ្ឋានគ្រឹះ","excerpt":"របៀបដែលវិធីបោះសសរស្ដម្ភដែលមានរំញ័រទាប កាត់បន្ថយហានិភ័យដល់សំណង់ជិតខាងនៅលើដីល្បាប់ទន់។","content":{"intro":"គ្រឹះដែលសាងសង់នៅតាមអាងទន្លេសាំងគែ ជួបប្រទះស្រទាប់ដីល្បាប់ជ្រៅ ដែលមានភាពធន់ទ្រាំនឹងការកាត់ទាប។ ការបោះសសរដោយប្រើញញួរម៉ាស៊ូតតាមបែបប្រពៃណី បង្កើតរលកញ័រទង្គិចដី ដែលគំរាមកំហែងដល់ផ្ទះជួរបុរាណ និងអគារលំនៅដ្ឋាននៅជិតខាង។ ម៉ាស៊ីនបោះសសរស្ដម្ភរបស់ BCE ផ្តល់នូវដំណោះស្រាយដែលអាចគ្រប់គ្រងបាន និងមានរំញ័រទាប ដែលសមស្របសម្រាប់ការដ្ឋានដែលចាំបាច់ត្រូវកំណត់ចលនាដី។","sections":[{"heading":"យន្តការចុចសសរដោយគ្មានរំញ័រ","body":["ម៉ាស៊ីនចុចសសរធារាសាស្ត្របែបស្ថិតិ កាន់សសរស្ដម្ភបេតុងអារម៉េរាងបួនជ្រុង (ពី 250x250mm ដល់ 400x400mm) ដោយប្រើថ្គាមចាប់សម្ពាធខ្ពស់។ ស៊ីឡាំងធារាសាស្ត្រមេពីរ បង្កលំនាំរុញចុះក្រោមជាបន្ត ដោយរុញសសរចូលទៅក្នុងដីបានយ៉ាងរលូន ដោយគ្មានការប៉ះទង្គិចថាមពល។","ដោយសារវិធីនេះបង្កើតសមត្ថភាពទ្រទ្រង់របស់សសរ ដោយគ្មានការប៉ះទង្គិចធ្ងន់ វាអាចប្រើប្រាស់បាននៅកន្លែងដែលចាំបាច់ត្រូវគ្រប់គ្រងរំញ័រ និងសំឡេងរំខាននៅជិតសំណង់ដែលមានស្រាប់។"],"callout":"ការចុចសសរបែបស្ថិតិ កាត់បន្ថយកម្រិតសំឡេងឱ្យទាបជាង 65 dB និងលុបបំបាត់រំញ័រដី ដែលអនុញ្ញាតឱ្យធ្វើការក្នុងទីក្រុងបាន 24/7 ដោយមិនបង្កការរំខានដល់សាធារណៈ។"},{"heading":"ការវាស់បន្ទុក-ការស្រុតដីឌីជីថលក្នុងពេលជាក់ស្តែង","body":["រាល់សង្កាត់នៃការចុចដោយម៉ាស៊ីនធារាសាស្ត្រ ត្រូវបានតាមដានតាមរយៈឧបករណ៍ប្តូរសញ្ញាសម្ពាធឌីជីថល ដែលក្រិតតម្រូវដោយផ្ទាល់ទៅនឹងកម្រិតតោននៃការចុចអតិបរមា។ វិស្វករកត់ត្រាបន្ទុកចុងក្រោយពិតប្រាកដ ដែលសសរឈប់ចុះបន្ថែម សម្រាប់សសរនីមួយៗ ដែលផ្តល់ការផ្ទៀងផ្ទាត់ភ្លាមៗអំពីសមត្ថភាពទ្រទ្រង់បន្ទុករបស់គ្រឹះ មុនពេលចាក់ក្បាលសសរ។"]}],"takeaways":["គ្មានរលកញ័រទង្គិច ដែលជួយការពារគ្រឹះជិតខាង និងខ្សែសាធារណប្រយោជន៍ក្រោមដី។","ការតាមដានបន្ទុកឌីជីថលជាបន្ត ជំនួសការប៉ាន់ស្មានចំនួនដងវាយញញួរ ដែលមិនច្បាស់លាស់។","អនុញ្ញាតឱ្យដំឡើងសសរស្ដម្ភចាក់ ដែលផ្សារភ្ជាប់ពីច្រើនកំណាត់ បានលឿនជាងមុន រហូតដល់ជម្រៅ 28 ម៉ែត្រ។"]},"author":{"name":"វិស្វករ ចាន់ធី រ៉ាត់","role":"ប្រធានវិស្វករភូគព្ភសាស្ត្រ និងការបោះសសរស្ដម្ភ, BCE"},"slug":"hydraulic-static-piling-soft-alluvial-soil"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('posts:dye-2000-compressive-strength-testing', 'posts', 'dye-2000-compressive-strength-testing', 'published', 2, '{"slug":"dye-2000-compressive-strength-testing","sample":true,"title":"Compressive Testing: How BCE Validates 28-Day Strength Across 4 Batching Plants","category":"Quality & Lab","kind":"Insight","year":"2026","date":"12 March 2026","readTime":"4 min read","image":"/Image/bce/about-hse-banner.webp","alt":"Concrete cylinder under compression testing in the BCE laboratory","excerpt":"Inside BCE’s in-house testing laboratory: our systematic protocol for casting standard test cylinders, water tank curing, and digital breaking to documented test procedures.","content":{"intro":"Consistent concrete quality cannot rely on visual inspection alone. BCE maintains a dedicated in-house testing laboratory in Battambang equipped with a digital compression testing machine. This facility guarantees that every cubic meter poured on our clients'' sites satisfies structural engineering specifications.","sections":[{"heading":"Sampling and test cylinder preparation","body":["Sampling occurs directly at the discharge chute of mixer trucks on site or at the batching plant. Technicians cast standard 150mm x 300mm cylindrical specimens in three equal layers, tamping each layer with a standard tamping rod.","Specimens are kept in moist ambient air for 24 hours before demolding, followed by complete immersion in temperature-controlled curing tanks at 23°C ± 2°C until test age."]},{"heading":"Automated Digital Rupture Analysis","body":["The testing machine applies a controlled compressive load until the cylinder fails. Microprocessor sensors record the peak fracture load, automatically calculating MPa strength and plotting failure curves to verify standard cone-and-split rupture patterns."],"callout":"Formal test reports generated by our laboratory provide clients, consulting engineers, and financial auditors with verifiable compliance certificates."}],"takeaways":["In-house testing delivers preliminary 7-day strength results within hours of de-molding.","Calibrated digital instrumentation removes manual reading error.","Documented sampling, curing and strength testing."]},"author":{"name":"Vannak Meas","role":"Senior Laboratory Quality Inspector, BCE"}}', '{"title":"ការសាកល្បងកម្លាំងសង្កត់៖ របៀបដែល BCE ផ្ទៀងផ្ទាត់កម្លាំងរយៈពេល 28 ថ្ងៃ នៅរោងចក្រលាយបេតុងទាំង 4","kind":"Insight","alt":"គំរូស៊ីឡាំងបេតុងកំពុងសាកល្បងកម្លាំងសង្កត់ក្នុងមន្ទីរពិសោធន៍ BCE","excerpt":"ចូលទៅខាងក្នុងមន្ទីរពិសោធន៍ផ្ទៃក្នុងរបស់ BCE៖ នីតិវិធីជាប្រព័ន្ធរបស់យើងសម្រាប់ការចាក់គំរូស៊ីឡាំងសាកល្បងស្តង់ដារ ការថែរក្សាក្នុងធុងទឹក និងការបំបែកដោយឌីជីថល ស្របតាមនីតិវិធីសាកល្បងដែលមានឯកសារ។","content":{"intro":"គុណភាពបេតុងដែលស្ថិតស្ថេរ មិនអាចពឹងផ្អែកតែលើការត្រួតពិនិត្យដោយភ្នែកនោះទេ។ BCE មានមន្ទីរពិសោធន៍ផ្ទៃក្នុងដោយឡែកនៅបាត់ដំបង ដែលបំពាក់ដោយម៉ាស៊ីនសាកល្បងកម្លាំងសង្កត់ឌីជីថល។ មន្ទីរនេះធានាថា គ្រប់ម៉ែត្រគូបដែលបានចាក់នៅការដ្ឋានរបស់អតិថិជន ស្របតាមលក្ខណៈបច្ចេកទេសវិស្វកម្មសំណង់។","sections":[{"heading":"ការយកគំរូ និងការរៀបចំស៊ីឡាំងសាកល្បង","body":["ការយកគំរូធ្វើឡើងដោយផ្ទាល់នៅរន្ធបញ្ចេញបេតុងរបស់រថយន្តលាយបេតុងនៅការដ្ឋាន ឬនៅរោងចក្រលាយបេតុង។ អ្នកបច្ចេកទេសចាក់គំរូស៊ីឡាំងស្តង់ដារ 150mm x 300mm ជាបីស្រទាប់ស្មើគ្នា ដោយបុកស្រទាប់នីមួយៗដោយដំបងបុកស្តង់ដារ។","គំរូត្រូវបានរក្សាទុកក្នុងខ្យល់មានសំណើមធម្មតារយៈពេល 24 ម៉ោង មុនពេលដកចេញពីទម្រង់ បន្ទាប់មកដាក់លិចទាំងស្រុងក្នុងធុងថែរក្សាបេតុង ដែលគ្រប់គ្រងសីតុណ្ហភាព 23°C ± 2°C រហូតដល់អាយុសាកល្បង។"]},{"heading":"ការវិភាគការប្រេះដោយឌីជីថលស្វ័យប្រវត្តិ","body":["ម៉ាស៊ីនសាកល្បងអនុវត្តបន្ទុកសង្កត់ដែលគ្រប់គ្រងបាន រហូតដល់ស៊ីឡាំងប្រេះខូច។ ឧបករណ៍ចាប់សញ្ញាមីក្រូប្រូសេស័រ កត់ត្រាបន្ទុកបំបែកខ្ពស់បំផុត ដោយគណនាកម្លាំងជា MPa ដោយស្វ័យប្រវត្តិ និងគូសក្រាហ្វខ្សែកោងបំបែក ដើម្បីផ្ទៀងផ្ទាត់លំនាំប្រេះរាងកោណ និងបំបែកតាមស្តង់ដារ។"],"callout":"របាយការណ៍សាកល្បងផ្លូវការ ដែលចេញដោយមន្ទីរពិសោធន៍របស់យើង ផ្តល់ឱ្យអតិថិជន វិស្វករប្រឹក្សា និងសវនករហិរញ្ញវត្ថុ នូវវិញ្ញាបនបត្រអនុលោមភាព ដែលអាចផ្ទៀងផ្ទាត់បាន។"}],"takeaways":["ការសាកល្បងផ្ទៃក្នុង ផ្តល់លទ្ធផលកម្លាំងបឋមរយៈពេល 7 ថ្ងៃ ក្នុងរយៈពេលប៉ុន្មានម៉ោងបន្ទាប់ពីដកចេញពីទម្រង់។","ឧបករណ៍ឌីជីថលដែលបានក្រិតតម្រូវ លុបបំបាត់កំហុសនៃការអានដោយដៃ។","ការយកគំរូ ការថែរក្សាបេតុង និងការសាកល្បងកម្លាំង សុទ្ធតែមានឯកសារកត់ត្រាច្បាស់លាស់។"]},"author":{"name":"វណ្ណៈ មាស","role":"អ្នកត្រួតពិនិត្យគុណភាពជាន់ខ្ពស់ប្រចាំមន្ទីរពិសោធន៍, BCE"},"slug":"dye-2000-compressive-strength-testing"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('posts:bce-fleet-expansion-41-mixers-8-pumps', 'posts', 'bce-fleet-expansion-41-mixers-8-pumps', 'published', 3, '{"slug":"bce-fleet-expansion-41-mixers-8-pumps","sample":true,"title":"Fleet Capability: 8 Pump Trucks and 41 Mixer Trucks Across Cambodia","category":"Fleet & Equipment","kind":"Insight","year":"2025","date":"18 November 2025","readTime":"4 min read","image":"/Image/bce/machinery_fleet.webp","alt":"BCE mixer trucks and pump trucks at a batching plant","excerpt":"How BCE plans production, dispatch and maintenance around one owned fleet of batching plants, mixer trucks and concrete pumps.","content":{"intro":"A continuous pour depends on production and delivery being planned together. BCE runs its own batching plants, 41 mixer trucks and 8 pump trucks, so plant output, truck cycles and the placing programme are managed by one team rather than assembled from subcontractors.","sections":[{"heading":"Planning the pour sequence","body":["Deliveries are sequenced around the contractor''s pour programme and the placing crew''s position on site. The aim is a steady supply that keeps the pour moving without trucks waiting or cold joints forming.","For larger pours, production is planned across plants and trucks in advance, with the site team confirming access, discharge points and the order in which each section will be placed."]},{"heading":"Pump reach and site access","body":["Boom and line pumps are selected for the placing point, site access and outrigger space. Pump requirements are confirmed during quotation so the right unit is mobilised rather than substituted on the day.","Where a mixer cannot reach the pour, concrete is pumped through a planned pipeline route agreed with the site team before delivery begins."]},{"heading":"Maintenance between pours","body":["Mixer trucks and pumps are maintained by BCE''s own team. Checks are carried out between pours, with planned servicing scheduled around the delivery programme so maintenance does not interrupt a committed pour."]}],"takeaways":["41 mixer trucks and 8 pump trucks in BCE''s own fleet.","Production and delivery planned together from four batching plants.","Pump type and site access confirmed at quotation."]},"author":{"name":"BCE Fleet & Dispatch Team","role":"Fleet operations, BCE"}}', '{"title":"សមត្ថភាពកងយានយន្ត៖ រថយន្តបូមបេតុង 8 គ្រឿង និងរថយន្តលាយបេតុង 41 គ្រឿង ទូទាំងប្រទេសកម្ពុជា","kind":"Insight","alt":"រថយន្តលាយបេតុង និងរថយន្តបូមបេតុងរបស់ BCE នៅរោងចក្រលាយបេតុង","excerpt":"របៀបដែល BCE រៀបចំផែនការផលិតកម្ម ការបញ្ជូន និងការថែទាំ ជុំវិញកងយានយន្តដែលជាកម្មសិទ្ធិផ្ទាល់ខ្លួន ដែលរួមមានរោងចក្រលាយបេតុង រថយន្តលាយបេតុង និងរថយន្តបូមបេតុង។","content":{"intro":"ការចាក់បេតុងជាបន្តបន្ទាប់ ពឹងផ្អែកលើការរៀបចំផែនការផលិតកម្ម និងការដឹកជញ្ជូនរួមគ្នា។ BCE ដំណើរការរោងចក្រលាយបេតុង រថយន្តលាយបេតុង 41 គ្រឿង និងរថយន្តបូមបេតុង 8 គ្រឿង ជាកម្មសិទ្ធិផ្ទាល់ខ្លួន ដូច្នេះទិន្នផលរោងចក្រ វដ្តរថយន្ត និងកម្មវិធីចាក់បេតុង ត្រូវបានគ្រប់គ្រងដោយក្រុមតែមួយ ជាជាងការផ្គុំពីអ្នកម៉ៅការបន្តរង។","sections":[{"heading":"ការរៀបចំផែនការលំដាប់នៃការចាក់បេតុង","body":["ការដឹកជញ្ជូនត្រូវបានរៀបចំតាមលំដាប់ ស្របតាមកម្មវិធីចាក់បេតុងរបស់អ្នកម៉ៅការ និងទីតាំងរបស់ក្រុមការងារចាក់បេតុងនៅការដ្ឋាន។ គោលដៅគឺការផ្គត់ផ្គង់ប្រកបដោយស្ថិរភាព ដែលរក្សាការចាក់បេតុងឱ្យដំណើរការបន្ត ដោយមិនឱ្យរថយន្តរង់ចាំ ឬកើតមានសន្លាក់ត្រជាក់។","សម្រាប់ការចាក់បេតុងធំៗ ការផលិតត្រូវបានរៀបចំផែនការឆ្លងកាត់រោងចក្រ និងរថយន្តជាមុន ដោយក្រុមការងារនៅការដ្ឋានផ្ទៀងផ្ទាត់ផ្លូវចូល ចំណុចបញ្ចេញបេតុង និងលំដាប់នៃការចាក់បេតុងក្នុងផ្នែកនីមួយៗ។"]},{"heading":"ចម្ងាយបូម និងផ្លូវចូលការដ្ឋាន","body":["រថយន្តបូមបេតុងប្រភេទដងដៃ និងប្រភេទបូមតាមបំពង់ ត្រូវបានជ្រើសរើសតាមចំណុចចាក់បេតុង ផ្លូវចូលការដ្ឋាន និងទីធ្លាសម្រាប់ជើងទម្របូម។ តម្រូវការបូមត្រូវបានបញ្ជាក់ក្នុងអំឡុងពេលធ្វើសម្រង់តម្លៃ ដើម្បីឱ្យគ្រឿងចក្រត្រឹមត្រូវត្រូវបានដាក់ពង្រាយ ជាជាងការប្តូរជំនួសនៅថ្ងៃចាក់បេតុង។","កន្លែងណាដែលរថយន្តលាយបេតុងមិនអាចទៅដល់ចំណុចចាក់បេតុង បេតុងត្រូវបានបូមតាមផ្លូវបំពង់ដែលបានរៀបចំផែនការ និងព្រមព្រៀងជាមួយក្រុមការងារការដ្ឋាន មុនពេលចាប់ផ្តើមដឹកជញ្ជូន។"]},{"heading":"ការថែទាំរវាងការចាក់បេតុង","body":["រថយន្តលាយបេតុង និងរថយន្តបូមបេតុង ត្រូវបានថែទាំដោយក្រុមការងារផ្ទាល់ខ្លួនរបស់ BCE។ ការត្រួតពិនិត្យត្រូវបានធ្វើឡើងរវាងការចាក់បេតុងនីមួយៗ ដោយការថែទាំតាមផែនការ ត្រូវបានកំណត់ពេលជុំវិញកម្មវិធីដឹកជញ្ជូន ដើម្បីកុំឱ្យការថែទាំរំខានដល់ការចាក់បេតុងដែលបានសន្យា។"]}],"takeaways":["រថយន្តលាយបេតុង 41 គ្រឿង និងរថយន្តបូមបេតុង 8 គ្រឿង ក្នុងកងយានយន្តផ្ទាល់ខ្លួនរបស់ BCE។","ការផលិត និងការដឹកជញ្ជូន ត្រូវបានរៀបចំផែនការរួមគ្នាពីរោងចក្រលាយបេតុងចំនួន 4។","ប្រភេទរថយន្តបូម និងផ្លូវចូលការដ្ឋាន ត្រូវបានបញ្ជាក់នៅពេលធ្វើសម្រង់តម្លៃ។"]},"author":{"name":"ក្រុមកងយានយន្ត និងការបញ្ជូន BCE","role":"ប្រតិបត្តិការកងយានយន្ត, BCE"},"slug":"bce-fleet-expansion-41-mixers-8-pumps"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
