INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('posts:hot-weather-concreting-ice-batching', 'posts', 'hot-weather-concreting-ice-batching', 'published', 4, '{"slug":"hot-weather-concreting-ice-batching","sample":true,"title":"Hot-Weather Concreting in Cambodia: Batching, Retarders and Curing","category":"Concrete Technology","kind":"Insight","year":"2025","date":"24 August 2025","readTime":"5 min read","image":"/Image/bce/hero_batching_plant.webp","alt":"BCE batching plant and aggregate yard","excerpt":"When temperatures exceed 36°C, hydration accelerates rapidly. Learn how BCE maintains fresh concrete temperatures below 32°C using flaked ice batching and extended set retarders.","content":{"intro":"During Cambodia’s dry season, daytime ambient temperatures regularly rise above 35°C to 38°C. Without specialized thermal management, high temperatures accelerate cement hydration, increase water demand, reduce 28-day ultimate strength, and trigger rapid plastic shrinkage cracking.","sections":[{"heading":"Chilled Water & Flaked Ice Substitution","body":["At our central batching plants, mixing water is pre-chilled through industrial water chilling units. On critical heavy structural pours, up to 60% of the batching water is substituted with flaked ice directly in the twin-shaft mixer.","Because the latent heat of fusion of melting ice absorbs 334 J/g of heat, the fresh concrete discharge temperature is kept within the specified limit on site arrival."]},{"heading":"Extended Hydration Retarders","body":["Water-reducing and retarding admixtures are dosed to extend setting time when a longer haul or a hot day requires it. This prevents flash setting during traffic transit and ensures complete consolidation around dense rebar cages."]}],"takeaways":["Ice batching keeps fresh concrete under 32°C to prevent thermal micro-cracking.","Set retarders provide working time for extensive slab finishing and laser screeding.","Night pouring schedules deployed for large continuous industrial floor slabs."]},"author":{"name":"Eng. Sokhom Seng","role":"Lead Materials & Batching Engineer, BCE"}}', '{"title":"ការចាក់បេតុងក្នុងអាកាសធាតុក្តៅនៅកម្ពុជា៖ ការលាយបេតុង សារធាតុពន្យារការរឹងខ្លួន និងការថែរក្សាបេតុង","kind":"Insight","alt":"រោងចក្រលាយបេតុង និងទីធ្លាថ្មរបស់ BCE","excerpt":"នៅពេលសីតុណ្ហភាពលើស 36°C ដំណើរការរីករាលនៃស៊ីម៉ងត៍កើនលឿនយ៉ាងខ្លាំង។ ស្វែងយល់ពីរបៀបដែល BCE រក្សាសីតុណ្ហភាពបេតុងស្រស់ឱ្យទាបជាង 32°C ដោយប្រើការលាយបេតុងជាមួយទឹកកកស្នាប់ និងសារធាតុពន្យារការរឹងខ្លួនបន្ថែម។","content":{"intro":"ក្នុងរដូវប្រាំងនៅកម្ពុជា សីតុណ្ហភាពព័ទ្ធជុំវិញពេលថ្ងៃ ជាទូទៅកើនឡើងលើសពី 35°C ដល់ 38°C។ បើគ្មានការគ្រប់គ្រងកម្តៅជាពិសេសទេ សីតុណ្ហភាពខ្ពស់ធ្វើឱ្យដំណើរការរីករាលនៃស៊ីម៉ងត៍កើនលឿន បង្កើនតម្រូវការទឹក បន្ថយកម្លាំងអតិបរមារយៈពេល 28 ថ្ងៃ និងបង្កឱ្យកើតស្នាមប្រេះដោយសារការរួមតូចប្លាស្ទិកយ៉ាងរហ័ស។","sections":[{"heading":"ការប្រើទឹកត្រជាក់ និងការជំនួសដោយទឹកកកស្នាប់","body":["នៅរោងចក្រលាយបេតុងកណ្តាលរបស់យើង ទឹកសម្រាប់លាយត្រូវបានធ្វើឱ្យត្រជាក់ជាមុន តាមរយៈឧបករណ៍ធ្វើទឹកត្រជាក់បែបឧស្សាហកម្ម។ សម្រាប់ការចាក់បេតុងរចនាសម្ព័ន្ធធ្ងន់ដែលសំខាន់ៗ ទឹកសម្រាប់លាយរហូតដល់ 60% ត្រូវបានជំនួសដោយទឹកកកស្នាប់ ដោយផ្ទាល់នៅក្នុងម៉ាស៊ីនលាយបេតុងពីរអ័ក្ស។","ដោយសារកម្តៅអាថ៌កំបាំងនៃការរលាយរបស់ទឹកកក ស្រូបយកកម្តៅ 334 J/g សីតុណ្ហភាពបេតុងស្រស់នៅពេលបញ្ចេញ ត្រូវបានរក្សាក្នុងកម្រិតកំណត់ នៅពេលទៅដល់ការដ្ឋាន។"]},{"heading":"សារធាតុពន្យារការរឹងខ្លួនបន្ថែម","body":["សារធាតុបន្ថែមបន្ថយទឹក និងពន្យារការរឹងខ្លួន ត្រូវបានបញ្ចូលក្នុងបរិមាណសមស្រប ដើម្បីពន្យារពេលរឹងខ្លួន នៅពេលត្រូវការដឹកជញ្ជូនចម្ងាយឆ្ងាយ ឬថ្ងៃក្តៅខ្លាំង។ នេះការពារការរឹងខ្លួនភ្លាមៗក្នុងអំឡុងពេលធ្វើដំណើរតាមចរាចរណ៍ និងធានាការបង្រួមបេតុងពេញលេញជុំវិញសំណាញ់ដែកគោលក្រាស់។"]}],"takeaways":["ការលាយបេតុងជាមួយទឹកកក រក្សាបេតុងស្រស់ឱ្យក្រោម 32°C ដើម្បីការពារស្នាមប្រេះតូចៗដោយសារកម្តៅ។","សារធាតុពន្យារការរឹងខ្លួន ផ្តល់ពេលវេលាធ្វើការគ្រប់គ្រាន់ សម្រាប់ការតុបតែងកម្រាលបេតុងធំៗ និងការកោរកម្រាលបេតុងដោយឡាស៊ែរ។","កាលវិភាគចាក់បេតុងពេលយប់ ត្រូវបានអនុវត្តសម្រាប់កម្រាលបេតុងឧស្សាហកម្មធំៗ ដែលចាក់ជាបន្តបន្ទាប់។"]},"author":{"name":"វិស្វករ សុខុម សេង","role":"ប្រធានវិស្វករវត្ថុធាតុ និងការលាយបេតុង, BCE"},"slug":"hot-weather-concreting-ice-batching"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('posts:one-million-safe-man-hours-milestone', 'posts', 'one-million-safe-man-hours-milestone', 'published', 5, '{"slug":"one-million-safe-man-hours-milestone","sample":true,"title":"Safety-First Infrastructure: How BCE Approaches Man-Hours on Complex Sites","category":"Site Quality & HSE","kind":"Insight","year":"2025","date":"10 June 2025","readTime":"4 min read","image":"/Image/bce/hse_safety.webp","alt":"BCE site crew in protective equipment","excerpt":"How BCE''s HSE management system works on site: shift briefings, equipment checks and clear responsibilities around every pour.","content":{"intro":"Heavy construction puts crews around boom pump lines, rotating mixer drums, piling rigs and deep excavations. BCE''s HSE management system is built around planning the work, briefing the crew and checking the equipment before each critical activity.","sections":[{"heading":"Brief the shift, not just the job","body":["Every shift starts with a briefing on the hazards specific to that site and pour: overhead lines, exclusion zones around rigs and pumps, access routes and the day''s sequence. Responsibilities are named, not assumed."]},{"heading":"Inspect before the pour","body":["Pump lines, clamps, safety pins, rigging and piling rig ropes are checked before work starts. Equipment with a defect is taken out of service rather than worked around."]},{"heading":"PPE and site rules","body":["Helmets, steel-toed boots, high-visibility clothing and eye protection are required on BCE sites. Visitors and subcontractors follow the same rules as BCE crews."]}],"takeaways":["Shift briefings cover the site, the pour and the day''s hazards.","Pumps, rigging and lifting equipment are inspected before critical work.","PPE and site rules apply to BCE crews, subcontractors and visitors."]},"author":{"name":"BCE HSE Team","role":"Health, Safety & Environment"}}', '{"title":"ហេដ្ឋារចនាសម្ព័ន្ធដែលផ្តល់អាទិភាពដល់សុវត្ថិភាព៖ របៀបដែល BCE គ្រប់គ្រងម៉ោងធ្វើការនៅការដ្ឋានស្មុគស្មាញ","kind":"Insight","alt":"ក្រុមការងារការដ្ឋាន BCE ក្នុងឧបករណ៍ការពារខ្លួន","excerpt":"របៀបដែលប្រព័ន្ធគ្រប់គ្រងសុខភាព សុវត្ថិភាព និងបរិស្ថាន (HSE) របស់ BCE ដំណើរការនៅការដ្ឋាន៖ ការប្រជុំផ្តល់ព័ត៌មានប្រចាំវេន ការត្រួតពិនិត្យឧបករណ៍ និងការកំណត់តួនាទីច្បាស់លាស់ជុំវិញរាល់ការចាក់បេតុង។","content":{"intro":"ការសាងសង់ធ្ងន់ ដាក់ក្រុមការងារនៅជុំវិញបំពង់បូមបេតុង ស្គរលាយបេតុងដែលកំពុងបង្វិល ម៉ាស៊ីនបោះសសរស្ដម្ភ និងរណ្តៅជីកជ្រៅ។ ប្រព័ន្ធគ្រប់គ្រង HSE របស់ BCE ត្រូវបានបង្កើតឡើងជុំវិញការរៀបចំផែនការការងារ ការផ្តល់ព័ត៌មានដល់ក្រុមការងារ និងការត្រួតពិនិត្យឧបករណ៍ មុនពេលធ្វើសកម្មភាពសំខាន់នីមួយៗ។","sections":[{"heading":"ផ្តល់ព័ត៌មានដល់វេនការងារ មិនត្រឹមតែការងារនោះទេ","body":["រាល់វេនការងារចាប់ផ្តើមដោយការប្រជុំផ្តល់ព័ត៌មានអំពីហានិភ័យជាក់លាក់នៃការដ្ឋាន និងការចាក់បេតុងនោះ៖ ខ្សែភ្លើងលើអាកាស តំបន់ហាមឃាត់ជុំវិញម៉ាស៊ីន និងរថយន្តបូម ផ្លូវចូល និងលំដាប់ការងារប្រចាំថ្ងៃ។ តួនាទីទទួលខុសត្រូវត្រូវបានកំណត់ជាក់លាក់ មិនមែនសន្មតយកទេ។"]},{"heading":"ត្រួតពិនិត្យមុនការចាក់បេតុង","body":["បំពង់បូម កន្លាស់ចាប់ ខ្ទាស់សុវត្ថិភាព ខ្សែចង និងខ្សែពួររបស់ម៉ាស៊ីនបោះសសរ ត្រូវបានត្រួតពិនិត្យមុនពេលចាប់ផ្តើមការងារ។ ឧបករណ៍ដែលមានបញ្ហាខូចខាត ត្រូវបានដកចេញពីការប្រើប្រាស់ ជាជាងការរកវិធីវាងវៃដើម្បីបន្តប្រើប្រាស់។"]},{"heading":"ឧបករណ៍ការពារខ្លួន និងវិន័យការដ្ឋាន","body":["មួកសុវត្ថិភាព ស្បែកជើងការពារកែងជើងធ្វើពីដែក សម្លៀកបំពាក់ឆ្លុះពន្លឺ និងឧបករណ៍ការពារភ្នែក គឺជាតម្រូវការចាំបាច់នៅការដ្ឋាន BCE។ ភ្ញៀវ និងអ្នកម៉ៅការបន្តរង អនុវត្តតាមវិន័យដូចគ្នានឹងក្រុមការងារ BCE។"]}],"takeaways":["ការប្រជុំផ្តល់ព័ត៌មានប្រចាំវេន គ្របដណ្តប់លើការដ្ឋាន ការចាក់បេតុង និងហានិភ័យប្រចាំថ្ងៃ។","រថយន្តបូម ខ្សែចង និងឧបករណ៍លើក ត្រូវបានត្រួតពិនិត្យមុនការងារសំខាន់ៗ។","ឧបករណ៍ការពារខ្លួន និងវិន័យការដ្ឋាន អនុវត្តចំពោះក្រុមការងារ BCE អ្នកម៉ៅការបន្តរង និងភ្ញៀវ។"]},"author":{"name":"ក្រុម HSE របស់ BCE","role":"សុខភាព សុវត្ថិភាព និងបរិស្ថាន"},"slug":"one-million-safe-man-hours-milestone"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('posts:30-years-of-bce-heritage-from-1995', 'posts', '30-years-of-bce-heritage-from-1995', 'published', 6, '{"slug":"30-years-of-bce-heritage-from-1995","sample":true,"title":"The History of BCE: 30 Years from Hong Huot Ly in 1995","category":"Company News","kind":"News","year":"2024","date":"14 December 2024","readTime":"6 min read","image":"/Image/bce/about-hero-banner.webp","alt":"Aerial view of a BCE batching plant and aggregate yard","excerpt":"How a modest local aggregate trading business founded in 1995 transformed into Battambang Construction and Engineering Co., Ltd. (BCE).","content":{"intro":"Three decades ago in 1995, Hong Huot Ly Co., Ltd. began operations supplying building materials and basic construction services to the recovering communities of Northwestern Cambodia. Through steady reinvestment in modern plant machinery and engineering talent, that enterprise evolved into Battambang Construction and Engineering Co., Ltd. (BCE).","sections":[{"heading":"Building Cambodia''s Resilient Foundations","body":["Under the leadership of Chairwoman Ms. Loeung Chan, BCE modernized operations in 2015, introducing computerized batching technology to replace manual drum mixers.","Today, BCE operates 4 central batching plants, 41 mixer trucks, 8 pump trucks, 7 hydraulic piling rigs, and an in-house materials testing laboratory serving 13 provinces and Phnom Penh."]},{"heading":"A Heritage of Trust & Integrity","body":["Over three decades, BCE has supplied concrete and construction services for residential, commercial, industrial and public projects across Cambodia."]}],"takeaways":["Established in 1995 with over 30 years of uninterrupted operational excellence.","Locally incorporated and managed in Cambodia.","Committed to supporting Cambodia’s next generation of civil engineering infrastructure."]},"author":{"name":"BCE Corporate Heritage Team","role":"Corporate Communications, BCE"}}', '{"title":"ប្រវត្តិរបស់ BCE៖ 30 ឆ្នាំ ចាប់ពីក្រុមហ៊ុន ហុង ហួត លី ក្នុងឆ្នាំ 1995","kind":"News","alt":"ទិដ្ឋភាពពីលើអាកាសនៃរោងចក្រលាយបេតុង និងទីធ្លាថ្មរបស់ BCE","excerpt":"របៀបដែលអាជីវកម្មពាណិជ្ជកម្មថ្មសំណង់ក្នុងតំបន់ដ៏តូចមួយ ដែលបានបង្កើតឡើងក្នុងឆ្នាំ 1995 បានវិវត្តទៅជាក្រុមហ៊ុន បាត់ដំបង ខនស្ត្រាក់សិន អេន អេនជីនារីង ខូអិលធីឌី (BCE)។","content":{"intro":"បីទសវត្សរ៍មុន ក្នុងឆ្នាំ 1995 ក្រុមហ៊ុន ហុង ហួត លី ខូអិលធីឌី បានចាប់ផ្តើមប្រតិបត្តិការ ដោយផ្គត់ផ្គង់សម្ភារសំណង់ និងសេវាកម្មសំណង់មូលដ្ឋាន ដល់សហគមន៍ដែលកំពុងរីកចម្រើនឡើងវិញនៅភាគពាយព្យកម្ពុជា។ តាមរយៈការវិនិយោគឡើងវិញជាប្រចាំ លើគ្រឿងចក្ររោងចក្រទំនើប និងធនធានមនុស្សផ្នែកវិស្វកម្ម សហគ្រាសនោះបានវិវត្តទៅជាក្រុមហ៊ុន បាត់ដំបង ខនស្ត្រាក់សិន អេន អេនជីនារីង ខូអិលធីឌី (BCE)។","sections":[{"heading":"ការកសាងគ្រឹះដ៏រឹងមាំឱ្យកម្ពុជា","body":["ក្រោមការដឹកនាំរបស់លោកស្រី លឿង ចាន់ ប្រធានក្រុមប្រឹក្សាភិបាល BCE បានធ្វើទំនើបកម្មប្រតិបត្តិការនៅឆ្នាំ 2015 ដោយនាំយកបច្ចេកវិទ្យាលាយបេតុងដោយប្រព័ន្ធកុំព្យូទ័រ មកជំនួសម៉ាស៊ីនលាយបេតុងដោយដៃ។","បច្ចុប្បន្ន BCE ដំណើរការរោងចក្រលាយបេតុងកណ្តាល 4 រោង រថយន្តលាយបេតុង 41 គ្រឿង រថយន្តបូមបេតុង 8 គ្រឿង ម៉ាស៊ីនបោះសសរស្ដម្ភធារាសាស្ត្រ 7 គ្រឿង និងមន្ទីរពិសោធន៍សាកល្បងវត្ថុធាតុផ្ទៃក្នុង ដែលផ្តល់សេវានៅ 13 ខេត្ត និងរាជធានីភ្នំពេញ។"]},{"heading":"កេរ្តិ៍ដំណែលនៃទំនុកចិត្ត និងសុចរិតភាព","body":["រយៈពេលជាងបីទសវត្សរ៍ BCE បានផ្គត់ផ្គង់បេតុង និងសេវាកម្មសំណង់ សម្រាប់គម្រោងលំនៅដ្ឋាន ពាណិជ្ជកម្ម ឧស្សាហកម្ម និងសាធារណៈ ទូទាំងប្រទេសកម្ពុជា។"]}],"takeaways":["បង្កើតឡើងក្នុងឆ្នាំ 1995 ជាមួយបទពិសោធន៍ប្រតិបត្តិការល្អឥតខ្ចោះជាង 30 ឆ្នាំ ដោយគ្មានការរអាក់រអួល។","បានចុះបញ្ជី និងគ្រប់គ្រងក្នុងស្រុកនៅកម្ពុជា។","ប្តេជ្ញាគាំទ្រហេដ្ឋារចនាសម្ព័ន្ធវិស្វកម្មស៊ីវិលជំនាន់ថ្មីរបស់កម្ពុជា។"]},"author":{"name":"ក្រុមកេរ្តិ៍ដំណែលសាជីវកម្ម BCE","role":"ទំនាក់ទំនងសាជីវកម្ម, BCE"},"slug":"30-years-of-bce-heritage-from-1995"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('posts:concrete-slab-laser-screeding-superflat', 'posts', 'concrete-slab-laser-screeding-superflat', 'published', 7, '{"slug":"concrete-slab-laser-screeding-superflat","sample":true,"title":"Concrete Slab Laser Screeding: Delivering Ultra-Flat Superflat Flooring for Modern Warehouses","category":"Civil Construction","kind":"Insight","year":"2024","date":"08 September 2024","readTime":"5 min read","image":"/Image/bce/core-business-slab.webp","alt":"BCE crew placing and finishing a concrete slab","excerpt":"Automated laser screed technology achieves precise floor flatness (FF) and floor levelness (FL) numbers required for high-bay logistics racking and automated forklifts.","content":{"intro":"Modern agricultural packaging centers, rice processing warehouses, and logistics hubs require ultra-flat concrete floors (FF > 45, FL > 35) to allow high-reach narrow-aisle forklifts to operate without mast tipping. BCE combines customized low-shrinkage ready-mix designs with automated laser screed finishing services.","sections":[{"heading":"Laser-Guided Elevation Accuracy","body":["Laser screeding uses continuous elevation signals from rotating laser transmitters set up on site, with automatic hydraulic adjustment of the screed to strike off concrete to a consistent level across the pour.","Combined with steel fiber reinforcement or synthetic macro-fibers, the resulting industrial floor slabs eliminate saw-cut curling and provide decades of dust-free operational resilience."]},{"heading":"Ride-On Power Trowel Polishing","body":["Following laser screeding, dual-rotor ride-on power trowels perform pan floating and finish burnishing to consolidate the top 5mm wear layer, creating an impermeable, mirror-smooth concrete surface suitable for high-traffic industrial traffic."]}],"takeaways":["Delivers high FF/FL numbers required for automated warehousing.","Speeds up placement across large floor areas when the method is specified.","Reduces construction joints and long-term floor maintenance costs."]},"author":{"name":"Eng. Sokhom Seng","role":"Lead Materials & Batching Engineer, BCE"}}', '{"title":"ការកោរកម្រាលបេតុងដោយឡាស៊ែរ៖ ការផ្តល់កម្រាលរាបស្មើពិសេស (Superflat) សម្រាប់ឃ្លាំងទំនើប","kind":"Insight","alt":"ក្រុមការងារ BCE កំពុងចាក់ និងតុបតែងកម្រាលបេតុង","excerpt":"បច្ចេកវិទ្យាកោរកម្រាលដោយឡាស៊ែរស្វ័យប្រវត្តិ សម្រេចបាននូវតម្លៃភាពរាបស្មើនៃកម្រាល (FF) និងភាពនឹងរាបនៃកម្រាល (FL) យ៉ាងជាក់លាក់ ដែលចាំបាច់សម្រាប់ធ្នើរខ្ពស់ក្នុងឃ្លាំងភស្តុភារ និងរថយន្តលើកទំនិញស្វ័យប្រវត្តិ។","content":{"intro":"មជ្ឈមណ្ឌលវេចខ្ចប់កសិផលទំនើប ឃ្លាំងកែច្នៃអង្ករ និងមជ្ឈមណ្ឌលភស្តុភារ តម្រូវឱ្យមានកម្រាលបេតុងរាបស្មើពិសេស (FF > 45, FL > 35) ដើម្បីឱ្យរថយន្តលើកទំនិញប្រភេទច្រកចង្អៀតខ្ពស់ អាចធ្វើការបានដោយមិនឱ្យបង្គោលលើកផ្អៀង។ BCE រួមបញ្ចូលរូបមន្តបេតុងលាយស្រេចដែលបានកែសម្រួលឱ្យមានការរួមតូចទាប ជាមួយសេវាកម្មតុបតែងកម្រាលដោយឡាស៊ែរស្វ័យប្រវត្តិ។","sections":[{"heading":"ភាពជាក់លាក់នៃកម្រិតខ្ពស់ដី ដឹកនាំដោយឡាស៊ែរ","body":["ការកោរកម្រាលដោយឡាស៊ែរ ប្រើសញ្ញាកម្រិតខ្ពស់ជាបន្តបន្ទាប់ ពីឧបករណ៍បញ្ចេញឡាស៊ែរបង្វិល ដែលដំឡើងនៅការដ្ឋាន ជាមួយការកែតម្រូវធារាសាស្ត្រដោយស្វ័យប្រវត្តិនៃឧបករណ៍កោរ ដើម្បីកោរបេតុងឱ្យមានកម្រិតស្មើគ្នាពេញការចាក់។","នៅពេលផ្សំជាមួយដែកគោលជាតិសរសៃដែក ឬសរសៃម៉ាក្រូសំយោគ កម្រាលបេតុងឧស្សាហកម្មដែលទទួលបាន លុបបំបាត់ការរមួលប្រេះតាមស្នាមកាត់ និងផ្តល់ភាពធន់ក្នុងប្រតិបត្តិការដោយគ្មានធូលី អស់ជាច្រើនទសវត្សរ៍។"]},{"heading":"ការខាត់រលោងដោយម៉ាស៊ីនតុបតែងកម្រាលបេតុងបើកបរ","body":["បន្ទាប់ពីការកោរកម្រាលដោយឡាស៊ែរ ម៉ាស៊ីនតុបតែងកម្រាលបេតុងបើកបរប្រភេទរ៉ូទ័រពីរ ធ្វើការហាលផ្ទៃដោយបន្ទះសំប៉ែត និងបញ្ចប់ដោយការខាត់រលោង ដើម្បីបង្រួមស្រទាប់ពាក់ខាងលើកម្រាស់ 5mm បង្កើតជាផ្ទៃបេតុងរលោងដូចកញ្ចក់ និងមិនជ្រាបទឹក ដែលសមស្របសម្រាប់ចរាចរណ៍ឧស្សាហកម្មកម្រិតខ្ពស់។"]}],"takeaways":["ផ្តល់តម្លៃ FF/FL ខ្ពស់ ដែលចាំបាច់សម្រាប់ឃ្លាំងស្វ័យប្រវត្តិ។","បង្កើនល្បឿនការចាក់បេតុងលើផ្ទៃធំទូលាយ នៅពេលវិធីនេះត្រូវបានកំណត់ក្នុងលក្ខណៈបច្ចេកទេស។","កាត់បន្ថយសន្លាក់សំណង់ និងថ្លៃថែទាំកម្រាលរយៈពេលវែង។"]},"author":{"name":"វិស្វករ សុខុម សេង","role":"ប្រធានវិស្វករវត្ថុធាតុ និងការលាយបេតុង, BCE"},"slug":"concrete-slab-laser-screeding-superflat"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('vacancies:sales-quotations-engineer', 'vacancies', 'sales-quotations-engineer', 'published', 0, '{"id":"sales-quotations-engineer","title":"Sales & Quotations Engineer","department":"Sales & Quotations","location":"Battambang Head Office","type":"Full-Time","deadline":"31 December 2026","overview":"Prepare clear, accurate quotations for ready-mix concrete, piling, construction, slab works and equipment hire. Work with our batching, piling and dispatch teams to price enquiries from drawings, BOQs and site requirements, then follow each request through to order.","duties":["Review enquiries, drawings and BOQs and prepare quotations for the five BCE services.","Coordinate with batching, piling and dispatch teams to confirm capacity, delivery windows and pump or rig requirements.","Visit sites in Battambang and nearby provinces to confirm access, scope and pour requirements.","Follow up quotations, answer technical questions and hand confirmed orders to the operations team.","Keep the enquiry and quotation records complete so nothing is lost between sales and delivery."],"qualifications":["Bachelor''s degree in Civil Engineering, Construction Management or a related field, or equivalent construction sales experience.","1–3 years in construction sales, estimating or quotations, preferably with ready-mix concrete or piling.","Able to read construction drawings and prepare a clear quantity take-off; AutoCAD is an advantage.","Fluent Khmer and good English, with confident written and spoken communication.","A valid driving licence and willingness to travel to project sites."]}', '{"title":"វិស្វករផ្នែកលក់ និងសម្រង់តម្លៃ","overview":"រៀបចំសម្រង់តម្លៃឱ្យបានច្បាស់លាស់ និងត្រឹមត្រូវសម្រាប់បេតុងលាយស្រេច ការបោះសសរស្ដម្ភ ការងារសំណង់ ការងារចាក់កម្រាលបេតុង និងការជួលគ្រឿងចក្រ។ សហការជាមួយក្រុមរោងចក្រលាយបេតុង ក្រុមបោះសសរស្ដម្ភ និងក្រុមបញ្ជូន ដើម្បីកំណត់តម្លៃតាមសំណើ ដោយផ្អែកលើគំនូរ បញ្ជីបរិមាណការងារ (BOQ) និងតម្រូវការនៅការដ្ឋាន បន្ទាប់មកតាមដានសំណើនីមួយៗរហូតដល់ការបញ្ជាទិញ។","duties":["ពិនិត្យសំណើ គំនូរ និងបញ្ជីបរិមាណការងារ (BOQ) រួចរៀបចំសម្រង់តម្លៃសម្រាប់សេវាកម្មទាំងប្រាំរបស់ BCE។","សម្របសម្រួលជាមួយក្រុមរោងចក្រលាយបេតុង ក្រុមបោះសសរស្ដម្ភ និងក្រុមបញ្ជូន ដើម្បីបញ្ជាក់សមត្ថភាព កាលវេលាដឹកជញ្ជូន និងតម្រូវការរថយន្តបូមបេតុង ឬម៉ាស៊ីនបោះសសរស្ដម្ភ។","ចុះពិនិត្យការដ្ឋាននៅបាត់ដំបង និងខេត្តជិតខាង ដើម្បីបញ្ជាក់ផ្លូវចូល វិសាលភាពការងារ និងតម្រូវការចាក់បេតុង។","តាមដានសម្រង់តម្លៃ ឆ្លើយសំណួរបច្ចេកទេស និងបញ្ជូនការបញ្ជាទិញដែលបានបញ្ជាក់រួច ទៅក្រុមប្រតិបត្តិការ។","រក្សាកំណត់ត្រាសំណើ និងសម្រង់តម្លៃឱ្យបានពេញលេញ ដើម្បីកុំឱ្យមានការបាត់បង់ព័ត៌មានរវាងផ្នែកលក់ និងការដឹកជញ្ជូន។"],"qualifications":["បរិញ្ញាបត្រផ្នែកវិស្វកម្មសំណង់ស៊ីវិល ការគ្រប់គ្រងសំណង់ ឬជំនាញពាក់ព័ន្ធ ឬបទពិសោធន៍លក់ក្នុងវិស័យសំណង់ស្មើនឹងកម្រិតនេះ។","បទពិសោធន៍ 1–3 ឆ្នាំ ក្នុងការលក់ផ្នែកសំណង់ ការប៉ាន់តម្លៃ ឬសម្រង់តម្លៃ ល្អបំផុតប្រសិនបើធ្លាប់ធ្វើការលើបេតុងលាយស្រេច ឬការបោះសសរស្ដម្ភ។","អាចអានគំនូរសំណង់ និងរៀបចំបញ្ជីបរិមាណការងារបានច្បាស់លាស់; ចេះប្រើ AutoCAD គឺជាការបន្ថែមពិន្ទុ។","ខ្មែរស្ទាត់ជំនាញ និងអង់គ្លេសកម្រិតល្អ មានទំនុកចិត្តក្នុងការប្រាស្រ័យទាក់ទងទាំងការសរសេរ និងការនិយាយ។","មានប័ណ្ណបើកបរត្រឹមត្រូវ និងមានឆន្ទៈធ្វើដំណើរទៅការដ្ឋានគម្រោងនានា។"],"id":"sales-quotations-engineer"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('vacancies:batching-plant-operator', 'vacancies', 'batching-plant-operator', 'published', 1, '{"id":"batching-plant-operator","title":"Concrete Batching Plant Operator","department":"Operations & Batching","location":"Battambang Central Plant","type":"Full-Time","deadline":"31 March 2026","overview":"Operate computerized concrete batching plants, oversee automated material weighing according to certified mix designs, and coordinate with mixer truck logistics for continuous large-scale pours.","duties":["Operate PLC computerized batching control panels to produce ready-mix concrete per approved ACI 211.1 mix designs.","Monitor aggregate bins, cement silos, water measurement, and admixture dosing systems for operational precision.","Collaborate with quality control lab technicians to verify slump, moisture content, and temperature before truck departure.","Perform daily pre-operational calibration, plant cleaning, and preventative maintenance logs.","Maintain safe batching operations in accordance with BCE Health, Safety, and Environment (HSE) standards."],"qualifications":["Vocational diploma or Bachelor''s degree in Electrical, Mechanical, or Civil Engineering.","1+ years experience operating computerized concrete batching plants (Sicoma, Simem, or similar).","Familiarity with concrete raw materials, chemical admixtures, and moisture adjustment calculations.","Strong attention to detail, punctuality, and commitment to workplace safety."]}', '{"title":"ប្រតិបត្តិកររោងចក្រលាយបេតុង","overview":"ប្រតិបត្តិការរោងចក្រលាយបេតុងប្រព័ន្ធកុំព្យូទ័រ ត្រួតពិនិត្យការថ្លឹងវត្ថុធាតុដើមដោយស្វ័យប្រវត្តិតាមរូបមន្តលាយបេតុងដែលបានបញ្ជាក់ និងសម្របសម្រួលជាមួយការដឹកជញ្ជូនរថយន្តលាយបេតុង សម្រាប់ការចាក់បេតុងទ្រង់ទ្រាយធំជាបន្តបន្ទាប់។","duties":["ប្រតិបត្តិការផ្ទាំងបញ្ជារោងចក្រលាយបេតុងប្រព័ន្ធ PLC ដើម្បីផលិតបេតុងលាយស្រេចតាមរូបមន្តលាយបេតុង ACI 211.1 ដែលបានអនុម័ត។","ត្រួតពិនិត្យធុងថ្ម ស៊ីឡូស៊ីម៉ងត៍ ការវាស់ទឹក និងប្រព័ន្ធចាក់សារធាតុបន្ថែម ដើម្បីធានាភាពត្រឹមត្រូវនៃប្រតិបត្តិការ។","សហការជាមួយអ្នកបច្ចេកទេសមន្ទីរពិសោធន៍ត្រួតពិនិត្យគុណភាព ដើម្បីផ្ទៀងផ្ទាត់កម្រិតស្រុត សំណើម និងសីតុណ្ហភាព មុនពេលរថយន្តចេញពីរោងចក្រ។","អនុវត្តការក្រិតតម្រូវមុនប្រតិបត្តិការជារៀងរាល់ថ្ងៃ ការសម្អាតរោងចក្រ និងការកត់ត្រាការថែទាំបង្ការ។","រក្សាប្រតិបត្តិការលាយបេតុងដោយសុវត្ថិភាព ស្របតាមស្តង់ដារសុខភាព សុវត្ថិភាព និងបរិស្ថាន (HSE) របស់ BCE។"],"qualifications":["សញ្ញាបត្រវិជ្ជាជីវៈ ឬបរិញ្ញាបត្រ ផ្នែកវិស្វកម្មអគ្គិសនី វិស្វកម្មមេកានិច ឬវិស្វកម្មសំណង់ស៊ីវិល។","បទពិសោធន៍ 1 ឆ្នាំឡើងទៅ ក្នុងការប្រតិបត្តិការរោងចក្រលាយបេតុងប្រព័ន្ធកុំព្យូទ័រ (Sicoma, Simem ឬម៉ាកស្រដៀងគ្នា)។","ស្គាល់វត្ថុធាតុដើមបេតុង សារធាតុបន្ថែមគីមី និងការគណនាកែតម្រូវសំណើម។","យកចិត្តទុកដាក់ខ្ពស់លើព័ត៌មានលម្អិត មកធ្វើការទាន់ពេលវេលា និងប្តេជ្ញាចិត្តខ្ពស់ចំពោះសុវត្ថិភាពកន្លែងធ្វើការ។"],"id":"batching-plant-operator"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('vacancies:qa-materials-engineer', 'vacancies', 'qa-materials-engineer', 'published', 2, '{"id":"qa-materials-engineer","title":"Quality Assurance / Materials Testing Engineer","department":"Quality & Lab","location":"BCE In-House Laboratory, Battambang","type":"Full-Time","deadline":"31 March 2026","overview":"Perform physical testing of concrete aggregates, fresh concrete slump inspections, test cylinder casting, and DYE-2000 compressive strength evaluations in BCE''s accredited in-house testing facility.","duties":["Conduct daily quality control sampling and testing of aggregates, cement, and water per ASTM and ACI standards.","Perform on-site slump tests, temperature checks, and casting of standard 150mm concrete test cylinders.","Operate the DYE-2000 digital compressive testing machine to evaluate 7-day and 28-day breaking strength.","Maintain formal laboratory test logs, calibration certifications, and generate client quality compliance reports.","Review supplier mill test certificates for cement, reinforcement rebar, and chemical admixtures."],"qualifications":["Bachelor''s degree in Civil Engineering, Materials Science, or Quality Engineering.","Knowledge of ACI 211.1, ASTM C39, and Cambodian construction material standards.","Experience working in a construction materials testing laboratory or ready-mix QA department.","Proficiency in technical reporting, data logging, and quality compliance documentation."]}', '{"title":"វិស្វករធានាគុណភាព / ពិសោធន៍វត្ថុធាតុ","overview":"ធ្វើការពិសោធន៍រូបវន្តលើថ្មបេតុង ការត្រួតពិនិត្យកម្រិតស្រុតបេតុងស្រស់ ការចាក់គំរូស៊ីឡាំងសាកល្បង និងការវាយតម្លៃកម្លាំងសង្កត់ដោយម៉ាស៊ីន DYE-2000 នៅក្នុងមន្ទីរពិសោធន៍ផ្ទាល់ខ្លួនរបស់ BCE ដែលបានទទួលការទទួលស្គាល់។","duties":["ធ្វើការយកគំរូ និងពិសោធន៍ត្រួតពិនិត្យគុណភាពប្រចាំថ្ងៃលើថ្ម ស៊ីម៉ងត៍ និងទឹក តាមស្តង់ដារ ASTM និង ACI។","ធ្វើតេស្តកម្រិតស្រុតនៅការដ្ឋាន ការវាស់សីតុណ្ហភាព និងការចាក់គំរូស៊ីឡាំងសាកល្បងបេតុងស្តង់ដារ 150mm។","ប្រតិបត្តិការម៉ាស៊ីនវាយតម្លៃកម្លាំងសង្កត់ឌីជីថល DYE-2000 ដើម្បីវាយតម្លៃកម្លាំងបែកនៅអាយុ 7 ថ្ងៃ និង 28 ថ្ងៃ។","រក្សាកំណត់ត្រាពិសោធន៍ផ្លូវការរបស់មន្ទីរពិសោធន៍ វិញ្ញាបនបត្រក្រិតតម្រូវ និងរៀបចំរបាយការណ៍អនុលោមភាពគុណភាពជូនអតិថិជន។","ពិនិត្យវិញ្ញាបនបត្រពិសោធន៍របស់រោងចក្រអ្នកផ្គត់ផ្គង់ សម្រាប់ស៊ីម៉ងត៍ ដែកគោល និងសារធាតុបន្ថែមគីមី។"],"qualifications":["បរិញ្ញាបត្រផ្នែកវិស្វកម្មសំណង់ស៊ីវិល វិទ្យាសាស្ត្រវត្ថុធាតុ ឬវិស្វកម្មគុណភាព។","មានចំណេះដឹងលើ ACI 211.1, ASTM C39 និងស្តង់ដារវត្ថុធាតុសំណង់របស់កម្ពុជា។","មានបទពិសោធន៍ធ្វើការក្នុងមន្ទីរពិសោធន៍វត្ថុធាតុសំណង់ ឬផ្នែកធានាគុណភាពនៃរោងចក្របេតុងលាយស្រេច។","មានជំនាញក្នុងការរៀបចំរបាយការណ៍បច្ចេកទេស ការកត់ត្រាទិន្នន័យ និងឯកសារអនុលោមភាពគុណភាព។"],"id":"qa-materials-engineer"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('vacancies:piling-rig-operator', 'vacancies', 'piling-rig-operator', 'published', 3, '{"id":"piling-rig-operator","title":"Hydraulic Piling Rig Operator & Field Technician","department":"Piling & Foundation","location":"Site Deployments across Cambodia","type":"Full-Time","deadline":"15 April 2026","overview":"Operate hydraulic static pile driving rigs and boring machinery on civil and industrial foundation projects across Cambodia with strict adherence to site safety blueprints.","duties":["Operate hydraulic pile driving rigs for precast reinforced concrete piles and deep foundation bored piling.","Ensure precise pile alignment, verticality inspection, and penetration resistance monitoring.","Conduct daily equipment inspection, hydraulic pressure checks, lubrication, and safety maintenance.","Coordinate with site engineers and survey teams to execute foundation layouts per engineering blueprints.","Comply with site safety protocols including full PPE and exclusion zone management during rig operation."],"qualifications":["Certified heavy machinery / hydraulic rig operator license.","3+ years experience operating hydraulic pile driving equipment or bored piling rigs in Cambodia.","Strong understanding of soil resistance, pile driving safety, and site hazard prevention.","Willingness to deploy to provincial project sites with full company accommodation and per diem."]}', '{"title":"ប្រតិបត្តិករម៉ាស៊ីនបោះសសរស្ដម្ភធារាសាស្ត្រ និងអ្នកបច្ចេកទេសការដ្ឋាន","overview":"ប្រតិបត្តិការម៉ាស៊ីនបោះសសរស្ដម្ភធារាសាស្ត្របែបស្ថិតស្ថេរ និងគ្រឿងចក្រខួរដី នៅក្នុងគម្រោងគ្រឹះសំណង់ស៊ីវិល និងឧស្សាហកម្មទូទាំងប្រទេសកម្ពុជា ដោយប្រកាន់ខ្ជាប់យ៉ាងតឹងរ៉ឹងនូវផែនការសុវត្ថិភាពនៅការដ្ឋាន។","duties":["ប្រតិបត្តិការម៉ាស៊ីនបោះសសរស្ដម្ភធារាសាស្ត្រ សម្រាប់សសរស្ដម្ភបេតុងពង្រឹងដែកដែលផលិតរួច និងការខួរបោះសសរស្ដម្ភគ្រឹះជ្រៅ។","ធានាភាពត្រឹមត្រូវនៃការតម្រឹមសសរស្ដម្ភ ការត្រួតពិនិត្យភាពឈរត្រង់ និងការត្រួតពិនិត្យកម្លាំងទប់ទល់នៃការចុះជ្រៅ។","ពិនិត្យឧបករណ៍ប្រចាំថ្ងៃ ត្រួតពិនិត្យសម្ពាធធារាសាស្ត្រ ការចាក់ប្រេងរំអិល និងការថែទាំផ្នែកសុវត្ថិភាព។","សម្របសម្រួលជាមួយវិស្វករការដ្ឋាន និងក្រុមវាស់ស្ទង់ ដើម្បីអនុវត្តប្លង់គ្រឹះតាមគំនូរវិស្វកម្ម។","គោរពតាមនីតិវិធីសុវត្ថិភាពនៅការដ្ឋាន រួមទាំងការពាក់ឧបករណ៍ការពារខ្លួន (PPE) ពេញលេញ និងការគ្រប់គ្រងតំបន់ហាមឃាត់ អំឡុងពេលប្រតិបត្តិការម៉ាស៊ីន។"],"qualifications":["មានអាជ្ញាបណ្ណបើកបរគ្រឿងចក្រធុនធ្ងន់ / ម៉ាស៊ីនធារាសាស្ត្រ ដែលមានការបញ្ជាក់ត្រឹមត្រូវ។","បទពិសោធន៍ 3 ឆ្នាំឡើងទៅ ក្នុងការប្រតិបត្តិការឧបករណ៍បោះសសរស្ដម្ភធារាសាស្ត្រ ឬម៉ាស៊ីនខួរបោះសសរស្ដម្ភ នៅកម្ពុជា។","យល់ដឹងច្បាស់ពីកម្លាំងទប់ទល់របស់ដី សុវត្ថិភាពក្នុងការបោះសសរស្ដម្ភ និងការការពារគ្រោះថ្នាក់នៅការដ្ឋាន។","មានឆន្ទៈចុះទៅការដ្ឋានគម្រោងនៅតាមខេត្ត ដោយក្រុមហ៊ុនផ្តល់កន្លែងស្នាក់នៅ និងប្រាក់ឧបត្ថម្ភប្រចាំថ្ងៃពេញលេញ។"],"id":"piling-rig-operator"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('vacancies:heavy-fleet-mechanic', 'vacancies', 'heavy-fleet-mechanic', 'published', 4, '{"id":"heavy-fleet-mechanic","title":"Heavy Fleet Maintenance Technician","department":"Fleet Logistics","location":"Battambang Central Workshop","type":"Full-Time","deadline":"15 April 2026","overview":"Maintain and service BCE''s fleet of 41 mixer trucks and 8 concrete boom and line pumps to ensure peak operational reliability, rapid turnaround, and zero breakdown during active pours.","duties":["Perform preventative maintenance, oil changes, brake inspections, and tire servicing across heavy truck fleet.","Diagnose and repair hydraulic motors, pump gearboxes, rotating drum systems, and pneumatic valves.","Support emergency site repairs during active concrete pours when necessary.","Maintain spare parts inventory logs, workshop safety compliance, and fleet maintenance records.","Ensure all trucks and pumping equipment meet strict road safety standards before site dispatch."],"qualifications":["Technical certificate or diploma in Heavy Vehicle Mechanics, Diesel Technology, or Hydraulic Systems.","2+ years experience servicing commercial diesel trucks (Hino, Isuzu, Howo, or similar heavy chassis).","Hands-on expertise with hydraulic pump systems, high-pressure hoses, and power take-off (PTO) units.","Hardworking, disciplined, and capable of working in shifts during major pour schedules."]}', '{"title":"អ្នកបច្ចេកទេសថែទាំក្រុមរថយន្តធុនធ្ងន់","overview":"ថែទាំ និងជួសជុលក្រុមរថយន្តរបស់ BCE ដែលមានរថយន្តលាយបេតុង 41 គ្រឿង និងរថយន្តបូមបេតុងប្រភេទដងយោង (boom) និងប្រភេទបំពង់ (line) 8 គ្រឿង ដើម្បីធានាភាពជឿជាក់ខ្ពស់បំផុតក្នុងប្រតិបត្តិការ ការត្រៀមរថយន្តបានរហ័ស និងការមិនមានការខូចម៉ាស៊ីន អំឡុងពេលចាក់បេតុង។","duties":["អនុវត្តការថែទាំបង្ការ ការប្តូរប្រេងម៉ាស៊ីន ការត្រួតពិនិត្យហ្វ្រាំង និងការថែទាំសំបកកង់ លើរថយន្តធុនធ្ងន់ទាំងអស់។","ធ្វើរោគវិនិច្ឆ័យ និងជួសជុលម៉ូទ័រធារាសាស្ត្រ ប្រអប់លេខរថយន្តបូម ប្រព័ន្ធធុងលាយវិល និងសន្ទះខ្យល់។","គាំទ្រការជួសជុលបន្ទាន់នៅការដ្ឋាន អំឡុងពេលចាក់បេតុង នៅពេលចាំបាច់។","រក្សាកំណត់ត្រាស្តុកគ្រឿងបន្លាស់ ការគោរពសុវត្ថិភាពក្នុងសិក្ខាសាលា និងកំណត់ត្រាថែទាំយានយន្ត។","ធានាថារថយន្ត និងឧបករណ៍បូមទាំងអស់ បំពេញតាមស្តង់ដារសុវត្ថិភាពចរាចរណ៍យ៉ាងតឹងរ៉ឹង មុនពេលបញ្ជូនចេញទៅការដ្ឋាន។"],"qualifications":["សញ្ញាបត្របច្ចេកទេស ឬសញ្ញាបត្រវិជ្ជាជីវៈ ផ្នែកមេកានិចយានយន្តធុនធ្ងន់ បច្ចេកវិទ្យាម៉ាស៊ីនម៉ាស៊ូត ឬប្រព័ន្ធធារាសាស្ត្រ។","បទពិសោធន៍ 2 ឆ្នាំឡើងទៅ ក្នុងការថែទាំរថយន្តម៉ាស៊ូតពាណិជ្ជកម្ម (Hino, Isuzu, Howo ឬតួរថយន្តធុនធ្ងន់ស្រដៀងគ្នា)។","មានជំនាញជាក់ស្តែងលើប្រព័ន្ធបូមធារាសាស្ត្រ ទុយោសម្ពាធខ្ពស់ និងគ្រឿងបញ្ជូនកម្លាំង (PTO)។","ឧស្សាហ៍ព្យាយាម មានវិន័យ និងអាចធ្វើការជាវេន អំឡុងពេលមានការចាក់បេតុងធំៗ។"],"id":"heavy-fleet-mechanic"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('vacancies:site-civil-engineer', 'vacancies', 'site-civil-engineer', 'published', 5, '{"id":"site-civil-engineer","title":"Site Civil Engineer — Ready-Mix & Foundation Works","department":"Civil Construction","location":"Site Deployments across Cambodia","type":"Full-Time","deadline":"30 April 2026","overview":"Supervise continuous concrete pour execution, foundation piling works, and structural civil projects. Ensure compliance with engineering drawings, client specifications, and HSE protocols.","duties":["Oversee on-site concrete casting, vibration, level finishing, and initial curing for structural foundations and industrial slabs.","Inspect reinforcing steel placement, formwork stability, and pile head preparation prior to concrete pour approval.","Coordinate with batching plant dispatch to maintain smooth truck delivery intervals and avoid cold joints.","Conduct daily site toolbox talks and enforce occupational safety standards across all subcontractors and field crews.","Prepare daily site progress reports, concrete volume reconciliation, and quality documentation."],"qualifications":["Bachelor''s degree in Civil Engineering, Structural Engineering, or Building Technology.","2+ years experience in structural construction, ready-mix concrete pouring, or foundation piling in Cambodia.","Proficiency in AutoCAD, construction blueprint reading, and structural bar bending schedules.","Strong leadership, problem-solving, and bilingual communication skills (Khmer / English)."]}', '{"title":"វិស្វករសំណង់ស៊ីវិលការដ្ឋាន — បេតុងលាយស្រេច និងការងារគ្រឹះ","overview":"ត្រួតពិនិត្យការអនុវត្តការចាក់បេតុងជាបន្តបន្ទាប់ ការងារបោះសសរស្ដម្ភគ្រឹះ និងគម្រោងសំណង់ស៊ីវិលផ្នែករចនាសម្ព័ន្ធ។ ធានាការអនុលោមតាមគំនូរវិស្វកម្ម លក្ខណៈបច្ចេកទេសរបស់អតិថិជន និងនីតិវិធី HSE។","duties":["ត្រួតពិនិត្យការចាក់បេតុងនៅការដ្ឋាន ការញ័របេតុង ការតម្រឹមកម្រិតផ្ទៃ និងការថែរក្សាបេតុងដំបូង សម្រាប់គ្រឹះរចនាសម្ព័ន្ធ និងកម្រាលបេតុងឧស្សាហកម្ម។","ពិនិត្យការដំឡើងដែកគោល ស្ថិរភាពទម្រង់ពូក និងការរៀបចំក្បាលសសរស្ដម្ភ មុនពេលអនុម័តការចាក់បេតុង។","សម្របសម្រួលជាមួយការបញ្ជូនរបស់រោងចក្រលាយបេតុង ដើម្បីរក្សាចន្លោះពេលដឹកជញ្ជូនរថយន្តឱ្យរលូន និងជៀសវាងការកើតសន្លាក់ត្រជាក់។","រៀបចំការប្រជុំសុវត្ថិភាពខ្លីៗប្រចាំថ្ងៃនៅការដ្ឋាន និងអនុវត្តស្តង់ដារសុវត្ថិភាពការងារ ចំពោះអ្នកម៉ៅការបន្ត និងក្រុមការងារវាលទាំងអស់។","រៀបចំរបាយការណ៍វឌ្ឍនភាពការដ្ឋានប្រចាំថ្ងៃ ការផ្ទៀងផ្ទាត់បរិមាណបេតុង និងឯកសារគុណភាព។"],"qualifications":["បរិញ្ញាបត្រផ្នែកវិស្វកម្មសំណង់ស៊ីវិល វិស្វកម្មរចនាសម្ព័ន្ធ ឬបច្ចេកវិទ្យាអគារ។","បទពិសោធន៍ 2 ឆ្នាំឡើងទៅ ក្នុងការសាងសង់រចនាសម្ព័ន្ធ ការចាក់បេតុងលាយស្រេច ឬការបោះសសរស្ដម្ភគ្រឹះ នៅកម្ពុជា។","មានជំនាញ AutoCAD ការអានគំនូរសំណង់ និងបញ្ជីកាត់ពត់ដែករចនាសម្ព័ន្ធ។","មានជំនាញដឹកនាំខ្លាំង ការដោះស្រាយបញ្ហា និងការប្រាស្រ័យទាក់ទងពីរភាសា (ខ្មែរ / អង់គ្លេស)។"],"id":"site-civil-engineer"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('resources:bce-corporate-profile', 'resources', 'bce-corporate-profile', 'published', 0, '{"id":"bce-corporate-profile","title":"BCE Corporate Profile 2026","category":"profile","categoryLabel":"Company Profile","description":"BCE''s official 55-page corporate profile: Chairwoman''s message, company statistics, milestones, core business areas, fleet, operational coverage, laboratory and quality control, HSE, project experience, clients and partners, and the licence and certificate annex.","fileFormat":"PDF","fileSize":"8.4 MB","language":"English","revisionDate":"2026 edition","year":"2026","downloadUrl":"/assets/BCE_Corporate_Profile_2026_web.pdf"}', '{"title":"ប្រវត្តិរូបក្រុមហ៊ុន BCE ឆ្នាំ ២០២៦","categoryLabel":"ប្រវត្តិរូបក្រុមហ៊ុន","description":"ប្រវត្តិរូបក្រុមហ៊ុនផ្លូវការរបស់ BCE ចំនួន ៥៥ ទំព័រ៖ សាររបស់ប្រធានក្រុមហ៊ុន ស្ថិតិក្រុមហ៊ុន ចំណុចសំខាន់ៗ អាជីវកម្មស្នូល កងគ្រឿងចក្រ តំបន់ប្រតិបត្តិការ មន្ទីរពិសោធន៍ និងការត្រួតពិនិត្យគុណភាព សុខភាព សុវត្ថិភាព និងបរិស្ថាន (HSE) បទពិសោធន៍គម្រោង អតិថិជន និងដៃគូ ព្រមទាំងឧបសម្ព័ន្ធអាជ្ញាប័ណ្ណ និងវិញ្ញាបនបត្រ។","id":"bce-corporate-profile"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
