INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('resources:concrete-mix-specs', 'resources', 'concrete-mix-specs', 'published', 1, '{"id":"concrete-mix-specs","title":"Approved concrete mix designs","category":"technical","categoryLabel":"Brochures & Technical Documents","description":"The approved mix designs behind the concrete grades BCE supplies, from C15 to C40, including the design for a specific project. Copies are supplied with the quotation or on request.","fileFormat":"PDF","fileSize":"","language":"English","revisionDate":"Available on request","year":"2026","downloadUrl":"","onRequest":true}', '{"title":"រូបមន្តលាយបេតុងដែលបានអនុម័ត","categoryLabel":"កម្រងព័ត៌មាន & ឯកសារបច្ចេកទេស","description":"រូបមន្តលាយដែលបានអនុម័តសម្រាប់កម្រិតបេតុងដែល BCE ផ្គត់ផ្គង់ ចាប់ពី C15 ដល់ C40 រួមទាំងរូបមន្តសម្រាប់គម្រោងជាក់លាក់មួយ។ ច្បាប់ចម្លងត្រូវបានផ្ដល់ជូនជាមួយសម្រង់តម្លៃ ឬតាមការស្នើសុំ។","onRequest":true,"id":"concrete-mix-specs"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
