INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('resources:piling-rigs-catalog', 'resources', 'piling-rigs-catalog', 'published', 2, '{"id":"piling-rigs-catalog","title":"Piling rig capability sheet","category":"technical","categoryLabel":"Brochures & Technical Documents","description":"The pile sizes, installation methods and site requirements for BCE''s own piling rigs. Issued on request for tender and method-statement reviews.","fileFormat":"PDF","fileSize":"","language":"English","revisionDate":"Available on request","year":"2026","downloadUrl":"","onRequest":true}', '{"title":"ឯកសារសមត្ថភាពម៉ាស៊ីនបោះសសរស្ដម្ភ","categoryLabel":"កម្រងព័ត៌មាន & ឯកសារបច្ចេកទេស","description":"ទំហំសសរស្ដម្ភ វិធីសាស្ត្រដំឡើង និងតម្រូវការការដ្ឋានសម្រាប់ម៉ាស៊ីនបោះសសរស្ដម្ភផ្ទាល់ខ្លួនរបស់ BCE។ ចេញជូនតាមការស្នើសុំ សម្រាប់ការពិនិត្យការដេញថ្លៃ និងឯកសារវិធីសាស្ត្រការងារ។","onRequest":true,"id":"piling-rigs-catalog"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
