INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('resources:concrete-pump-reach', 'resources', 'concrete-pump-reach', 'published', 3, '{"id":"concrete-pump-reach","title":"Concrete pump deployment information","category":"technical","categoryLabel":"Brochures & Technical Documents","description":"Boom and line pump reach, site footprint and pipeline requirements for the pump trucks in BCE''s fleet. Issued on request to help plan a pour.","fileFormat":"PDF","fileSize":"","language":"English","revisionDate":"Available on request","year":"2026","downloadUrl":"","onRequest":true}', '{"title":"ព័ត៌មានការដាក់ពង្រាយរថយន្តបូមបេតុង","categoryLabel":"កម្រងព័ត៌មាន & ឯកសារបច្ចេកទេស","description":"ចម្ងាយ និងកម្ពស់ដែលដៃបូម និងបូមតាមបំពង់អាចទៅដល់ ផ្ទៃក្រឡាការដ្ឋាន និងតម្រូវការបំពង់សម្រាប់រថយន្តបូមបេតុងក្នុងកងរថយន្តរបស់ BCE។ ចេញជូនតាមការស្នើសុំ ដើម្បីជួយរៀបចំផែនការចាក់បេតុង។","onRequest":true,"id":"concrete-pump-reach"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
