INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('resources:aggregate-sieve-analysis', 'resources', 'aggregate-sieve-analysis', 'published', 4, '{"id":"aggregate-sieve-analysis","title":"Aggregate and material test reports","category":"technical","categoryLabel":"Brochures & Technical Documents","description":"Sieve analysis and material test reports for the fine and coarse aggregates used in BCE concrete, produced by the in-house laboratory. Available on request.","fileFormat":"PDF","fileSize":"","language":"English","revisionDate":"Available on request","year":"2026","downloadUrl":"","onRequest":true}', '{"title":"របាយការណ៍តេស្តថ្ម ខ្សាច់ និងវត្ថុធាតុដើម","categoryLabel":"កម្រងព័ត៌មាន & ឯកសារបច្ចេកទេស","description":"របាយការណ៍រែងវិភាគទំហំគ្រាប់ និងតេស្តវត្ថុធាតុសម្រាប់ខ្សាច់ម៉ត់ និងថ្មគ្រួសដែលប្រើក្នុងបេតុងរបស់ BCE រៀបចំដោយមន្ទីរពិសោធន៍ផ្ទាល់ខ្លួន។ មានជូនតាមការស្នើសុំ។","onRequest":true,"id":"aggregate-sieve-analysis"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
