INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('resources:ministry-registration', 'resources', 'ministry-registration', 'published', 5, '{"id":"ministry-registration","title":"Business registration & contractor classification","category":"licenses","categoryLabel":"Licenses & Certifications","description":"Business registration, tax registration and construction contractor classification documents. Copies are released to tender and procurement teams on request.","fileFormat":"PDF","fileSize":"","language":"Khmer","revisionDate":"2020 incorporation","year":"2020","downloadUrl":"","onRequest":true}', '{"title":"ការចុះបញ្ជីអាជីវកម្ម & ការចាត់ថ្នាក់អ្នកម៉ៅការ","categoryLabel":"អាជ្ញាប័ណ្ណ & វិញ្ញាបនបត្រ","description":"ឯកសារចុះបញ្ជីអាជីវកម្ម ចុះបញ្ជីពន្ធដារ និងការចាត់ថ្នាក់អ្នកម៉ៅការសំណង់។ ច្បាប់ចម្លងត្រូវបានផ្ដល់ជូនក្រុមដេញថ្លៃ និងក្រុមលទ្ធកម្ម តាមការស្នើសុំ។","onRequest":true,"id":"ministry-registration"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
