INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('resources:laboratory-calibration', 'resources', 'laboratory-calibration', 'published', 6, '{"id":"laboratory-calibration","title":"Laboratory & equipment calibration certificates","category":"licenses","categoryLabel":"Licenses & Certifications","description":"Calibration certificates for the batching scales, compression testing machine and laboratory equipment used in production and quality control. Copies are available on request.","fileFormat":"PDF","fileSize":"","language":"English / Khmer","revisionDate":"Available on request","year":"2026","downloadUrl":"","onRequest":true}', '{"title":"វិញ្ញាបនបត្រក្រិតខ្នាតមន្ទីរពិសោធន៍ & ឧបករណ៍","categoryLabel":"អាជ្ញាប័ណ្ណ & វិញ្ញាបនបត្រ","description":"វិញ្ញាបនបត្រក្រិតខ្នាតសម្រាប់ជញ្ជីងថ្លឹងវត្ថុធាតុ ម៉ាស៊ីនតេស្តកម្លាំងសង្កត់ និងឧបករណ៍មន្ទីរពិសោធន៍ដែលប្រើក្នុងផលិតកម្ម និងការត្រួតពិនិត្យគុណភាព។ ច្បាប់ចម្លងមានជូនតាមការស្នើសុំ។","onRequest":true,"id":"laboratory-calibration"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
