INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('resources:hse-policy', 'resources', 'hse-policy', 'published', 7, '{"id":"hse-policy","title":"Health, Safety & Environment (HSE) policy","category":"licenses","categoryLabel":"Licenses & Certifications","description":"BCE''s health, safety and environment policy, covering PPE, site inspections, safe pumping procedures and environmental responsibilities. Copies are available on request.","fileFormat":"PDF","fileSize":"","language":"English / Khmer","revisionDate":"Available on request","year":"2026","downloadUrl":"","onRequest":true}', '{"title":"គោលការណ៍សុខភាព សុវត្ថិភាព និងបរិស្ថាន (HSE)","categoryLabel":"អាជ្ញាប័ណ្ណ & វិញ្ញាបនបត្រ","description":"គោលការណ៍សុខភាព សុវត្ថិភាព និងបរិស្ថានរបស់ BCE ដែលគ្របដណ្តប់លើឧបករណ៍ការពារខ្លួន (PPE) ការត្រួតពិនិត្យការដ្ឋាន នីតិវិធីបូមបេតុងប្រកបដោយសុវត្ថិភាព និងការទទួលខុសត្រូវផ្នែកបរិស្ថាន។ ច្បាប់ចម្លងមានជូនតាមការស្នើសុំ។","onRequest":true,"id":"hse-policy"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('businesses:ready-mix-concrete', 'businesses', 'ready-mix-concrete', 'published', 0, '{"slug":"ready-mix-concrete","name":"Ready-Mix Concrete","tagline":"Supply and logistics","heroImage":"/Image/bce/photos/concrete-discharge.webp","heroAlt":"BCE mixer truck discharging ready-mix concrete on site","intro":"Quality-controlled concrete from our four batching plants, each producing 70 m³ an hour, delivered to site by our own fleet of 41 mixer trucks across 13 provinces and Phnom Penh.","valuesKicker":"Why BCE for ready-mix","valuesTitle":"A supply chain you can plan around","values":[{"title":"Own plants, own trucks","icon":"plant","text":"Four batching plants and 41 mixer trucks, all ours, so production and delivery are planned around your programme rather than a supplier''s."},{"title":"Designed and tested in-house","icon":"lab","text":"Every grade is trial-mixed and approved before supply, then slump-tested on delivery and sampled for strength in our own laboratory."},{"title":"Every batch recorded","icon":"record","text":"Batch weights, delivery tickets and test results are documented for each pour and handed over with the works."},{"title":"Dispatch that keeps up","icon":"truck","text":"Site pouring runs 24/7 on schedule, with deliveries sequenced to the placing crew''s programme and the pour sequence."}],"solutionsKicker":"Our solutions","solutionsTitle":"Concrete for every pour","solutionsLead":"From foundations and frames to floors and hardstands, concrete is batched to the approved mix design and delivered when the site is ready.","solutions":[{"title":"Structural concrete, C15–C40","text":"Foundations, columns, beams and slabs, batched to the approved mix design and delivered to the pour sequence.","image":"/Image/bce/photos/bridge-pump.webp","alt":"BCE pump boom placing structural concrete into formwork"},{"title":"Continuous and mass pours","text":"Raft foundations, warehouse floors and large slabs, planned across plants and trucks so the pour runs without interruption.","image":"/Image/bce/photos/mixer-pour.webp","alt":"A continuous concrete pour across a large slab, with mixer trucks and a pump on site"},{"title":"Pumped delivery","text":"Our eight pump trucks place concrete where mixer chutes cannot reach, including upper floors and restricted sites.","image":"/Image/bce/photos/boom-pump.webp","alt":"BCE boom pump truck placing concrete on site"}],"capacityKicker":"Capacity and fleet","capacityTitle":"Production and delivery in one fleet","capacityCopy":"Concrete is produced at four batching plants and delivered by our own mixers, so capacity, quality and timing stay under one roof and one programme.","figures":[{"value":"04","label":"Batching plants"},{"value":"70 m³","label":"Per hour, each plant"},{"value":"41","label":"Mixer trucks"},{"value":"13+","label":"Provinces and Phnom Penh"}],"prepare":["Site location and access — where the trucks will discharge, and any height, gate or road limits.","Volume per pour and the concrete grade (C15–C40), or the drawings and BOQ if you have them.","Pour dates and sequence, including any night or weekend pours.","Whether you need a pump truck, and the distance from the pump position to the pour."],"projects":["siem-reap-commercial-ready-mix"]}', '{"name":"បេតុងលាយស្រេច","tagline":"ការផ្គត់ផ្គង់ និងភស្តុភារ","heroAlt":"រថយន្តលាយបេតុងរបស់ BCE កំពុងបញ្ចេញបេតុងលាយស្រេចនៅការដ្ឋាន","intro":"បេតុងដែលគ្រប់គ្រងគុណភាពយ៉ាងតឹងរ៉ឹង ចេញពីរោងចក្រលាយបេតុងទាំងបួនរបស់យើង ដែលម្នាក់ៗផលិតបាន 70 m³ ក្នុងមួយម៉ោង ហើយដឹកជញ្ជូនទៅការដ្ឋានដោយក្រុមរថយន្តលាយបេតុងចំនួន 41 គ្រឿងរបស់យើងផ្ទាល់ ឆ្លងកាត់ 13 ខេត្ត និងរាជធានីភ្នំពេញ។","valuesKicker":"ហេតុអ្វីជ្រើសរើស BCE សម្រាប់បេតុងលាយស្រេច","valuesTitle":"ខ្សែសង្វាក់ផ្គត់ផ្គង់ដែលអ្នកអាចរៀបចំផែនការបានយ៉ាងទុកចិត្ត","values":[{"title":"រោងចក្រ និងរថយន្តរបស់យើងផ្ទាល់","text":"រោងចក្រលាយបេតុងចំនួនបួន និងរថយន្តលាយបេតុងចំនួន 41 គ្រឿង សុទ្ធតែជាកម្មសិទ្ធិរបស់យើង ដូច្នេះការផលិត និងការដឹកជញ្ជូនត្រូវបានរៀបចំផែនការតាមកាលវិភាគរបស់អ្នក មិនមែនតាមអ្នកផ្គត់ផ្គង់ទេ។"},{"title":"រចនា និងធ្វើតេស្តដោយខ្លួនឯង","text":"រាល់ថ្នាក់បេតុងត្រូវបានលាយសាកល្បង និងអនុម័តមុនការផ្គត់ផ្គង់ បន្ទាប់មកធ្វើតេស្តកម្រិតស្រុតពេលដឹកជញ្ជូន និងយកគំរូធ្វើតេស្តកម្លាំងសង្កត់នៅមន្ទីរពិសោធន៍របស់យើងផ្ទាល់។"},{"title":"កត់ត្រារាល់បាច់លាយ","text":"ទម្ងន់បាច់លាយ វិក័យប័ត្រដឹកជញ្ជូន និងលទ្ធផលតេស្ត ត្រូវបានកត់ត្រាសម្រាប់ការចាក់បេតុងនីមួយៗ និងប្រគល់ជូនជាមួយការងារ។"},{"title":"ការបញ្ជូនដែលទាន់កាលវិភាគ","text":"ការចាក់បេតុងនៅការដ្ឋានដំណើរការ 24/7 តាមកាលវិភាគ ដោយការដឹកជញ្ជូនត្រូវបានរៀបចំតាមកាលវិភាគរបស់ក្រុមចាក់បេតុង និងលំដាប់នៃការចាក់។"}],"solutionsKicker":"ដំណោះស្រាយរបស់យើង","solutionsTitle":"បេតុងសម្រាប់រាល់ការចាក់","solutionsLead":"ចាប់ពីគ្រឹះ និងគ្រោងរចនាសម្ព័ន្ធ រហូតដល់កម្រាល និងផ្ទៃខាងក្រៅ បេតុងត្រូវបានលាយតាមរូបមន្តដែលបានអនុម័ត និងដឹកជញ្ជូននៅពេលការដ្ឋានរួចរាល់។","solutions":[{"title":"បេតុងរចនាសម្ព័ន្ធ C15–C40","text":"គ្រឹះ សសរ ធ្នឹម និងកម្រាល លាយតាមរូបមន្តដែលបានអនុម័ត និងដឹកជញ្ជូនតាមលំដាប់នៃការចាក់។","alt":"ដងដៃបូមរបស់ BCE កំពុងចាក់បេតុងរចនាសម្ព័ន្ធចូលទៅក្នុងទម្រង់ពូក"},{"title":"ការចាក់បេតុងបន្ត និងការចាក់បរិមាណច្រើន","text":"គ្រឹះរាបស្មើ កម្រាលឃ្លាំង និងកម្រាលបេតុងធំៗ ត្រូវបានរៀបចំផែនការឆ្លងកាត់រោងចក្រ និងរថយន្ត ដើម្បីឱ្យការចាក់ដំណើរការដោយមិនដាច់។","alt":"ការចាក់បេតុងបន្តលើកម្រាលធំ ជាមួយរថយន្តលាយបេតុង និងរថយន្តបូមនៅការដ្ឋាន"},{"title":"ការដឹកជញ្ជូនដោយបូម","text":"រថយន្តបូមបេតុងចំនួនប្រាំបីគ្រឿងរបស់យើង ដាក់បេតុងទៅកន្លែងដែលរន្ធបញ្ចេញរបស់រថយន្តលាយបេតុងមិនអាចទៅដល់ រួមទាំងជាន់ខាងលើ និងការដ្ឋានចង្អៀត។","alt":"រថយន្តបូមបេតុងដងដៃរបស់ BCE កំពុងចាក់បេតុងនៅការដ្ឋាន"}],"capacityKicker":"សមត្ថភាព និងក្រុមយានយន្ត","capacityTitle":"ការផលិត និងការដឹកជញ្ជូនក្នុងក្រុមយានយន្តតែមួយ","capacityCopy":"បេតុងត្រូវបានផលិតនៅរោងចក្រលាយបេតុងចំនួនបួន និងដឹកជញ្ជូនដោយរថយន្តលាយបេតុងរបស់យើងផ្ទាល់ ដូច្នេះសមត្ថភាព គុណភាព និងពេលវេលា ស្ថិតនៅក្រោមការគ្រប់គ្រងតែមួយ និងកាលវិភាគតែមួយ។","figures":[{"value":"04","label":"រោងចក្រលាយបេតុង"},{"value":"70 m³","label":"ក្នុងមួយម៉ោង ក្នុងមួយរោងចក្រ"},{"value":"41","label":"រថយន្តលាយបេតុង"},{"value":"13+","label":"ខេត្ត និងរាជធានីភ្នំពេញ"}],"prepare":["ទីតាំងការដ្ឋាន និងផ្លូវចូល — កន្លែងដែលរថយន្តនឹងបញ្ចេញបេតុង និងដែនកំណត់កម្ពស់ ច្រកចូល ឬផ្លូវ។","បរិមាណក្នុងមួយការចាក់ និងថ្នាក់បេតុង (C15–C40) ឬគំនូរ និង BOQ ប្រសិនបើអ្នកមាន។","កាលបរិច្ឆេទ និងលំដាប់នៃការចាក់ រួមទាំងការចាក់ពេលយប់ ឬថ្ងៃចុងសប្តាហ៍។","តើអ្នកត្រូវការរថយន្តបូមបេតុងឬអត់ និងចម្ងាយពីទីតាំងរថយន្តបូមទៅកន្លែងចាក់។"],"slug":"ready-mix-concrete"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
