INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('businesses:piling', 'businesses', 'piling', 'published', 1, '{"slug":"piling","name":"Piling","tagline":"Foundations","heroImage":"/Image/bce/photos/pile-reinforcement.webp","heroAlt":"Reinforcement and concrete placement for a BCE foundation","intro":"Reinforced concrete piles for bridges, roads and buildings, installed with our own rigs and crews and backed by concrete and laboratory quality control from the same team.","valuesKicker":"Why BCE for piling","valuesTitle":"Foundations built on control","values":[{"title":"Our own rigs and crews","icon":"rig","text":"We mobilise our own piling rigs and installation crews, so the programme is set by our capacity, not a subcontractor''s."},{"title":"Engineered from the drawings","icon":"blueprint","text":"Our engineers plan the piling sequence, reinforcement and concrete supply around the structural design, then supervise installation on site."},{"title":"Concrete from our plants","icon":"plant","text":"Piles are cast with concrete from our own batching plants, tested for slump and strength before it reaches the rig."},{"title":"Records with every pile","icon":"record","text":"Installation records, concrete results and test reports are compiled and handed over with the foundation."}],"solutionsKicker":"Our solutions","solutionsTitle":"Piling solutions","solutionsLead":"We install foundations for almost any structure, combining proven methods with concrete, rigs and testing from our own resources.","solutions":[{"title":"Bored cast-in-place piles","text":"Piles bored and cast on site with our own concrete, suited to deep foundations and high load capacity.","image":"/Image/bce/photos/piling-rig.webp","alt":"BCE bored piling rig and casing on a foundation site"},{"title":"Pressed and driven RC piles","text":"Hydraulic static pressing and driven reinforced concrete piles for foundations where vibration and spoil must stay controlled.","image":"/Image/bce/photos/pile-reinforcement.webp","alt":"Reinforcement cage and concrete placement for an RC pile"},{"title":"Bridge and infrastructure foundations","text":"Pile caps, abutments and culverts for roads and bridges, from mobilisation through load testing and as-built records.","image":"/Image/bce/photos/bridge-pump.webp","alt":"Concrete pumping for a bridge pier and its foundation"}],"capacityKicker":"Rigs and capability","capacityTitle":"Rigs, crews and records","capacityCopy":"Piling crews work with our own rigs, concrete and laboratory, so foundations are planned, installed and verified by one team.","figures":[{"value":"07","label":"Hydraulic piling rigs"},{"value":"15","label":"Engineers in our team"},{"value":"C35–C40","label":"Pile concrete from our plants"},{"value":"13+","label":"Provinces and Phnom Penh"}],"prepare":["Pile type, diameter and depth, and the number of piles.","Ground information or the soil report, if one is available.","Site access and the working platform the rig will stand on.","Programme: start date and the sequence of pile groups."],"projects":["kampong-thom-bridge-foundations","phnom-penh-tower-foundations"]}', '{"name":"ការបោះសសរស្ដម្ភ","tagline":"គ្រឹះ","heroAlt":"ការដាក់ដែកគោល និងចាក់បេតុងសម្រាប់គ្រឹះរបស់ BCE","intro":"សសរស្ដម្ភបេតុងពង្រឹងដែកសម្រាប់ស្ពាន ផ្លូវ និងអគារ ដំឡើងដោយម៉ាស៊ីន និងក្រុមកម្មកររបស់យើងផ្ទាល់ ព្រមទាំងមានការត្រួតពិនិត្យគុណភាពបេតុង និងមន្ទីរពិសោធន៍ពីក្រុមតែមួយ។","valuesKicker":"ហេតុអ្វីជ្រើសរើស BCE សម្រាប់ការបោះសសរស្ដម្ភ","valuesTitle":"គ្រឹះដែលកសាងលើការគ្រប់គ្រង","values":[{"title":"ម៉ាស៊ីន និងក្រុមកម្មកររបស់យើងផ្ទាល់","text":"យើងដាក់ពង្រាយម៉ាស៊ីនបោះសសរស្ដម្ភ និងក្រុមដំឡើងរបស់យើងផ្ទាល់ ដូច្នេះកាលវិភាគត្រូវបានកំណត់ដោយសមត្ថភាពរបស់យើង មិនមែនដោយអ្នកម៉ៅការបន្តរងទេ។"},{"title":"រចនាវិស្វកម្មតាមគំនូរ","text":"វិស្វកររបស់យើងរៀបចំផែនការលំដាប់នៃការបោះសសរស្ដម្ភ ដែកគោល និងការផ្គត់ផ្គង់បេតុង ស្របតាមការរចនារចនាសម្ព័ន្ធ បន្ទាប់មកត្រួតពិនិត្យការដំឡើងនៅការដ្ឋាន។"},{"title":"បេតុងពីរោងចក្ររបស់យើង","text":"សសរស្ដម្ភត្រូវបានចាក់ដោយបេតុងពីរោងចក្រលាយបេតុងរបស់យើងផ្ទាល់ ដែលបានធ្វើតេស្តកម្រិតស្រុត និងកម្លាំងសង្កត់ មុនពេលដល់ម៉ាស៊ីន។"},{"title":"កំណត់ត្រាជាមួយរាល់សសរស្ដម្ភ","text":"កំណត់ត្រាការដំឡើង លទ្ធផលបេតុង និងរបាយការណ៍តេស្ត ត្រូវបានចងក្រង និងប្រគល់ជូនជាមួយគ្រឹះ។"}],"solutionsKicker":"ដំណោះស្រាយរបស់យើង","solutionsTitle":"ដំណោះស្រាយការបោះសសរស្ដម្ភ","solutionsLead":"យើងដំឡើងគ្រឹះសម្រាប់សំណង់ស្ទើរតែគ្រប់ប្រភេទ ដោយរួមបញ្ចូលវិធីសាស្ត្រដែលបានបញ្ជាក់ ជាមួយបេតុង ម៉ាស៊ីន និងការធ្វើតេស្តពីធនធានរបស់យើងផ្ទាល់។","solutions":[{"title":"សសរស្ដម្ភខួងចាក់នៅនឹងកន្លែង","text":"សសរស្ដម្ភដែលខួង និងចាក់នៅការដ្ឋានដោយបេតុងរបស់យើងផ្ទាល់ សមស្របសម្រាប់គ្រឹះជ្រៅ និងផ្ទុកបន្ទុកខ្ពស់។","alt":"ម៉ាស៊ីនបោះសសរស្ដម្ភខួង និងបំពង់ស្រោមរបស់ BCE នៅការដ្ឋានគ្រឹះ"},{"title":"សសរស្ដម្ភ RC ចុចដោយធារាសាស្ត្រ និងវាយចុះ","text":"ការចុចដោយធារាសាស្ត្រស្តាទិច និងការវាយសសរស្ដម្ភបេតុងពង្រឹងដែក សម្រាប់គ្រឹះដែលត្រូវគ្រប់គ្រងការញ័រ និងការបាត់បង់ដី។","alt":"ទ្រុងដែកគោល និងការចាក់បេតុងសម្រាប់សសរស្ដម្ភ RC"},{"title":"គ្រឹះស្ពាន និងហេដ្ឋារចនាសម្ព័ន្ធ","text":"ក្បាលសសរស្ដម្ភ ជើងទម្រស្ពាន និងលូសម្រាប់ផ្លូវ និងស្ពាន ចាប់ពីការដាក់ពង្រាយ រហូតដល់ការធ្វើតេស្តបន្ទុក និងកំណត់ត្រាស្ថានភាពជាក់ស្តែង។","alt":"ការបូមបេតុងសម្រាប់សសរស្ពាន និងគ្រឹះរបស់វា"}],"capacityKicker":"ម៉ាស៊ីន និងសមត្ថភាព","capacityTitle":"ម៉ាស៊ីន ក្រុមកម្មករ និងកំណត់ត្រា","capacityCopy":"ក្រុមបោះសសរស្ដម្ភធ្វើការជាមួយម៉ាស៊ីន បេតុង និងមន្ទីរពិសោធន៍របស់យើងផ្ទាល់ ដូច្នេះគ្រឹះត្រូវបានរៀបចំផែនការ ដំឡើង និងផ្ទៀងផ្ទាត់ដោយក្រុមតែមួយ។","figures":[{"value":"07","label":"ម៉ាស៊ីនបោះសសរស្ដម្ភធារាសាស្ត្រ"},{"value":"15","label":"វិស្វករក្នុងក្រុមរបស់យើង"},{"value":"C35–C40","label":"បេតុងសសរស្ដម្ភពីរោងចក្ររបស់យើង"},{"value":"13+","label":"ខេត្ត និងរាជធានីភ្នំពេញ"}],"prepare":["ប្រភេទសសរស្ដម្ភ អង្កត់ផ្ចិត និងជម្រៅ ព្រមទាំងចំនួនសសរស្ដម្ភ។","ព័ត៌មានដី ឬរបាយការណ៍ស្ថានភាពដី ប្រសិនបើមាន។","ផ្លូវចូលការដ្ឋាន និងវេទិកាធ្វើការដែលម៉ាស៊ីននឹងឈរ។","កាលវិភាគ៖ កាលបរិច្ឆេទចាប់ផ្តើម និងលំដាប់នៃក្រុមសសរស្ដម្ភ។"],"slug":"piling"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('businesses:construction', 'businesses', 'construction', 'published', 2, '{"slug":"construction","name":"Construction","tagline":"Civil construction","heroImage":"/Image/bce/photos/road-crew.webp","heroAlt":"BCE construction crew placing concrete on a road project","intro":"Civil construction for infrastructure, industrial, commercial and residential projects, built with our own concrete, equipment and engineers from the first earthworks to handover.","valuesKicker":"Why BCE for construction","valuesTitle":"One team from ground to handover","values":[{"title":"One point of responsibility","icon":"shield","text":"Concrete, foundations and construction come from one team, so interfaces between trades do not become delays."},{"title":"Own materials and fleet","icon":"truck","text":"Our plants, mixer and pump trucks and piling rigs are assigned from our own fleet, keeping programme and cost under control."},{"title":"Engineers on site","icon":"helmet","text":"A team of 15 engineers plans, supervises and records the work from setting out to handover."},{"title":"Built for the wet season","icon":"rain","text":"Programmes are sequenced around Cambodia''s rainy season, with drainage and earthworks planned before the first rains."}],"solutionsKicker":"Our solutions","solutionsTitle":"Construction services","solutionsLead":"We deliver the works that carry a project from prepared ground to a completed structure, using resources we own and maintain.","solutions":[{"title":"Roads and infrastructure","text":"National and provincial roads, bridges, culverts and drainage, delivered with our own earthworks, concrete and paving crews.","image":"/Image/bce/photos/concrete-discharge.webp","alt":"BCE crew placing concrete for a provincial road base"},{"title":"Industrial and logistics","text":"Factories, warehouses and depots, from site preparation and foundations to structural frames and floors.","image":"/Image/bce/photos/boom-pump.webp","alt":"Concrete pumping at an industrial plant and storage facility"},{"title":"Commercial and residential","text":"Commercial buildings and residential developments, built with our own concrete, equipment and engineers.","image":"/Image/bce/photos/building-frame.webp","alt":"Completed multi-storey building delivered by BCE"}],"capacityKicker":"Team and capacity","capacityTitle":"Built with our own resources","capacityCopy":"From the first earthworks to the final handover, our construction teams draw on the same plants, fleet and engineers that supply our concrete and foundations.","figures":[{"value":"1995","label":"Building in Cambodia since"},{"value":"71","label":"People in our team"},{"value":"15","label":"Engineers on staff"},{"value":"13+","label":"Provinces and Phnom Penh"}],"prepare":["Scope of works with the drawings and BOQ you have.","Site location, access, and any phasing or occupied-area constraints.","Programme and the required completion date.","Approvals already in place, and the consultant or engineer of record."],"projects":["battambang-provincial-road"]}', '{"name":"សំណង់ស៊ីវិល","tagline":"ការសាងសង់ស៊ីវិល","heroAlt":"ក្រុមកម្មករសំណង់របស់ BCE កំពុងចាក់បេតុងលើគម្រោងផ្លូវ","intro":"សំណង់ស៊ីវិលសម្រាប់គម្រោងហេដ្ឋារចនាសម្ព័ន្ធ ឧស្សាហកម្ម ពាណិជ្ជកម្ម និងលំនៅដ្ឋាន កសាងដោយបេតុង គ្រឿងចក្រ និងវិស្វកររបស់យើងផ្ទាល់ ចាប់ពីការងារដីដំបូងរហូតដល់ការប្រគល់ជូន។","valuesKicker":"ហេតុអ្វីជ្រើសរើស BCE សម្រាប់ការសាងសង់","valuesTitle":"ក្រុមតែមួយពីការងារដីដល់ការប្រគល់ជូន","values":[{"title":"ចំណុចទទួលខុសត្រូវតែមួយ","text":"បេតុង គ្រឹះ និងការសាងសង់ មកពីក្រុមតែមួយ ដូច្នេះចំណុចប្រសព្វរវាងការងារនីមួយៗ មិនក្លាយជាការយឺតយ៉ាវទេ។"},{"title":"វត្ថុធាតុ និងក្រុមយានយន្តរបស់យើងផ្ទាល់","text":"រោងចក្រ រថយន្តលាយបេតុង រថយន្តបូមបេតុង និងម៉ាស៊ីនបោះសសរស្ដម្ភរបស់យើង ត្រូវបានកំណត់ពីក្រុមយានយន្តរបស់យើងផ្ទាល់ ដែលរក្សាកាលវិភាគ និងថ្លៃដើមឱ្យស្ថិតក្រោមការគ្រប់គ្រង។"},{"title":"វិស្វករនៅការដ្ឋាន","text":"ក្រុមវិស្វករចំនួន 15 នាក់ រៀបចំផែនការ ត្រួតពិនិត្យ និងកត់ត្រាការងារ ចាប់ពីការកំណត់ទីតាំងរហូតដល់ការប្រគល់ជូន។"},{"title":"កសាងសម្រាប់រដូវវស្សា","text":"កាលវិភាគត្រូវបានរៀបចំតាមរដូវវស្សារបស់កម្ពុជា ដោយការងារបង្ហូរទឹក និងការងារដី ត្រូវបានរៀបចំផែនការមុនពេលភ្លៀងដំបូង។"}],"solutionsKicker":"ដំណោះស្រាយរបស់យើង","solutionsTitle":"សេវាកម្មសំណង់","solutionsLead":"យើងអនុវត្តការងារដែលនាំគម្រោងពីដីដែលបានរៀបចំ ទៅជាសំណង់ដែលបានបញ្ចប់ ដោយប្រើធនធានដែលយើងជាម្ចាស់ និងថែទាំ។","solutions":[{"title":"ផ្លូវ និងហេដ្ឋារចនាសម្ព័ន្ធ","text":"ផ្លូវជាតិ និងផ្លូវខេត្ត ស្ពាន លូ និងប្រព័ន្ធបង្ហូរទឹក អនុវត្តដោយក្រុមការងារដី ក្រុមចាក់បេតុង និងក្រុមចាក់ផ្ទៃផ្លូវរបស់យើងផ្ទាល់។","alt":"ក្រុមកម្មកររបស់ BCE កំពុងចាក់បេតុងសម្រាប់ស្រទាប់មូលដ្ឋានផ្លូវខេត្ត"},{"title":"ឧស្សាហកម្ម និងភស្តុភារ","text":"រោងចក្រ ឃ្លាំង និងស្ថានីយដឹកជញ្ជូន ចាប់ពីការរៀបចំទីតាំង និងគ្រឹះ រហូតដល់គ្រោងរចនាសម្ព័ន្ធ និងកម្រាល។","alt":"ការបូមបេតុងនៅរោងចក្រឧស្សាហកម្ម និងឃ្លាំងស្តុកទំនិញ"},{"title":"ពាណិជ្ជកម្ម និងលំនៅដ្ឋាន","text":"អគារពាណិជ្ជកម្ម និងគម្រោងលំនៅដ្ឋាន កសាងដោយបេតុង គ្រឿងចក្រ និងវិស្វកររបស់យើងផ្ទាល់។","alt":"អគារពហុជាន់ដែលបានបញ្ចប់ និងប្រគល់ជូនដោយ BCE"}],"capacityKicker":"ក្រុមការងារ និងសមត្ថភាព","capacityTitle":"កសាងដោយធនធានរបស់យើងផ្ទាល់","capacityCopy":"ចាប់ពីការងារដីដំបូងរហូតដល់ការប្រគល់ជូនចុងក្រោយ ក្រុមសំណង់របស់យើងប្រើប្រាស់រោងចក្រ ក្រុមយានយន្ត និងវិស្វករដូចគ្នា ដែលផ្គត់ផ្គង់បេតុង និងគ្រឹះរបស់យើង។","figures":[{"value":"1995","label":"កសាងសង់នៅកម្ពុជាតាំងពី"},{"value":"71","label":"សមាជិកក្រុមរបស់យើង"},{"value":"15","label":"វិស្វករប្រចាំការ"},{"value":"13+","label":"ខេត្ត និងរាជធានីភ្នំពេញ"}],"prepare":["វិសាលភាពការងារ ជាមួយគំនូរ និង BOQ ដែលអ្នកមាន។","ទីតាំងការដ្ឋាន ផ្លូវចូល និងដែនកំណត់ដំណាក់កាល ឬតំបន់ដែលកំពុងប្រើប្រាស់។","កាលវិភាគ និងកាលបរិច្ឆេទបញ្ចប់ដែលបានកំណត់។","ការអនុញ្ញាតដែលមានរួចហើយ និងអ្នកប្រឹក្សា ឬវិស្វករទទួលបន្ទុក។"],"slug":"construction"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
