INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('businesses:concrete-slab-works', 'businesses', 'concrete-slab-works', 'published', 3, '{"slug":"concrete-slab-works","name":"Concrete Slab Works","tagline":"Placement and finishing","heroImage":"/video/hero_concrete_poster.webp","heroAlt":"Concrete placement and finishing by the BCE slab crew","intro":"Placement and finishing of concrete slabs, pumped by our eight pump trucks with ready-mix from our own plants and tested for slump and strength on every pour.","valuesKicker":"Why BCE for slab works","valuesTitle":"Placed, finished and checked","values":[{"title":"Pumped by our own fleet","icon":"truck","text":"Eight pump trucks place concrete across the slab, keeping pours steady and reducing manual handling on site."},{"title":"Finishing that lasts","icon":"layers","text":"Power-float finishes, dry-shake hardeners and saw-cut joints are matched to how the floor will be used."},{"title":"Tested concrete, every delivery","icon":"lab","text":"Slump is checked on arrival and cubes are crushed at 7 and 28 days, with results recorded for each pour."},{"title":"Pours planned in bays","icon":"grid","text":"Large floors are divided into pour bays and sequenced with our batching plants so each day''s work closes cleanly."}],"solutionsKicker":"Our solutions","solutionsTitle":"Slab solutions","solutionsLead":"Slab crews work with ready-mix from our plants and pumps from our fleet, so placement, finishing and testing are coordinated on one programme.","solutions":[{"title":"Ground-bearing floors","text":"Warehouse, factory and depot floors, placed in planned bays and power-floated for racking and forklift traffic.","image":"/Image/bce/photos/mixer-pour.webp","alt":"Ground-bearing floor slab placed with mixer trucks and a pump"},{"title":"Suspended slabs","text":"Structural slabs for upper floors, pumped by our own fleet and finished to the engineer''s specification.","image":"/Image/bce/photos/slab-pour.webp","alt":"Reinforced concrete placed into suspended slab formwork"},{"title":"Yards and hardstands","text":"External slabs, yards and hardstands, detailed for drainage, joints and the loads they will carry.","image":"/Image/bce/photos/road-crew.webp","alt":"External concrete slab placed and power-floated"}],"capacityKicker":"Pumps and plants","capacityTitle":"Pumps, plants and crews","capacityCopy":"Our slab crews place and finish with ready-mix from our batching plants and pumps from our own fleet, tested as it arrives.","figures":[{"value":"08","label":"Concrete pump trucks"},{"value":"41","label":"Mixer trucks"},{"value":"70 m³","label":"Per hour, each plant"},{"value":"C25–C35","label":"Slab concrete from our plants"}],"prepare":["Slab area, thickness and the specified finish (power float, laser screed or brushed).","Joint layout or drawings, and the pour sequence.","Access for the pump and mixers, plus water and power on site.","Required flatness or tolerance, and the handover date."],"projects":["poipet-logistics-warehouse"]}', '{"name":"ការងារចាក់កម្រាលបេតុង","tagline":"ការចាក់ និងការបញ្ចប់ផ្ទៃ","heroAlt":"ការចាក់ និងការបញ្ចប់ផ្ទៃបេតុងដោយក្រុមកម្រាលបេតុងរបស់ BCE","intro":"ការចាក់ និងការបញ្ចប់ផ្ទៃកម្រាលបេតុង ដោយបូមពីរថយន្តបូមបេតុងចំនួនប្រាំបីគ្រឿងរបស់យើង ជាមួយបេតុងលាយស្រេចពីរោងចក្ររបស់យើងផ្ទាល់ និងធ្វើតេស្តកម្រិតស្រុត និងកម្លាំងសង្កត់លើរាល់ការចាក់។","valuesKicker":"ហេតុអ្វីជ្រើសរើស BCE សម្រាប់ការងារកម្រាលបេតុង","valuesTitle":"ចាក់ បញ្ចប់ផ្ទៃ និងត្រួតពិនិត្យ","values":[{"title":"បូមដោយក្រុមយានយន្តរបស់យើងផ្ទាល់","text":"រថយន្តបូមបេតុងចំនួនប្រាំបីគ្រឿង ចាក់បេតុងពាសពេញកម្រាល ដោយរក្សាការចាក់ឱ្យមានស្ថិរភាព និងកាត់បន្ថយការលើកដោយដៃនៅការដ្ឋាន។"},{"title":"ការបញ្ចប់ផ្ទៃដែលឋិតថេរ","text":"ការបញ្ចប់ផ្ទៃដោយម៉ាស៊ីន Power-float សារធាតុរឹងបន្ថែមប្រភេទ dry-shake និងសន្លាក់កាត់ដោយម៉ាស៊ីន saw-cut ត្រូវបានជ្រើសរើសស្របតាមការប្រើប្រាស់ជាក់ស្តែងរបស់កម្រាល។"},{"title":"បេតុងធ្វើតេស្ត រាល់ការដឹកជញ្ជូន","text":"កម្រិតស្រុតត្រូវបានពិនិត្យនៅពេលមកដល់ ហើយគូបបេតុងត្រូវបានចុចសាកល្បងនៅថ្ងៃទី 7 និងថ្ងៃទី 28 ដោយកត់ត្រាលទ្ធផលសម្រាប់ការចាក់នីមួយៗ។"},{"title":"ការចាក់រៀបចំជាតំបន់","text":"កម្រាលធំៗត្រូវបានបែងចែកជាតំបន់ចាក់ និងរៀបចំលំដាប់ជាមួយរោងចក្រលាយបេតុងរបស់យើង ដើម្បីឱ្យការងារប្រចាំថ្ងៃបញ្ចប់យ៉ាងស្អាត។"}],"solutionsKicker":"ដំណោះស្រាយរបស់យើង","solutionsTitle":"ដំណោះស្រាយកម្រាលបេតុង","solutionsLead":"ក្រុមកម្រាលបេតុងធ្វើការជាមួយបេតុងលាយស្រេចពីរោងចក្ររបស់យើង និងរថយន្តបូមពីក្រុមយានយន្តរបស់យើង ដូច្នេះការចាក់ ការបញ្ចប់ផ្ទៃ និងការធ្វើតេស្ត ត្រូវបានសម្របសម្រួលលើកាលវិភាគតែមួយ។","solutions":[{"title":"កម្រាលដែលផ្ទុកលើដី","text":"កម្រាលឃ្លាំង រោងចក្រ និងស្ថានីយដឹកជញ្ជូន ចាក់ជាតំបន់ដែលបានរៀបចំ និងបញ្ចប់ផ្ទៃដោយម៉ាស៊ីន Power-float សម្រាប់ធ្នើរ និងរថយន្តលើកទំនិញ។","alt":"កម្រាលបេតុងផ្ទុកលើដី ដែលចាក់ដោយរថយន្តលាយបេតុង និងរថយន្តបូម"},{"title":"កម្រាលបេតុងព្យួរ","text":"កម្រាលបេតុងរចនាសម្ព័ន្ធសម្រាប់ជាន់ខាងលើ បូមដោយក្រុមយានយន្តរបស់យើងផ្ទាល់ និងបញ្ចប់ផ្ទៃតាមលក្ខណៈបច្ចេកទេសរបស់វិស្វករ។","alt":"បេតុងពង្រឹងដែកដែលចាក់ចូលទម្រង់ពូកកម្រាលព្យួរ"},{"title":"ផ្ទៃខាងក្រៅ និងទីលានរឹង","text":"កម្រាលខាងក្រៅ ទីលាន និងផ្ទៃរឹង រៀបចំលម្អិតសម្រាប់ការបង្ហូរទឹក សន្លាក់ និងបន្ទុកដែលត្រូវទ្រាំ។","alt":"កម្រាលបេតុងខាងក្រៅ ដែលចាក់ និងបញ្ចប់ផ្ទៃដោយម៉ាស៊ីន Power-float"}],"capacityKicker":"រថយន្តបូម និងរោងចក្រ","capacityTitle":"រថយន្តបូម រោងចក្រ និងក្រុមកម្មករ","capacityCopy":"ក្រុមកម្រាលបេតុងរបស់យើងចាក់ និងបញ្ចប់ផ្ទៃដោយបេតុងលាយស្រេចពីរោងចក្រលាយបេតុងរបស់យើង និងរថយន្តបូមពីក្រុមយានយន្តរបស់យើងផ្ទាល់ ដោយធ្វើតេស្តនៅពេលមកដល់។","figures":[{"value":"08","label":"រថយន្តបូមបេតុង"},{"value":"41","label":"រថយន្តលាយបេតុង"},{"value":"70 m³","label":"ក្នុងមួយម៉ោង ក្នុងមួយរោងចក្រ"},{"value":"C25–C35","label":"បេតុងកម្រាលពីរោងចក្ររបស់យើង"}],"prepare":["ផ្ទៃក្រឡាកម្រាល កម្រាស់ និងការបញ្ចប់ផ្ទៃដែលបានកំណត់ (Power-float ម៉ាស៊ីនក្រិតឡាស៊ែរ ឬការដុសផ្ទៃ)។","ប្លង់សន្លាក់ ឬគំនូរ និងលំដាប់នៃការចាក់។","ផ្លូវចូលសម្រាប់រថយន្តបូម និងរថយន្តលាយបេតុង ព្រមទាំងទឹក និងអគ្គិសនីនៅការដ្ឋាន។","កម្រិតរាបស្មើ ឬការអនុគ្រោះដែលត្រូវការ និងកាលបរិច្ឆេទប្រគល់ជូន។"],"slug":"concrete-slab-works"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
