INSERT INTO documents (id, type, slug, status, sort, data, km, created_at, updated_at, updated_by)
VALUES ('businesses:equipment-rental', 'businesses', 'equipment-rental', 'published', 4, '{"slug":"equipment-rental","name":"Truck & Equipment Rental","tagline":"Fleet hire","heroImage":"/Image/bce/photos/mixer-pour.webp","heroAlt":"BCE mixer truck and pump placing concrete on site","intro":"Mixer trucks, pump trucks and piling rigs for hire, maintained by our own team and ready to mobilise across Cambodia with the operators who know them best.","valuesKicker":"Why BCE for hire","valuesTitle":"Equipment that arrives ready","values":[{"title":"Maintained in-house","icon":"wrench","text":"Every truck and rig is serviced by our own workshop team, so machines arrive on site ready to work."},{"title":"Operators included","icon":"helmet","text":"Experienced operators and drivers come with the equipment, familiar with the machine and the site."},{"title":"Mobilised across Cambodia","icon":"pin","text":"Equipment is dispatched from Battambang and mobilised to projects in 13 provinces and Phnom Penh."},{"title":"Backed by our plants","icon":"plant","text":"Hire can be combined with ready-mix supply and pumping from the same team, under one schedule."}],"solutionsKicker":"Our solutions","solutionsTitle":"Hire solutions","solutionsLead":"Our rental fleet is the same equipment we use on our own works, maintained to the same standard and available with its operators.","solutions":[{"title":"Mixer truck hire","text":"41 mixer trucks on daily call-off or project terms, with drivers and GPS dispatch from our plants.","image":"/Image/bce/photos/concrete-discharge.webp","alt":"BCE mixer truck discharging concrete on site"},{"title":"Pump truck hire","text":"Eight concrete pump trucks with experienced operators for high-reach and restricted-access pours.","image":"/Image/bce/photos/boom-pump.webp","alt":"BCE boom pump truck mobilised for a pour"},{"title":"Piling rig hire","text":"Piling rigs and crews available for foundation works, backed by our own maintenance team.","image":"/Image/bce/photos/piling-rig.webp","alt":"BCE piling rig and crew on a foundation site"}],"capacityKicker":"Fleet and coverage","capacityTitle":"Our fleet, ready to mobilise","capacityCopy":"Mixers, pumps, rigs and lifting plant are all ours, serviced by our own team and dispatched from Battambang, with operators available for every machine. Counts match the fleet on our Equipment & fleet page, not a broker''s availability list.","figures":[{"value":"41","label":"Mixer trucks for hire"},{"value":"08","label":"Pump trucks for hire"},{"value":"07","label":"Piling rigs for hire"},{"value":"13+","label":"Provinces and Phnom Penh"}],"prepare":["Equipment and the hire period, with dates.","Site location and access for mobilisation.","Whether you need an operator, fuel and maintenance included.","The lifting or capacity requirement, and the work the machine will do."],"projects":["sihanoukville-fleet-hire"]}', '{"name":"ការជួលរថយន្ត និងគ្រឿងចក្រ","tagline":"ការជួលក្រុមយានយន្ត","heroAlt":"រថយន្តលាយបេតុង និងរថយន្តបូមបេតុងរបស់ BCE កំពុងចាក់បេតុងនៅការដ្ឋាន","intro":"រថយន្តលាយបេតុង រថយន្តបូមបេតុង និងម៉ាស៊ីនបោះសសរស្ដម្ភ សម្រាប់ជួល ថែទាំដោយក្រុមការងាររបស់យើងផ្ទាល់ និងរួចរាល់ដាក់ពង្រាយពាសពេញកម្ពុជា ជាមួយអ្នកបើកបរ និងអ្នកប្រតិបត្តិការដែលស្គាល់ឧបករណ៍ទាំងនោះច្បាស់ជាងគេ។","valuesKicker":"ហេតុអ្វីជ្រើសរើស BCE សម្រាប់ការជួល","valuesTitle":"គ្រឿងចក្រដែលមកដល់រួចរាល់","values":[{"title":"ថែទាំដោយខ្លួនឯង","text":"រាល់រថយន្ត និងម៉ាស៊ីន ត្រូវបានថែទាំដោយក្រុមជាងថែទាំរបស់យើងផ្ទាល់ ដូច្នេះគ្រឿងចក្រមកដល់ការដ្ឋានរួចរាល់សម្រាប់ការងារ។"},{"title":"រួមបញ្ចូលអ្នកប្រតិបត្តិការ","text":"អ្នកប្រតិបត្តិការ និងអ្នកបើកបរដែលមានបទពិសោធន៍ មកជាមួយគ្រឿងចក្រ ដោយស្គាល់ម៉ាស៊ីន និងការដ្ឋានច្បាស់លាស់។"},{"title":"ដាក់ពង្រាយពាសពេញកម្ពុជា","text":"គ្រឿងចក្រត្រូវបានបញ្ជូនចេញពីបាត់ដំបង និងដាក់ពង្រាយទៅគម្រោងក្នុង 13 ខេត្ត និងរាជធានីភ្នំពេញ។"},{"title":"គាំទ្រដោយរោងចក្ររបស់យើង","text":"ការជួលអាចរួមបញ្ចូលជាមួយការផ្គត់ផ្គង់បេតុងលាយស្រេច និងការបូម ពីក្រុមតែមួយ ក្រោមកាលវិភាគតែមួយ។"}],"solutionsKicker":"ដំណោះស្រាយរបស់យើង","solutionsTitle":"ដំណោះស្រាយការជួល","solutionsLead":"ក្រុមយានយន្តសម្រាប់ជួលរបស់យើង គឺជាគ្រឿងចក្រដូចគ្នាដែលយើងប្រើលើការងាររបស់យើងផ្ទាល់ ថែទាំតាមស្តង់ដារដូចគ្នា និងអាចជួលជាមួយអ្នកប្រតិបត្តិការ។","solutions":[{"title":"ការជួលរថយន្តលាយបេតុង","text":"រថយន្តលាយបេតុងចំនួន 41 គ្រឿង សម្រាប់ការហៅប្រើប្រចាំថ្ងៃ ឬតាមកិច្ចសន្យាគម្រោង ជាមួយអ្នកបើកបរ និងការបញ្ជូនតាម GPS ពីរោងចក្ររបស់យើង។","alt":"រថយន្តលាយបេតុងរបស់ BCE កំពុងបញ្ចេញបេតុងនៅការដ្ឋាន"},{"title":"ការជួលរថយន្តបូមបេតុង","text":"រថយន្តបូមបេតុងចំនួនប្រាំបីគ្រឿង ជាមួយអ្នកប្រតិបត្តិការដែលមានបទពិសោធន៍ សម្រាប់ការចាក់កម្ពស់ខ្ពស់ និងកន្លែងចង្អៀត។","alt":"រថយន្តបូមបេតុងដងដៃរបស់ BCE ដាក់ពង្រាយសម្រាប់ការចាក់បេតុង"},{"title":"ការជួលម៉ាស៊ីនបោះសសរស្ដម្ភ","text":"ម៉ាស៊ីនបោះសសរស្ដម្ភ និងក្រុមកម្មករ អាចជួលបានសម្រាប់ការងារគ្រឹះ ដោយមានការគាំទ្រពីក្រុមថែទាំរបស់យើងផ្ទាល់។","alt":"ម៉ាស៊ីនបោះសសរស្ដម្ភ និងក្រុមកម្មកររបស់ BCE នៅការដ្ឋានគ្រឹះ"}],"capacityKicker":"ក្រុមយានយន្ត និងតំបន់គ្របដណ្តប់","capacityTitle":"ក្រុមយានយន្តរបស់យើង រួចរាល់ដាក់ពង្រាយ","capacityCopy":"រថយន្តលាយបេតុង រថយន្តបូម ម៉ាស៊ីនបោះសសរស្ដម្ភ និងគ្រឿងចក្រលើក សុទ្ធតែជាកម្មសិទ្ធិរបស់យើង ថែទាំដោយក្រុមការងាររបស់យើងផ្ទាល់ និងបញ្ជូនចេញពីបាត់ដំបង ជាមួយអ្នកប្រតិបត្តិការសម្រាប់រាល់ម៉ាស៊ីន។ ចំនួននេះត្រូវគ្នានឹងក្រុមយានយន្តនៅទំព័រ គ្រឿងចក្រ និងក្រុមយានយន្ត របស់យើង មិនមែនបញ្ជីអ្នកកណ្តាលទេ។","figures":[{"value":"41","label":"រថយន្តលាយបេតុងសម្រាប់ជួល"},{"value":"08","label":"រថយន្តបូមសម្រាប់ជួល"},{"value":"07","label":"ម៉ាស៊ីនបោះសសរស្ដម្ភសម្រាប់ជួល"},{"value":"13+","label":"ខេត្ត និងរាជធានីភ្នំពេញ"}],"prepare":["គ្រឿងចក្រ និងរយៈពេលជួល ជាមួយកាលបរិច្ឆេទ។","ទីតាំងការដ្ឋាន និងផ្លូវចូលសម្រាប់ការដាក់ពង្រាយ។","តើអ្នកត្រូវការអ្នកប្រតិបត្តិការ ប្រេងឥន្ធនៈ និងការថែទាំរួមបញ្ចូលឬអត់។","តម្រូវការលើក ឬសមត្ថភាព និងការងារដែលម៉ាស៊ីននឹងធ្វើ។"],"slug":"equipment-rental"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
ON CONFLICT(id) DO UPDATE SET status = excluded.status, sort = excluded.sort, data = excluded.data, km = excluded.km, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

