VALUES ('offerings:ready-mix-concrete', 'offerings', 'ready-mix-concrete', 'published', 0, '{"slug":"ready-mix-concrete","name":"Ready-Mix Concrete","tagline":"Supply and logistics","image":"/Image/bce/core-business-ready-mix.webp","bg":"#293e8a","fg":"#fff","intro":"Quality-controlled concrete from our four batching plants, each producing 70 m³ an hour, delivered to site by our own fleet of 41 mixer trucks.","details":["4 batching plants","70 m³/hr per plant","41 mixer trucks","Slump and strength testing"]}', '{"name":"បេតុងលាយស្រេច","tagline":"ការផ្គត់ផ្គង់ និងភស្តុភារ","intro":"បេតុងដែលគ្រប់គ្រងគុណភាពពីរោងចក្រលាយបេតុងទាំង ៤ របស់យើង ដែលមួយរោងចក្រផលិតបាន ៧០ m³/ម៉ោង ដឹកជញ្ជូនដល់ការដ្ឋានដោយកងរថយន្តលាយបេតុង ៤១ គ្រឿងផ្ទាល់ខ្លួន។","details":["រោងចក្រលាយបេតុង ៤","៧០ m³/ម៉ោង ក្នុងមួយរោងចក្រ","រថយន្តលាយបេតុង ៤១ គ្រឿង","ការតេស្តកម្រិតស្រុត និងកម្លាំងបេតុង"],"slug":"ready-mix-concrete"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
