VALUES ('offerings:piling', 'offerings', 'piling', 'published', 1, '{"slug":"piling","name":"Piling","tagline":"Foundations","image":"/Image/bce/core-business-piling.webp","bg":"#2a2927","fg":"#fff","intro":"Reinforced concrete piles for infrastructure and buildings, installed with our own piling rigs and backed by laboratory quality control.","details":["Reinforced concrete piles","Our own piling rigs","Infrastructure and buildings","Laboratory quality control"]}', '{"name":"ការបោះសសរស្ដម្ភ","tagline":"គ្រឹះសំណង់","intro":"សសរស្ដម្ភបេតុងអារម៉េសម្រាប់ហេដ្ឋារចនាសម្ព័ន្ធ និងអគារ បោះដោយម៉ាស៊ីនបោះសសរផ្ទាល់ខ្លួន និងធានាគុណភាពដោយមន្ទីរពិសោធន៍។","details":["សសរស្ដម្ភបេតុងអារម៉េ","ម៉ាស៊ីនបោះសសរស្ដម្ភផ្ទាល់ខ្លួន","ហេដ្ឋារចនាសម្ព័ន្ធ និងអគារ","ការត្រួតពិនិត្យគុណភាពក្នុងមន្ទីរពិសោធន៍"],"slug":"piling"}', '2026-11-23T06:32:26.379Z', '2026-11-23T06:32:26.379Z', 'seed')
